class TableError(Exception):
    def __init__(self, code: str, status: int = 400):
        super().__init__(code)
        self.code = code
        self.status = status


# Set by the server at start: does this user hold the game perks? A game
# asks, and never learns where the answer is kept.
PERKS = None


def _perks(uid) -> bool:
    try:
        return bool(PERKS and PERKS(int(uid)))
    except Exception:  # noqa: BLE001
        return False


def _people(room: dict, limit: int) -> list[dict]:
    return [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": False}
            for p in (p for p in room["players"] if not p.get("spectator"))][:limit]


# ═══════════════════════════ ألعاب الورق ═══════════════════════════

def _start_baloot(room: dict) -> dict:
    seats: list[dict | None] = [None, None, None, None]
    for index, person in enumerate(_people(room, 4)):
        seats[index] = person
    # يفتح على شاشة المقاعد: يختار كلٌّ مكانه وشريكه قبل أن تُوزَّع ورقة.
    return baloot.new_match(baloot.ensure_bots(seats), lobby=True)


_BALOOT_SEATED = {"bid", "card", "double", "declare", "baloot", "sitback",
                  "takeseat", "startmatch", "stepaway"}


def _act_baloot(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action in _BALOOT_SEATED and seat is None:
        raise TableError("watchingOnly", 403)
    try:
        if action == "bid":
            baloot.bid(state, seat, str(body.get("call") or ""), body.get("suit"))
        elif action == "card":
            baloot.play(state, seat, str(body.get("card") or ""))
        elif action == "double":
            baloot.double(state, seat, str(body.get("call") or "skip"))
        elif action == "declare":
            kinds = body.get("kinds")
            baloot.declare(state, seat, list(kinds) if kinds else None)
        elif action == "baloot":
            baloot.call_baloot(state, seat)
        elif action == "sitback":
            baloot.sit_back(state, seat)
        elif action == "stepaway":
            baloot.step_away(state, seat)
        elif action == "nexthand":
            baloot.next_hand(state)
        elif action == "takeseat":
            baloot.take_seat(state, seat, int(body.get("seat", seat)))
        elif action == "startmatch":
            baloot.start_match(state)
        else:
            raise TableError("badAction")
    except baloot.Illegal as err:
        raise TableError(err.code, 409) from None


def _start_tricks(mode: str):
    def start(room: dict) -> dict:
        seats: list[dict | None] = [None, None, None, None]
        for index, person in enumerate(_people(room, 4)):
            seats[index] = person
        return tricks.new_match(mode, tricks.ensure_bots(seats))
    return start


def _act_tricks(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action in {"bid", "card"} and seat is None:
        raise TableError("watchingOnly", 403)
    try:
        if action == "bid":
            tricks.bid(state, seat, int(body.get("amount") or 0), body.get("suit"))
        elif action == "card":
            tricks.play(state, seat, str(body.get("card") or ""))
        elif action == "nexthand":
            tricks.next_round(state)
        else:
            raise TableError("badAction")
    except tricks.Illegal as err:
        raise TableError(err.code, 409) from None


def _seat_in_players(state: dict, user_id: int) -> int | None:
    for index, person in enumerate(state["players"]):
        if not person.get("bot") and person.get("id") == user_id:
            return index
    return None


def _view_cards(view_fn):
    def view(state: dict, seat: int | None) -> dict:
        out = view_fn(state, seat)
        out["suits"] = cards.SUITS
        return out
    return view


# ═══════════════════════════ الشطرنج ═══════════════════════════

def _start_chess(room: dict) -> dict:
    people = _people(room, 2)
    seats = [
        people[0] if people else {"id": -1, "name": "🤖 الآلة", "photo": "", "bot": True},
        people[1] if len(people) > 1 else {"id": -2, "name": "🤖 الآلة", "photo": "", "bot": True},
    ]
    state = chess.new_game()
    state["players"] = seats            # 0 أبيض · 1 أسود
    state["level"] = "normal"
    state["game"] = "chess"
    return state


def _act_chess(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action == "level":
        wanted = str(body.get("level") or "normal")
        state["level"] = wanted if wanted in chess_ai.LEVELS else "normal"
        return
    if action != "card":
        raise TableError("badAction")
    if seat is None:
        raise TableError("watchingOnly", 403)
    want_turn = chess.WHITE if seat == 0 else chess.BLACK
    if state["turn"] != want_turn:
        raise TableError("notYourTurn", 409)
    if chess.status(state)["over"]:
        raise TableError("gameOver", 409)

    origin = str(body.get("from") or "")
    target = str(body.get("to") or "")
    promo = str(body.get("promo") or "Q").upper()[:1]
    for move in chess.legal_moves(state):
        if (chess.to_algebraic(move["from"]) == origin
                and chess.to_algebraic(move["to"]) == target
                and (not move.get("promo") or move["promo"] == promo)):
            chess.push(state, move)
            return
    raise TableError("illegalMove", 409)


def _view_chess(state: dict, seat: int | None) -> dict:
    info = chess.status(state)
    moves: dict[str, list[str]] = {}
    my_turn = seat is not None and state["turn"] == (chess.WHITE if seat == 0 else chess.BLACK)
    if my_turn and not info["over"]:
        for move in chess.legal_moves(state):
            moves.setdefault(chess.to_algebraic(move["from"]), []).append(
                chess.to_algebraic(move["to"]))
    squares = []
    for rank in range(7, -1, -1):
        for file in range(8):
            index = rank * 16 + file
            squares.append({"sq": chess.to_algebraic(index), "p": state["board"][index]})
    return {
        "game": "chess",
        "phase": "done" if info["over"] else "playing",
        "squares": squares,
        "turn": state["turn"],
        "seat": seat,
        "myColor": None if seat is None else (chess.WHITE if seat == 0 else chess.BLACK),
        "moves": moves,
        "check": info["result"] == "check",
        "result": info["result"],
        "winner": info["winner"],
        "level": state.get("level", "normal"),
        "history": state["moves"][-12:],
        "lastMove": state.get("last_move"),
        "players": [{**p, "seat": i} for i, p in enumerate(state["players"])],
    }


def _step_chess(state: dict) -> bool:
    """
    البحث يجري على **نسخة**: ألفا-بيتا ينقل القطع ويعيدها آلاف المرّات،
    ولو فعل ذلك بالرقعة الحقيقية لرآها من يستطلع الحالة في وضعٍ وسيط.
    ثمّ تُنفَّذ النقلة المختارة على الرقعة الحقيقية دفعةً واحدة.
    """
    if chess.status(state)["over"]:
        return False
    seat = 0 if state["turn"] == chess.WHITE else 1
    if not state["players"][seat].get("bot"):
        return False

    scratch = {**state, "board": list(state["board"]),
               "history": list(state["history"]), "moves": list(state["moves"])}
    move = chess_ai.choose(scratch, state.get("level", "normal"))
    if move is None:
        return False
    chess.push(state, move)
    return True


# ═════════════════════════ ألعاب شهد السريعة داخل التطبيق ═════════════════════════

def _two_players(room: dict) -> list[dict]:
    people = _people(room, 2)
    while len(people) < 2:
        people.append({"id": -(90 + len(people)), "name": "لاعب شهد", "photo": "", "bot": True})
    return people


def _start_xo(room: dict) -> dict:
    return {"game": "xo", "players": _two_players(room), "board": [""] * 9,
            "turn": 0, "phase": "playing", "winner": None, "rev": 0, "last": "ابدأ من أي مربع"}


def _xo_result(board: list[str]) -> int | None:
    lines = ((0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6))
    for a,b,c in lines:
        if board[a] and board[a] == board[b] == board[c]:
            return 0 if board[a] == "X" else 1
    return -1 if all(board) else None


def _act_xo(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action != "card" or seat is None or seat != state["turn"] or state["phase"] != "playing":
        raise TableError("notYourTurn", 409)
    try:
        cell = int(body.get("cell"))
    except (TypeError, ValueError):
        raise TableError("badAction") from None
    if cell not in range(9) or state["board"][cell]:
        raise TableError("illegalMove", 409)
    state["board"][cell] = "X" if seat == 0 else "O"
    result = _xo_result(state["board"])
    state["rev"] += 1
    if result is not None:
        state.update(phase="done", winner=result, last="تعادل" if result < 0 else f"فاز {state['players'][result]['name']}")
    else:
        state["turn"] = 1 - seat
        state["last"] = f"الدور على {state['players'][state['turn']]['name']}"


def _view_xo(state: dict, seat: int | None) -> dict:
    return {**state, "seat": seat,
            "canPlay": state["phase"] == "playing" and seat == state["turn"]}


def _step_xo(state: dict) -> bool:
    if state["phase"] != "playing" or not state["players"][state["turn"]].get("bot"):
        return False
    seat = state["turn"]
    available = [i for i, value in enumerate(state["board"]) if not value]
    mark = "X" if seat == 0 else "O"
    other = "O" if mark == "X" else "X"
    pick = None
    for wanted in (mark, other):
        for cell in available:
            board = list(state["board"]); board[cell] = wanted
            if _xo_result(board) in (0, 1): pick = cell; break
        if pick is not None: break
    pick = pick if pick is not None else (4 if 4 in available else random.choice(available))
    _act_xo(state, seat, "card", {"cell": pick})
    return True


def _start_rps(room: dict) -> dict:
    return {"game": "rps", "players": _two_players(room), "choices": {},
            "turn": 0, "phase": "playing", "winner": None, "rev": 0, "last": "اختر حركتك"}


def _resolve_rps(state: dict) -> None:
    if len(state["choices"]) < 2: return
    a, b = state["choices"]["0"], state["choices"]["1"]
    beats = {"rock": "scissors", "paper": "rock", "scissors": "paper"}
    winner = -1 if a == b else (0 if beats[a] == b else 1)
    state.update(phase="done", winner=winner, rev=state["rev"] + 1,
                 last="تعادل" if winner < 0 else f"فاز {state['players'][winner]['name']}")


def _act_rps(state: dict, seat: int | None, action: str, body: dict) -> None:
    choice = str(body.get("choice") or "")
    if action != "card" or seat is None or choice not in {"rock", "paper", "scissors"}:
        raise TableError("badAction")
    if state["phase"] != "playing" or str(seat) in state["choices"]:
        raise TableError("alreadyPlayed", 409)
    state["choices"][str(seat)] = choice
    state["last"] = "تم اختيارك — ننتظر المنافس"
    _resolve_rps(state)


def _view_rps(state: dict, seat: int | None) -> dict:
    mine = state["choices"].get(str(seat)) if seat is not None else None
    shown = state["choices"] if state["phase"] == "done" else ({str(seat): mine} if mine else {})
    return {**state, "choices": shown, "seat": seat, "picked": mine,
            "canPlay": state["phase"] == "playing" and seat is not None and not mine}


def _step_rps(state: dict) -> bool:
    if state["phase"] != "playing": return False
    moved = False
    for seat, person in enumerate(state["players"]):
        if person.get("bot") and str(seat) not in state["choices"]:
            state["choices"][str(seat)] = random.choice(("rock", "paper", "scissors")); moved = True
    _resolve_rps(state)
    return moved


# ═══════════════════════════ الكذّاب ═══════════════════════════

def _start_liar(room: dict) -> dict:
    # الكذّاب يفتح على شاشة المقاعد: القائد يختار من لاعبين إلى خمسة قبل أن
    # تُوزَّع ورقة، والشدّة نفسها تكبر وتصغر مع العدد.
    people = _people(room, liar.MAX_SEATS)
    for person in people:
        person["perks"] = _perks(person["id"])
    seats = int(room.get("seats") or liar.DEFAULT_SEATS)
    return liar.new_match(liar.ensure_bots(people), seats=seats)


def _act_liar(state: dict, seat: int | None, action: str, body: dict) -> None:
    if seat is None:
        raise TableError("watchingOnly", 403)
    try:
        if action == "card":
            picks = body.get("idx") or []
            liar.play(state, seat, [int(index) for index in picks])
        elif action == "challenge":
            liar.challenge(state, seat)
        elif action == "seats":
            liar.set_seats(state, seat, int(body.get("seats") or 4))
        elif action == "character":
            me = state["players"][seat]
            me["perks"] = _perks(me["id"]) if not me.get("bot") else False
            target = body.get("seat")
            liar.set_character(state, seat, str(body.get("char") or ""),
                               None if target is None else int(target), bool(me["perks"]))
        elif action == "mode":
            liar.set_mode(state, seat, str(body.get("mode") or ""))
        elif action == "peek":
            liar.peek(state, seat, int(body.get("target")))
        elif action == "hawk":
            liar.hawk(state, seat)
        elif action == "look":
            # أين يوجّه اللاعب كاميرته — يصل كثيرًا ويكلّف لا شيء، ولا يوقظ
            # نسخةً جديدة من الطاولة: يركب مع أوّل عرضٍ يخرج بعده.
            liar.set_look(state, seat, body.get("yaw"))
        elif action == "startmatch":
            liar.start_match(state)
        else:
            raise TableError("badAction")
    except (TypeError, ValueError):
        raise TableError("badPick", 400) from None
    except liar.Illegal as err:
        raise TableError(err.code, 409) from None


