def _start_habda(room: dict) -> dict:
    state = habda.new_match(_people(room, habda.MAX_SEATS), room.get("host", 0))
    if not room.get("bots", True):
        habda.set_bots(state, False)
    return state


def _act_habda(state: dict, seat: int | None, action: str, body: dict) -> None:
    try:
        habda.act(state, seat, action, body)
    except habda.Illegal as error:
        raise TableError(error.code, 409) from None


def _sit_habda(state: dict, room: dict, user_id: int) -> None:
    person = next((p for p in room["players"] if p["id"] == user_id), None)
    if person is None:
        raise TableError("notInRoom", 409)
    try:
        habda.sit(state, {"id": person["id"], "name": person["name"], "photo": person.get("photo", "")})
    except habda.Illegal as error:
        raise TableError(error.code, 409) from None
    person["spectator"] = False


ADAPTERS["habda"] = {
