    "step": habda.step, "pace": 0.5,
}


def _party(engine, **extra) -> dict:
    """محرّكات الحفلات (هبدة، كلمات…): تبدأ بمن في الغرفة، ولكلٍّ `Illegal` و`sit`."""
    def start(room: dict) -> dict:
        state = engine.new_match(_people(room, engine.MAX_SEATS), room.get("host", 0))
        if not room.get("bots", True) and hasattr(engine, "set_bots"):
            engine.set_bots(state, False)
        elif room.get("bots", True) and getattr(engine, "BOTS_ON_START", False):
            engine.set_bots(state, True)
        return state

    def act(state: dict, seat, action: str, body: dict) -> None:
        try:
            engine.act(state, seat, action, body)
        except engine.Illegal as error:
            raise TableError(error.code, 409) from None

    def sit(state: dict, room: dict, user_id: int) -> None:
        person = next((p for p in room["players"] if p["id"] == user_id), None)
        if person is None:
            raise TableError("notInRoom", 409)
        try:
            engine.sit(state, {"id": person["id"], "name": person["name"], "photo": person.get("photo", "")})
        except engine.Illegal as error:
            raise TableError(error.code, 409) from None
        person["spectator"] = False

    return {"start": start, "act": act, "sit": sit, "view": engine.view_for,
            "seat": engine.seat_of, "step": engine.step, "pace": 0.5, **extra}


