# ألعابٌ البوتُ فيها حشوٌ لا حاجة: تبدأ بلا بوتات، ويشغّلها صاحب الغرفة متى أراد.
# وفي غيرها (الورق والشطرنج وإكس أو…) البوت يملأ مقعدًا لا تقوم اللعبة بدونه، فيبقى مفعّلًا.
BOT_STAND_IN = "بوت شهد"

BOTLESS_DEFAULT = {"watch", "rasm", "habda", "kalimat", "salfa", "jasoos", "huroof", "mazad", "muhaqiq", "meen"}


# ═══════════════════════════ غرف المشاهدة ═══════════════════════════
#
# ليست لعبة: الغرفة نفسها بدردشتها ومايكها وقائمة حاضريها، وعليها «طاولة» تحفظ
# ماذا يُعرض وأين وصل. الوقت عند الخادم، وكل جهاز يضبط نفسه عليه.

# يضبطه الخادم: يصنع رابطًا موقّعًا لملفّ من مجلّد الفيديوهات.
watch_signer = None
watch_relay = None     # set by the server: an address that fetches a stream on the viewer's behalf
watch_quality = None   # set by the server: which sizes of a file are ready

_YOUTUBE = re.compile(r"(?:youtube(?:-nocookie)?\.com/(?:watch\?(?:[^#]*&)?v=|shorts/|live/|embed/|v/)|youtu\.be/)([\w-]{11})")


def _start_watch(room: dict) -> dict:
    return {"game": "watch", "host": room.get("host", 0), "title": room.get("title") or "غرفة مشاهدة",
            "source": None, "playing": False, "pos": 0.0, "at": time.time(), "free": False, "rev": 1}


def _watch_feed(state: dict, room: dict) -> None:
    # القيادة قد تنتقل حين يخرج صاحب الغرفة.
    state["host"] = room.get("host", 0)


def _watch_pos(state: dict) -> float:
    return float(state["pos"]) + (time.time() - float(state["at"]) if state["playing"] else 0.0)


def _watch_mark(state: dict, pos: float, playing: bool) -> None:
    state.update(pos=max(0.0, pos), at=time.time(), playing=playing)
    state["rev"] += 1


def _act_watch(state: dict, user: int, action: str, body: dict) -> None:
    is_host = user == state["host"]
    if action in ("wgame", "wgameoff"):
        # Anyone may start a game; only its opener or the host may swap or end one.
        running = state.get("popup")
        if running and not (is_host or running["by"] == user):
            raise TableError("notHost", 403)
        if action == "wgameoff":
            state["popup"] = None
            return
        game = re.sub(r"[^a-z_]", "", str(body.get("game") or ""))[:20]
        code = re.sub(r"[^A-Z0-9]", "", str(body.get("gcode") or "").upper())[:8]
        if not game or not code:
            raise TableError("badAction")
        state["popup"] = {"game": game, "code": code, "by": user}
        return
    if action == "wsync":
        # Whoever drove the film last reports where it really is, so a pause to
        # download on that device holds everyone back instead of leaving it behind.
        if state.get("leader", state["host"]) == user and state["playing"]:
            try:
                pos = float(body.get("pos"))
            except (TypeError, ValueError):
                return
            if pos == pos and 0 <= pos <= 86400 * 3:
                state.update(pos=pos, at=time.time())
        return
    if action == "wfree":
        if not is_host:
            raise TableError("notHost", 403)
        state["free"] = bool(body.get("on"))
        state["rev"] += 1
        return
    if not (is_host or state["free"]):
        raise TableError("notHost", 403)
    if action == "wtitle":
        title = " ".join(str(body.get("title") or "").split())[:50]
        if title:
            state["title"] = title
            state["rev"] += 1
        return
    if action == "wclear":
        state["source"] = None
        _watch_mark(state, 0.0, False)
        return
    if action == "wsource":
        kind = str(body.get("kind") or "link")
        if kind == "file":
            # الخادم تحقّق أن الطالب هو المالك وأن الملف موجود.
            name = str(body.get("name") or "")
            state["source"] = {"kind": "file", "ref": name, "name": name.rsplit("/", 1)[-1].rsplit(".", 1)[0][:80], "thumb": ""}
        elif kind == "stream":
            # A video spotted by the room's browser.
            link = str(body.get("link") or "").strip()[:4000]
            if not re.match(r"https?://\S+$", link, re.I):
                raise TableError("badLink")
            title = " ".join(str(body.get("title") or "").split())[:80]
            state["source"] = {"kind": "stream", "ref": link, "name": title or "فيديو من المتصفح", "thumb": "",
                               "referer": str(body.get("referer") or "")[:2000],
                               "relayed": bool(body.get("_relay")),
                               "hls": bool(re.search(r"m3u8|mpegurl", link, re.I))}
        else:
            link = str(body.get("link") or "").strip()[:2000]
            match = _YOUTUBE.search(link)
            if match:
                vid = match.group(1)
                state["source"] = {"kind": "youtube", "ref": vid, "name": "يوتيوب",
                                   "thumb": f"https://i.ytimg.com/vi/{vid}/mqdefault.jpg"}
            elif link.lower().startswith("https://") and " " not in link:
                state["source"] = {"kind": "url", "ref": link, "name": "فيديو برابط", "thumb": ""}
            elif link.lower().startswith("http://"):
                raise TableError("needHttps")
            else:
                raise TableError("badLink")
        state["leader"] = user
        _watch_mark(state, 0.0, True)
        return
    if not state["source"]:
        raise TableError("noVideo", 409)
    if action in ("wplay", "wpause", "wseek"):
        try:
            pos = float(body.get("pos"))
        except (TypeError, ValueError):
            pos = _watch_pos(state)
        if pos != pos or pos > 86400 * 3:
            pos = _watch_pos(state)
        playing = action == "wplay" or (action == "wseek" and state["playing"])
        state["leader"] = user
        _watch_mark(state, pos, playing)
        return
    raise TableError("badAction")


def _view_watch(state: dict, user: int) -> dict:
    source = state["source"]
    if source:
        source = dict(source)
        source["url"] = source["ref"] if source["kind"] in ("url", "stream") else ""
        if source["kind"] == "stream" and source.get("relayed") and watch_relay:
            source["relay"] = watch_relay(source["ref"], source.get("referer", ""))
        if source["kind"] == "file" and watch_signer:
            source["url"] = watch_signer(source["ref"])
            if watch_quality:
                source.update(watch_quality(source["ref"]))
    return {"game": "watch", "title": state["title"], "source": source, "playing": state["playing"],
            "pos": round(_watch_pos(state), 2), "rev": state["rev"], "free": state["free"],
            "isHost": user == state["host"], "canControl": user == state["host"] or state["free"],
            "popup": state.get("popup"), "leader": user == state.get("leader", state["host"])}


ADAPTERS["watch"] = {"start": _start_watch, "act": _act_watch, "view": _view_watch,
                     "seat": lambda state, user_id: user_id, "feed": _watch_feed,
                     "step": lambda state: False, "pace": 5.0}


def bots_default(game: str) -> bool:
    return game not in BOTLESS_DEFAULT


def has_bots(room: dict) -> bool:
    seats = (room.get("table") or {}).get("players")
    return isinstance(seats, list) and any(isinstance(p, dict) and p.get("bot") for p in seats)


def set_bots(room: dict, on: bool) -> str:
    """صاحب الغرفة يشغّل البوتات أو يطفئها في أيّ لحظة.

    يرجع: «live» إن طُبّق على الطاولة وهي تلعب، و«lobby» إن كانت لعبةَ مقاعد ثابتة
    لا تكمل بلا بوت فرجعت الغرفة للردهة، و«saved» إن حُفظ الاختيار للجولة القادمة.
    """
    room["bots"] = bool(on)
    state = room.get("table")
    if not state:
        return "saved"
    module = _ENGINES.get(room.get("game", ""))
    if module is not None and hasattr(module, "set_bots"):
        module.set_bots(state, bool(on))
        room["updated_at"] = time.time()
        return "live"
    if not on and has_bots(room):
        stop(room["code"])
        room.pop("table", None)
        room["phase"] = "lobby"
        return "lobby"
    return "saved"


def start_table(room: dict, game: str) -> dict:
    adapter = ADAPTERS.get(game)
    if not adapter:
        raise TableError("badGame")
    room["table"] = adapter["start"](room)
    room["game"] = game
    room["phase"] = "table"
    return room["table"]


def unseat(room: dict, user_id: int) -> None:
    """A player steps out to watch: a bot takes the seat (keeping its score), or the seat
    goes when the host plays without bots and the game can drop seats mid-match."""
    state = room.get("table")
    seats = state.get("players") if isinstance(state, dict) else None
    if not isinstance(seats, list):
        return
    for index, seat in enumerate(seats):
        if isinstance(seat, dict) and not seat.get("bot") and seat.get("id") == user_id:
            seats[index] = {**seat, "id": -(400 + index), "name": BOT_STAND_IN, "photo": "", "bot": True}
            break
    else:
        return
    module = _ENGINES.get(room.get("game", ""))
    if module is not None and hasattr(module, "set_bots") and not room.get("bots", True):
        module.set_bots(state, False)
    if isinstance(state.get("rev"), int):
        state["rev"] += 1
    room["updated_at"] = time.time()


def table_action(room: dict, user_id: int, action: str, body: dict) -> None:
    state = room.get("table")
    if not state:
        raise TableError("noTable", 409)
    adapter = ADAPTERS[room["game"]]
    if action == "rematch":
        start_table(room, room["game"])
        return
    if action == "sit" and adapter.get("sit"):
        adapter["sit"](state, room, user_id)
        return
    if adapter.get("feed"):
        adapter["feed"](state, room)
    adapter["act"](state, adapter["seat"](state, user_id), action, body)
    gamestats.observe(room)


def table_ink(room: dict, user_id: int, body: dict) -> dict:
    """The drawing channel (ارسمها): the artist's strokes in, everyone's unseen strokes out."""
    state = room.get("table")
    adapter = ADAPTERS.get(room.get("game", "")) or {}
    if not state or not adapter.get("ink"):
        raise TableError("noTable", 409)
    try:
        return adapter["ink"](state, adapter["seat"](state, user_id), body)
    except rasm.Illegal as error:
        raise TableError(error.code, 409) from None


def table_view(room: dict, user_id: int) -> dict | None:
    state = room.get("table")
    if not state:
        return None
    adapter = ADAPTERS[room["game"]]
    return adapter["view"](state, adapter["seat"](state, user_id))


# ═══════════════════════════ سائق البوتات ═══════════════════════════

def _has_people(room: dict) -> bool:
    """هل ما زال في الطاولة إنسانٌ حاضر؟

    الغرفةُ تبقى دقائق بعد خروج آخر لاعب، والبوتات كانت تُكمل المباراة فيها
    وحدها إلى ما لا نهاية: خيطٌ يعمل ونداءات تُكتب وطاولةٌ تُحدَّث ولا أحد
    ينظر. فالقاعدة صريحة: لا يلعب الآليّ إلّا وفي الطاولة إنسان.
    """
    people = {p["id"] for p in room.get("players", []) if not p.get("spectator")}
    if not people:
        return False
    seats = (room.get("table") or {}).get("players")
    if not isinstance(seats, list) or not seats:
        return True                      # لعبةٌ بلا مقاعد معلومة: الغرفة تكفي
    return any(not p.get("bot") and p.get("id") in people
               for p in seats if isinstance(p, dict))


def drive(room: dict, lock: asyncio.Lock) -> None:
    """
    يوقظ سائق البوتات لهذه الغرفة إن لم يكن يعمل.

    مهمّةٌ واحدة لكل غرفة، تنتهي وحدها حين يحين دور إنسان — فلا خيوطٌ
    تتراكم ولا غرفةٌ تُبقي مهمّةً بعد انتهائها.

    ويأخذ قفل الغرفة نفسه الذي تأخذه أفعال اللاعبين. وبدونه يقع ما وقع:
    البوت يحرّك بينما اللاعب يحرّك، فتختلط الحالة ويُرفض ما هو قانوني.
    """
    code = room["code"]
    existing = _drivers.get(code)
    if existing and not existing.done():
        return
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    _drivers[code] = loop.create_task(_run(room, lock))


async def _run(room: dict, lock: asyncio.Lock) -> None:
    code = room["code"]
    try:
        while True:
            state = room.get("table")
            adapter = ADAPTERS.get(room.get("game", ""))
            if not state or not adapter:
                return
            if not _has_people(room):
                return
            await asyncio.sleep(adapter["pace"])
            async with lock:
                # قد تُغلق الغرفة أو تُعاد الطاولة أثناء المهلة.
                if room.get("table") is not state:
                    return
                # التفكير يحجب الحلقة، فننقله إلى خيطٍ جانبي — والقفل قائم،
                # فلا يدخل لاعبٌ على الحالة وهي بين يدَي البوت.
                moved = await asyncio.to_thread(adapter["step"], state)
                state.pop("aiming", None)
                room["updated_at"] = time.time()
                gamestats.observe(room)
            if not moved:
                return
    except asyncio.CancelledError:
        raise
    except Exception:
        logger.exception("تعثّر سائق بوتات الغرفة %s", code)
    finally:
        if _drivers.get(code) is asyncio.current_task():
            _drivers.pop(code, None)


def stop(code: str) -> None:
    task = _drivers.pop(code, None)
    if task and not task.done():
        task.cancel()

