"""
شدّة البلوت: ٣٢ ورقة، وقيمها تختلف باختلاف نوع الجولة.

لماذا وحدةٌ مستقلّة: البلوت والطرنيب والهاند تلعب بالشدّة نفسها، فالأوراق
وأسماؤها ورسمها تُكتب مرّةً وتُستعمل في الثلاث.

الورقة نصٌّ من حرفين: الرتبة ثمّ اللون — «AH» = آس كبة. نصٌّ لا كائن لأنّها
تسافر في JSON إلى المتصفّح وترجع، ونصٌّ واحد أوضح من كائنٍ يُفكّك ويُركّب.
"""
from __future__ import annotations

import random

# الرموز الأربعة بأسمائها المتداولة في الخليج.
SUITS = {
    "S": {"key": "S", "sym": "♠", "ar": "صبيت", "color": "dark"},
    "H": {"key": "H", "sym": "♥", "ar": "كبة", "color": "red"},
    "D": {"key": "D", "sym": "♦", "ar": "ديناري", "color": "red"},
    "C": {"key": "C", "sym": "♣", "ar": "سيف", "color": "dark"},
}
SUIT_ORDER = ("S", "H", "D", "C")
RANKS = ("7", "8", "9", "10", "J", "Q", "K", "A")

DECK = tuple(f"{rank}{suit}" for suit in SUIT_ORDER for rank in RANKS)

# ── القيم ──
# في الحكم يقفز الشايب (J) والنِّتِش (9) من لون الحكم إلى رأس القائمة، وهذا
# ما يجعل الحكم لعبةً مختلفة عن الصن لا مجرّد لونٍ رابح.
TRUMP_VALUES = {"J": 20, "9": 14, "A": 11, "10": 10, "K": 4, "Q": 3, "8": 0, "7": 0}
PLAIN_VALUES = {"A": 11, "10": 10, "K": 4, "Q": 3, "J": 2, "9": 0, "8": 0, "7": 0}

# ترتيب القوّة داخل اللون الواحد (الأكبر يكسب اللِّفّة).
TRUMP_STRENGTH = {"J": 8, "9": 7, "A": 6, "10": 5, "K": 4, "Q": 3, "8": 2, "7": 1}
PLAIN_STRENGTH = {"A": 8, "10": 7, "K": 6, "Q": 5, "J": 4, "9": 3, "8": 2, "7": 1}

# ترتيب التسلسل للمشاريع (سرا/خمسين/مية): تسلسلٌ طبيعي لا قيمة له في اللعب.
SEQUENCE_ORDER = {rank: index for index, rank in enumerate(RANKS)}


def rank_of(card: str) -> str:
    return card[:-1]


def suit_of(card: str) -> str:
    return card[-1]


def value(card: str, trump: str | None) -> int:
    """قيمة الورقة في الحساب. `trump=None` يعني صن."""
    if trump and suit_of(card) == trump:
        return TRUMP_VALUES[rank_of(card)]
    return PLAIN_VALUES[rank_of(card)]


def strength(card: str, trump: str | None) -> int:
    if trump and suit_of(card) == trump:
        return TRUMP_STRENGTH[rank_of(card)]
    return PLAIN_STRENGTH[rank_of(card)]


def shuffled(rng: random.Random | None = None) -> list[str]:
    deck = list(DECK)
    (rng or random).shuffle(deck)
    return deck


def sort_hand(hand: list[str], trump: str | None) -> list[str]:
    """ترتيبٌ للعرض: الحكم أوّلًا ثمّ بقيّة الألوان، والأقوى في المقدّمة."""
    def key(card: str) -> tuple:
        suit = suit_of(card)
        is_trump = 0 if (trump and suit == trump) else 1
        return (is_trump, SUIT_ORDER.index(suit), -strength(card, trump))
    return sorted(hand, key=key)


def label(card: str) -> str:
    """اسمٌ عربيّ مختصر للورقة — للسجلّ ورسائل البوت."""
    names = {"A": "آس", "K": "شيخ", "Q": "بنت", "J": "ولد", "10": "ديك"}
    return f"{names.get(rank_of(card), rank_of(card))} {SUITS[suit_of(card)]['ar']}"


def trick_winner(plays: list[tuple[int, str]], lead_suit: str, trump: str | None) -> int:
    """صاحب اللِّفّة: أعلى ورقة حكم، وإلّا فأعلى ورقة من لون البداية."""
    best_seat, best_key = plays[0][0], (-1, -1)
    for seat, card in plays:
        suit = suit_of(card)
        tier = 2 if (trump and suit == trump) else (1 if suit == lead_suit else 0)
        key = (tier, strength(card, trump))
        if key > best_key:
            best_seat, best_key = seat, key
    return best_seat

