"""
أساسٌ مشترك لألعاب الحفلات الجديدة (الجاسوس بالصور، سباق الحروف، المزاد).

كل ما يخصّ اللاعب في الجولة يُحفظ بمعرّفه (id) لا برقم مقعده: فإذا خرجت البوتات
أو جلس متأخّر مكان بوت لا يُعاد ترقيم شيء. البوت معرّفه سالب.
"""
from __future__ import annotations

import random
import time

BOT_NAMES = ["أبو سعد", "عبدالرحمن", "نورة", "فهد", "ريم", "سلطان", "جود", "مشاعل", "تركي", "لمى"]


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def seats(people: list[dict], limit: int) -> list[dict]:
    return [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": False, "score": 0}
            for p in people[:limit]]


def fill_bots(state: dict, minimum: int) -> None:
    players = state["players"]
    taken = {p["name"] for p in players}
    names = [n for n in BOT_NAMES if n not in taken]
    random.shuffle(names)
    used = {p["id"] for p in players}
    while len(players) < minimum:
        bot_id = -(200 + len(players))
        while bot_id in used:
            bot_id -= 1
        used.add(bot_id)
        players.append({"id": bot_id, "name": names.pop() if names else f"بوت {len(players)}",
                        "photo": "", "bot": True, "score": 0})


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot") and seat.get("id") == user_id:
            return index
    return None


def host_seat(state: dict) -> int | None:
    host = seat_of(state, state.get("host", 0))
    if host is not None:
        return host
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot"):
            return index
    return None


def humans(state: dict) -> list[dict]:
    return [p for p in state["players"] if not p.get("bot")]


def bots(state: dict) -> list[dict]:
    return [p for p in state["players"] if p.get("bot")]


def sit(state: dict, person: dict, open_phases: tuple, max_seats: int) -> None:
    """متأخّرٌ يجلس: مكان بوتٍ إن وُجد (ويرث نقاطه)، وإلا مقعدٌ جديد بين الجولات."""
    if seat_of(state, person["id"]) is not None:
        return
    if state["phase"] not in open_phases:
        raise Illegal("waitForRound")
    seat = {"id": person["id"], "name": person["name"], "photo": person.get("photo", ""), "bot": False, "score": 0}
    for index, old in enumerate(state["players"]):
        if old.get("bot"):
            if state["phase"] != "setup":
                seat["score"] = old["score"]
            state["players"][index] = seat
            state["rev"] += 1
            return
    if len(state["players"]) >= max_seats:
        raise Illegal("full")
    state["players"].append(seat)
    state["rev"] += 1


def set_bots(state: dict, on: bool, minimum: int, quiet_phases: tuple) -> None:
    """تشغيل البوتات يملأ حتى الحدّ الأدنى. إطفاؤها يُخرجها فورًا بين الجولات، وإلا عند الجولة التالية."""
    state["no_bots"] = not on
    if on:
        fill_bots(state, minimum)
    elif state["phase"] in quiet_phases:
        drop_bots(state)
    state["rev"] += 1


def drop_bots(state: dict) -> None:
    if state.get("no_bots"):
        state["players"] = [p for p in state["players"] if not p.get("bot")]


def player_view(state: dict, done: set | None = None) -> list[dict]:
    done = done or set()
    return [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": bool(p.get("bot")),
             "score": p["score"], "done": p["id"] in done} for p in state["players"]]


def base_view(state: dict, seat: int | None) -> dict:
    t = now()
    host = host_seat(state)
    return {
        "game": state["game"],
        "phase": state["phase"],
        "seat": seat,
        "me": state["players"][seat]["id"] if seat is not None else None,
        "isHost": seat is not None and seat == host,
        "hostName": state["players"][host]["name"] if host is not None else "",
        "rounds": state["rounds"],
        "round": state["round"],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state.get("deadline") else 0,
        "rev": state["rev"],
        "roster": list(BOT_NAMES),
    }


def set_roster(state: dict, names: list, max_seats: int) -> None:
    """صاحب الطاولة يختار بنفسه من يلعب معه من البوتات بأسمائهم الثابتة (قبل البدء فقط)."""
    if state["phase"] != "setup":
        raise Illegal("tooLate")
    wanted = [n for n in BOT_NAMES if n in {str(x) for x in (names or [])}]
    humans_only = [p for p in state["players"] if not p.get("bot")]
    kept = {p["name"]: p for p in state["players"] if p.get("bot")}
    room_left = max(0, max_seats - len(humans_only))
    used = {p["id"] for p in state["players"]}
    out = list(humans_only)
    for name in wanted[:room_left]:
        bot = kept.get(name)
        if bot is None:
            bot_id = -(200 + BOT_NAMES.index(name))
            while bot_id in used:
                bot_id -= 20
            used.add(bot_id)
            bot = {"id": bot_id, "name": name, "photo": "", "bot": True, "score": 0}
        out.append(bot)
    state["players"] = out
    state["no_bots"] = not wanted
    state["rev"] += 1

