            raise Illegal("badBid")
        # آخر معلنٍ لا يجوز أن يجعل المجموع ثمانيةً بالضبط، وإلّا نجح الكلّ
        # وضاع معنى المخاطرة — قاعدةٌ متّبعة في أكثر الموائد.
        if len(state["bids"]) == 3 and sum(state["bids"].values()) + amount == HAND_SIZE:
            raise Illegal("badLastBid")
        state["bids"][seat] = amount
        state["turn"] = (seat + 1) % 4
        if len(state["bids"]) == 4:
            state["phase"] = "playing"
            state["turn"] = (state["dealer"] + 1) % 4
        return state

    # طرنيب
    if amount == 0:
        state["bids"][seat] = 0
    else:
        if not 5 <= amount <= HAND_SIZE:
            raise Illegal("badBid")
        highest = max(state["bids"].values(), default=0)
        if amount <= highest:
            raise Illegal("bidTooLow")
        if suit not in cards.SUITS:
            raise Illegal("badSuit")
        state["bids"][seat] = amount
        state["declarer"] = seat
        state["contract"] = amount
        state["trump"] = suit

    state["turn"] = (seat + 1) % 4
    if len(state["bids"]) == 4:
        if state["declarer"] is None:
            # مرّ الجميع: الموزّع مجبورٌ على شراء الحدّ الأدنى، فلا تموت اليد.
            forced = state["dealer"]
            state["declarer"] = forced
            state["contract"] = 5
            state["bids"][forced] = 5
            state["trump"] = _best_suit(state["hands"][forced])
        state["phase"] = "playing"
        state["turn"] = state["declarer"]
        for seat_index in SEATS:
            state["hands"][seat_index] = cards.sort_hand(state["hands"][seat_index], state["trump"])
    return state


def _best_suit(hand: list[str]) -> str:
    counts = {suit: 0 for suit in cards.SUIT_ORDER}
    for card in hand:
        counts[suit_of(card)] += 1
    return max(counts, key=lambda s: (counts[s], sum(
        cards.PLAIN_STRENGTH[cards.rank_of(c)] for c in hand if suit_of(c) == s)))


# ═══════════════════════════ اللعب ═══════════════════════════

def legal_moves(state: dict, seat: int) -> list[str]:
    """الاتّباع واجب. ومن لا يملك اللون فحرٌّ — لا قصَّ إجباريًّا هنا."""
    hand = state["hands"][seat]
    if not state["trick"]:
        return list(hand)
    same = [c for c in hand if suit_of(c) == state["lead_suit"]]
    return same or list(hand)


def play(state: dict, seat: int, card: str) -> dict:
    if state["phase"] != "playing":
        raise Illegal("notPlaying")
    if seat != state["turn"]:
        raise Illegal("notYourTurn")
    if card not in state["hands"][seat]:
        raise Illegal("notYours")
    if card not in legal_moves(state, seat):
        raise Illegal("mustFollow")

    state["hands"][seat].remove(card)
    if not state["trick"]:
        state["lead_suit"] = suit_of(card)
    state["trick"].append([seat, card])

    if len(state["trick"]) < 4:
        state["turn"] = (seat + 1) % 4
        return state

    winner = cards.trick_winner([(s, c) for s, c in state["trick"]],
                                state["lead_suit"], state["trump"])
    state["won"][winner] += 1
    state["tricks"].append({"plays": state["trick"], "winner": winner})
    state["trick"] = []
    state["lead_suit"] = None
    state["turn"] = winner

    if all(not state["hands"][s] for s in SEATS):
        _score(state)
    return state


def _score(state: dict) -> None:
    if state["game"] == "tarneeb":
        team = team_of(state["declarer"])
        made = state["won"][team] + state["won"][team + 2]
        gained = [0, 0]
        if made >= state["contract"]:
            gained[team] = made
        else:
            gained[team] = -state["contract"]
        other = 1 - team
        gained[other] = state["won"][other] + state["won"][other + 2]
        state["scores"][0] += gained[0]
        state["scores"][1] += gained[1]
        state["last_round"] = {"contract": state["contract"], "made": made,
                               "declarer": state["declarer"], "gained": gained,
                               "failed": made < state["contract"]}
        state["phase"] = "round_done"
        if max(state["scores"]) >= TARNEEB_TARGET and state["scores"][0] != state["scores"][1]:
            state["phase"] = "match_done"
            state["winner_team"] = 0 if state["scores"][0] > state["scores"][1] else 1
        return

    gained = [0, 0, 0, 0]
    for seat in SEATS:
        promised = state["bids"].get(seat, 0)
        took = state["won"][seat]
        gained[seat] = (10 + took) if took == promised else -abs(took - promised)
        state["scores"][seat] += gained[seat]
    state["last_round"] = {"bids": dict(state["bids"]), "won": dict(state["won"]),
                           "gained": gained}
    state["phase"] = "round_done"
    if state["round_no"] >= HAND_ROUNDS:
        state["phase"] = "match_done"
        best = max(state["scores"])
        state["winner_seat"] = state["scores"].index(best)


def next_round(state: dict) -> dict:
    if state["phase"] != "round_done":
        raise Illegal("roundNotDone")
    state["dealer"] = (state["dealer"] + 1) % 4
    return start_round(state)


# ═══════════════════════════ العرض ═══════════════════════════

def view_for(state: dict, seat: int | None) -> dict:
    trump = state["trump"]
    view = {
        "game": state["game"],
        "phase": state["phase"],
        "trump": trump,
        "trumpSuit": cards.SUITS[trump] if trump else None,
        "declarer": state["declarer"],
        "contract": state["contract"],
        "dealer": state["dealer"],
        "turn": state.get("turn"),
        "roundNo": state["round_no"],
        "rounds": HAND_ROUNDS if state["game"] == "hand" else None,
        "scores": state["scores"],
        "target": TARNEEB_TARGET if state["game"] == "tarneeb" else None,
        "seat": seat,
        "bids": {str(k): v for k, v in state["bids"].items()},
        "won": {str(k): v for k, v in state["won"].items()},
        "players": [
            {**{k: p.get(k) for k in ("id", "name", "photo", "bot")},
             "seat": index, "team": team_of(index),
             "cards": len(state["hands"].get(index, []))}
            for index, p in enumerate(state["players"])
        ],
        "trick": state["trick"],
        "leadSuit": state["lead_suit"],
        "tricksPlayed": len(state["tricks"]),
        "lastTrick": state["tricks"][-1] if state["tricks"] else None,
        "lastRound": state.get("last_round"),
        "winnerTeam": state.get("winner_team"),
        "winnerSeat": state.get("winner_seat"),
    }
    if seat is not None and seat in state["hands"]:
        view["hand"] = cards.sort_hand(state["hands"][seat], trump)
        view["legal"] = (legal_moves(state, seat)
                         if state["phase"] == "playing" and state["turn"] == seat else [])
    else:
        view["hand"] = []
        view["legal"] = []
    return view


# ═══════════════════════════ الذكاء الآلي ═══════════════════════════

def _strength(hand: list[str], trump: str | None) -> float:
    """تقديرٌ تقريبيّ لعدد اللِّفّات التي تحملها اليد."""
    total = 0.0
    for suit in cards.SUIT_ORDER:
        same = [c for c in hand if suit_of(c) == suit]
        for card in same:
            rank = cards.rank_of(card)
            if suit == trump:
                total += {"A": 1.0, "K": 0.9, "Q": 0.7, "J": 0.6, "10": 0.5}.get(rank, 0.35)
            else:
                total += {"A": 0.9, "K": 0.6, "Q": 0.3, "J": 0.15}.get(rank, 0.0)
    return total


def choose_bid(state: dict, seat: int) -> dict:
    hand = state["hands"][seat]
    if state["game"] == "hand":
        want = int(round(_strength(hand, state["trump"])))
        want = max(0, min(HAND_SIZE, want))
        if len(state["bids"]) == 3 and sum(state["bids"].values()) + want == HAND_SIZE:
            want = want + 1 if want < HAND_SIZE else want - 1
        return {"amount": want}

    suit = _best_suit(hand)
    can = int(_strength(hand, suit) + 0.5)
    highest = max(state["bids"].values(), default=0)
    if can >= max(5, highest + 1) and can <= HAND_SIZE:
        return {"amount": max(5, highest + 1), "suit": suit}
    return {"amount": 0}


def choose_card(state: dict, seat: int) -> str:
    options = legal_moves(state, seat)
    if len(options) == 1:
        return options[0]
    trump = state["trump"]
    trick = state["trick"]

    if not trick:
        # ابدأ بأقوى ورقةٍ في لونٍ ليس الحكم، فهي أقرب ما يكسب.
        plain = [c for c in options if suit_of(c) != trump] or options
        return max(plain, key=lambda c: cards.strength(c, trump))

    lead = state["lead_suit"]
    winner = cards.trick_winner([(s, c) for s, c in trick], lead, trump)
    partner_wins = state["game"] == "tarneeb" and team_of(winner) == team_of(seat)
    if partner_wins and len(trick) == 3:
        return min(options, key=lambda c: cards.strength(c, trump))

    winners = []
    for card in options:
        plays = [(s, c) for s, c in trick] + [(99, card)]
        if cards.trick_winner(plays, lead, trump) == 99:
            winners.append(card)
    if winners:
        return min(winners, key=lambda c: cards.strength(c, trump))
    return min(options, key=lambda c: cards.strength(c, trump))


def step(state: dict) -> bool:
    if state.get("phase") not in {"bidding", "playing"}:
        return False
    seat = state.get("turn")
    if seat is None or not state["players"][seat].get("bot"):
        return False
    if state["phase"] == "bidding":
        call = choose_bid(state, seat)
        bid(state, seat, call["amount"], call.get("suit"))
    else:
        play(state, seat, choose_card(state, seat))
    return True

