"""
Rasm - draw it, they guess it.

Players take turns at the easel in a random order. The artist is offered
three words (easy, medium and hard, worth more the harder they are), picks
one, and draws it while everyone else types guesses. A right guess scores by
how quickly it came (the first one earns a bonus) and pays the artist for
every friend who got it. Letters of the word are uncovered as time runs out,
a near miss is whispered to its author alone, and some turns bring a twist:
one continuous line, drawing blind, half the time for double points, one
colour only, or no eraser.

The server holds the word and the ink. Guessers only ever learn the word's
pattern (and the letters uncovered) until they guess it or the turn ends. The
ink (the artist's strokes) travels on its own light channel (`ink`) so a
drawing can be followed several times a second without sending the whole
room each time.

Bots fill empty seats up to three so one person can play; they guess but
never draw.

Two more modes share the room, the players and the scoreboard:
- trace: everyone re-inks the same random line drawing at once. The server
  measures each tracing against the drawing (coverage and precision within a
  small radius) as it arrives, so the first ones to come really close finish
  first and earn the most.
- color: everyone colours the same line drawing with bucket fills, then the
  room votes for the best one (no voting for yourself).
"""
from __future__ import annotations

import json
import pathlib
import random
import re
import time
import unicodedata

HERE = pathlib.Path(__file__).resolve().parent
_WORDS = json.loads((HERE / "content" / "words.json").read_text(encoding="utf-8"))
_LOCALE = json.loads((HERE / "locales" / "ar.json").read_text(encoding="utf-8"))
PACKS: dict[str, dict] = {p["key"]: p for p in _WORDS["packs"]}
MIX = "mix"

TURN_CHOICES = (1, 2, 3)          # how many times each player draws
DEFAULT_TURNS = 2
SECOND_CHOICES = (60, 80, 100)
DEFAULT_SECONDS = 80
MIN_SEATS = 3
MAX_SEATS = 10

CHOOSE_SECONDS = 15
ABSENT_SECONDS = 25               # an artist who has not drawn a line by then is away: the turn ends
REVEAL_SECONDS = 8
GUESS_GAP = 0.7
TWIST_CHANCE = 0.4
TWISTS = ("oneline", "blind", "half", "mono", "noerase")

GUESS_BASE = 100
GUESS_SPEED = 200
FIRST_BONUS = 50
ARTIST_PER_GUESS = 60
ALL_GUESSED_BONUS = 80
LIKE_POINTS = 15
LEVEL_FACTOR = {1: 1.0, 2: 1.3, 3: 1.6}

# The canvas is 1000 x 750 units; every stroke point is a pair of integers on it.
INK_W = 1000
INK_H = 750
COLORS = 13                       # palette size (index 12 is the eraser: paper white)
ERASER = 12
MAX_OPS = 5000
MAX_POINTS = 24000
MAX_OP_POINTS = 96
INK_PAGE = 800


MODES = ("guess", "trace", "color")
_DRAWINGS = json.loads((HERE / "content" / "drawings.json").read_text(encoding="utf-8"))["drawings"]
ART: dict[str, dict] = {d["key"]: d for d in _DRAWINGS}
TRACE_RADIUS = 18                 # canvas units: ink this close to a line counts as on it
TRACE_STEP = 9                    # both drawings are resampled at this spacing before comparing
TRACE_FINISH = 80                 # percent: a tracing this close finishes the round for its author
TRACE_RANK_POINTS = (300, 230, 180, 140, 110, 90, 75, 60, 50, 40)
TRACE_PARTIAL_FROM = 30           # unfinished tracings above this still earn a little
TRACE_MAX_POINTS = 2400
TRACE_GAP = 0.35                  # seconds between two scored submissions of one player
TRACE_SECONDS = {60: 45, 80: 60, 100: 75}
COLOR_EXTRA_SECONDS = 40
COLOR_VOTE_SECONDS = 25
COLOR_PALETTE = 24                # fill colours the client offers (indexes 0..23)
COLOR_MIN_FILLS = 3
MAX_FILLS = 240
VOTE_POINTS = 100
COLOR_EFFORT_POINTS = 40
RESULT_SECONDS = 9


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


# ============================== words ==============================

_MARKS = re.compile(r"[\u064b-\u065f\u0670\u0640]")


def _fold(text: str) -> str:
    value = unicodedata.normalize("NFKC", str(text or "")).strip().lower()
    value = _MARKS.sub("", value)
    return (value.replace("\u0623", "\u0627").replace("\u0625", "\u0627").replace("\u0622", "\u0627")
            .replace("\u0629", "\u0647").replace("\u0649", "\u064a").replace("\u0624", "\u0648")
            .replace("\u0626", "\u064a"))


def normalize(text: str) -> str:
    """Letters only, each word without its article, so two spellings of one phrase agree."""
    words = []
    for part in _fold(text).split():
        part = "".join(ch for ch in part if ch.isalnum())
        if part.startswith("\u0627\u0644") and len(part) > 3:
            part = part[2:]
        if part:
            words.append(part)
    return "".join(words)


def _distance(a: str, b: str) -> int:
    if abs(len(a) - len(b)) > 2:
        return 3
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def _answers(word: dict) -> list[str]:
    return [normalize(v) for v in [word["w"], *(word.get("alt") or [])] if normalize(v)]


def judge(word: dict, text: str) -> str:
    """'right', 'close' (a letter or two away) or 'wrong'."""
    guess = normalize(text)
    if not guess:
        return "wrong"
    answers = _answers(word)
    if guess in answers:
        return "right"
    for answer in answers:
        limit = 1 if len(answer) < 7 else 2
        if len(answer) >= 3 and _distance(guess, answer) <= limit:
            return "close"
    return "wrong"


def _pool(pack: str) -> list[dict]:
    keys = list(PACKS) if pack == MIX else [pack]
    seen: set[str] = set()
    out = []
    for key in keys:
        for word in PACKS[key]["words"]:
            if word["w"] in seen:
                continue
            seen.add(word["w"])
            out.append({**word, "pack": key})
    return out


def _options(state: dict) -> list[dict]:
    """One word of each level, never one already drawn this match."""
    pool = [w for w in _pool(state["pack"]) if w["w"] not in state["used"]]
    if len(pool) < 3:
        state["used"] = []
        pool = _pool(state["pack"])
    picked = []
    for level in (1, 2, 3):
        choices = [w for w in pool if int(w.get("d", 2)) == level and w not in picked]
        if not choices:
            choices = [w for w in pool if w not in picked]
        picked.append(random.choice(choices))
    return picked


def pattern(word: str, shown: list[int]) -> str:
    """The word with its hidden letters as underscores (spaces kept)."""
    return "".join(ch if (ch == " " or i in shown) else "_" for i, ch in enumerate(word))


# ============================== match ==============================

def _bot_names() -> list[str]:
    return list(_LOCALE.get("bots") or ["Bot"])


def _seat(person: dict, bot: bool = False) -> dict:
    return {"id": person["id"], "name": person["name"], "photo": person.get("photo", ""), "bot": bot,
            "score": 0, "drawn": 0, "right": 0, "likes": 0, "fastest": 0.0}


def new_match(people: list[dict], host: int) -> dict:
    """`people`: [{id, name, photo}] humans in the room, in join order."""
    seats = [_seat(p) for p in people[:MAX_SEATS]]
    _fill_bots(seats)
    return {
        "game": "rasm", "host": host, "players": seats,
        "pack": MIX, "turns": DEFAULT_TURNS, "seconds": DEFAULT_SECONDS, "twists": True,
        "phase": "setup", "phase_at": now(), "deadline": 0.0,
        "schedule": [], "round": 0, "drawer": None, "options": [], "rerolled": False,
        "word": None, "twist": None, "shown": [], "solved": {}, "gains": {}, "likes": [],
        "close": {}, "feed": [], "last_guess": {}, "used": [],
        "ink": [], "ink_points": 0, "ink_turn": "", "strokes": 0,
        "bot_due": {}, "gallery": [], "rev": 0,
        "mode": "guess", "art": None, "art_used": [], "art_rounds": 0,
        "trace": {}, "trace_ink": {}, "last_trace": {}, "fills": {}, "votes": {},
    }


def _fill_bots(seats: list[dict]) -> None:
    names = [n for n in _bot_names() if n not in {s["name"] for s in seats}]
    random.shuffle(names)
    while len(seats) < MIN_SEATS:
        index = len(seats)
        seats.append(_seat({"id": -(300 + index), "name": names.pop() if names else f"Bot {index}"}, bot=True))


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot") and seat.get("id") == user_id:
            return index
    return None


def host_seat(state: dict) -> int | None:
    host = seat_of(state, state.get("host", 0))
    if host is not None:
        return host
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot"):
            return index
    return None


def sit(state: dict, person: dict) -> None:
    """A late arrival takes a bot's seat, or a new one; they draw at the end of the order."""
    if seat_of(state, person["id"]) is not None:
        return
    seat = _seat(person)
    index = next((i for i, s in enumerate(state["players"]) if s.get("bot") and i != state.get("drawer")), None)
    if state.get("no_bots"):
        index = None
    if index is not None:
        seat["score"] = state["players"][index]["score"] if state["phase"] != "setup" else 0
        state["players"][index] = seat
    else:
        if len(state["players"]) >= MAX_SEATS:
            raise Illegal("full")
        state["players"].append(seat)
        index = len(state["players"]) - 1
    if state["phase"] not in ("setup", "final") and state.get("mode", "guess") == "guess":
        state["schedule"].extend([index] * state["turns"])
    state["bot_due"].pop(str(index), None)
    state["rev"] += 1


def _humans(state: dict) -> list[int]:
    return [i for i, p in enumerate(state["players"]) if not p.get("bot")]


def _guessers(state: dict) -> list[int]:
    return [i for i in range(len(state["players"])) if i != state["drawer"]]


# ============================== bots on / off ==============================
#
# The host decides whether bots play. Off: they leave at once, even mid-turn, and every
# record keyed by seat number is renumbered so nothing points at a seat that is gone.

def _renumber(keep: list[int]) -> dict[int, int]:
    return {old: new for new, old in enumerate(keep)}


def _keys(table: dict, new: dict[int, int]) -> dict:
    out = {}
    for key, value in (table or {}).items():
        try:
            seat = int(key)
        except (TypeError, ValueError):
            continue
        if seat in new:
            out[str(new[seat])] = value
    return out


def _seats(items, new: dict[int, int]) -> list:
    return [new[i] for i in (items or []) if isinstance(i, int) and i in new]


def set_bots(state: dict, on: bool) -> None:
    """On: bots fill the table up to three seats (they guess, never draw). Off: every bot leaves now."""
    state["no_bots"] = not on
    if on:
        _fill_bots(state["players"])
        state["rev"] += 1
        return
    keep = [i for i, p in enumerate(state["players"]) if not p.get("bot")]
    if len(keep) == len(state["players"]):
        return
    new = _renumber(keep)
    state["players"] = [state["players"][i] for i in keep]
    state["schedule"] = _seats(state["schedule"], new)
    if state.get("drawer") is not None:
        state["drawer"] = new.get(state["drawer"])
    for key in ("solved", "gains", "close", "last_guess", "bot_due", "trace", "trace_ink", "last_trace", "fills", "votes"):
        state[key] = _keys(state.get(key), new)
    state["votes"] = {k: new[v] for k, v in (state.get("votes") or {}).items() if v in new}
    state["likes"] = _seats(state.get("likes"), new)
    for entry in state.get("feed", []):
        if entry.get("seat") is not None:
            entry["seat"] = new.get(entry["seat"])
    for entry in state.get("gallery", []):
        if entry.get("seat") is not None:
            entry["seat"] = new.get(entry["seat"])
    state["rev"] += 1
    # Every human who was left to guess may already have it: the turn ends instead of waiting on nobody.
    guessers = _guessers(state) if state.get("drawer") is not None else []
    if state["phase"] == "draw" and guessers and len(state["solved"]) >= len(guessers):
        _end_turn(state)


def _log(state: dict, kind: str, seat: int | None, text: str = "") -> None:
    state["feed"].append({"kind": kind, "seat": seat, "text": text, "at": int(now() * 1000)})
    del state["feed"][:-30]


def _gain(state: dict, seat: int, points: int) -> None:
    state["players"][seat]["score"] += points
    key = str(seat)
    state["gains"][key] = state["gains"].get(key, 0) + points


def _start(state: dict) -> None:
    if state.get("mode", "guess") != "guess":
        _start_art(state)
        return
    order = _humans(state)
    random.shuffle(order)
    state["schedule"] = [seat for _ in range(state["turns"]) for seat in order]
    state["round"] = 0
    for p in state["players"]:
        p.update(score=0, drawn=0, right=0, likes=0, fastest=0.0)
    state["gallery"] = []
    state["used"] = []
    _next_turn(state)


def _next_turn(state: dict) -> None:
    # Someone who left the room keeps their seat, but a seat now held by a bot does not draw.
    while state["round"] < len(state["schedule"]) and state["players"][state["schedule"][state["round"]]].get("bot"):
        state["schedule"].pop(state["round"])
    if state["round"] >= len(state["schedule"]):
        state.update(phase="final", phase_at=now(), deadline=0.0, drawer=None, word=None, options=[])
        state["rev"] += 1
        return
    drawer = state["schedule"][state["round"]]
    state["round"] += 1
    state.update(
        phase="choose", phase_at=now(), deadline=now() + CHOOSE_SECONDS, drawer=drawer,
        options=_options(state), rerolled=False, word=None, shown=[], solved={}, gains={},
        likes=[], close={}, feed=[], twist=None, ink=[], ink_points=0, strokes=0, bot_due={},
        ink_turn=f"{state['round']}-{random.randrange(1 << 30):x}",
    )
    state["rev"] += 1


def _begin_draw(state: dict, choice: int) -> None:
    word = state["options"][choice]
    twist = random.choice(TWISTS) if state["twists"] and random.random() < TWIST_CHANCE else None
    seconds = state["seconds"] * (0.5 if twist == "half" else 1)
    state.update(phase="draw", phase_at=now(), deadline=now() + seconds, word=word, twist=twist,
                 options=[], shown=[], solved={}, close={}, feed=[])
    state["used"].append(word["w"])
    state["players"][state["drawer"]]["drawn"] += 1
    # Bots take a turn at guessing: some get it, sooner for easy words.
    chance = {1: 0.8, 2: 0.6, 3: 0.4}.get(int(word.get("d", 2)), 0.5)
    for index, seat in enumerate(state["players"]):
        if seat.get("bot") and index != state["drawer"]:
            right = random.random() < chance
            state["bot_due"][str(index)] = {"at": now() + seconds * random.uniform(0.25, 0.85), "right": right,
                                            "tries": random.randint(1, 3)}
    if twist:
        _log(state, "twist", None, twist)
    state["rev"] += 1


def _end_turn(state: dict) -> None:
    drawer = state["drawer"]
    word = state["word"] or {}
    guessers = _guessers(state)
    if drawer is not None and guessers and len(state["solved"]) == len(guessers):
        _gain(state, drawer, ALL_GUESSED_BONUS)
    state["gallery"].append({"seat": drawer, "word": word.get("w", ""), "likes": len(state["likes"]),
                             "solved": len(state["solved"])})
    state.update(phase="reveal", phase_at=now(), deadline=now() + REVEAL_SECONDS, bot_due={})
    state["rev"] += 1


def _multiplier(state: dict) -> float:
    level = int((state["word"] or {}).get("d", 2))
    return LEVEL_FACTOR.get(level, 1.0) * (2 if state["twist"] == "half" else 1)


def _right(state: dict, seat: int) -> None:
    t = now()
    total = max(1.0, state["deadline"] - state["phase_at"])
    left = max(0.0, state["deadline"] - t)
    first = not state["solved"]
    points = GUESS_BASE + GUESS_SPEED * left / total + (FIRST_BONUS if first else 0)
    points = int(round(points * _multiplier(state) / 5) * 5)
    state["solved"][str(seat)] = {"at": round(t - state["phase_at"], 1), "points": points}
    player = state["players"][seat]
    player["right"] += 1
    took = t - state["phase_at"]
    if not player["fastest"] or took < player["fastest"]:
        player["fastest"] = round(took, 1)
    _gain(state, seat, points)
    _gain(state, state["drawer"], int(round(ARTIST_PER_GUESS * _multiplier(state) / 5) * 5))
    _log(state, "right", seat)
    if len(state["solved"]) >= len(_guessers(state)):
        _end_turn(state)


# ============================== actions ==============================

def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if seat is None:
        raise Illegal("notSeated")
    phase = state["phase"]
    is_host = seat == host_seat(state)

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        pack = str(body.get("pack") or state["pack"])
        if pack != MIX and pack not in PACKS:
            raise Illegal("badPack")
        state["pack"] = pack
        try:
            turns = int(body.get("turns") or state["turns"])
            seconds = int(body.get("seconds") or state["seconds"])
        except (TypeError, ValueError):
            turns, seconds = state["turns"], state["seconds"]
        state["turns"] = turns if turns in TURN_CHOICES else DEFAULT_TURNS
        state["seconds"] = seconds if seconds in SECOND_CHOICES else DEFAULT_SECONDS
        if "twists" in body:
            state["twists"] = bool(body.get("twists"))
        if str(body.get("mode") or "") in MODES:
            state["mode"] = str(body["mode"])
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        _start(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        state.update(phase="setup", phase_at=now(), deadline=0.0, drawer=None, word=None, feed=[], gains={})
        state["rev"] += 1
        return

    if action == "pick":
        if phase != "choose" or seat != state["drawer"]:
            raise Illegal("notYourTurn")
        try:
            choice = int(body.get("choice"))
        except (TypeError, ValueError):
            raise Illegal("badChoice") from None
        if not 0 <= choice < len(state["options"]):
            raise Illegal("badChoice")
        _begin_draw(state, choice)
        return

    if action == "reroll":
        if phase != "choose" or seat != state["drawer"]:
            raise Illegal("notYourTurn")
        if state["rerolled"]:
            raise Illegal("oneReroll")
        state["used"].extend(w["w"] for w in state["options"])
        state["options"] = _options(state)
        state["rerolled"] = True
        state["rev"] += 1
        return

    if action == "guess":
        if phase != "draw":
            raise Illegal("tooLate")
        if seat == state["drawer"]:
            raise Illegal("artistCantGuess")
        if str(seat) in state["solved"]:
            raise Illegal("alreadySolved")
        t = now()
        if t - state["last_guess"].get(str(seat), 0) < GUESS_GAP:
            raise Illegal("slowDown")
        state["last_guess"][str(seat)] = t
        text = " ".join(str(body.get("text") or "").split())[:32]
        if not normalize(text):
            raise Illegal("emptyGuess")
        verdict = judge(state["word"], text)
        if verdict == "right":
            _right(state, seat)
            return
        if verdict == "close":
            # Whispered to its author alone: the others would learn too much.
            state["close"][str(seat)] = {"text": text, "at": int(t * 1000)}
        else:
            _log(state, "guess", seat, text)
        state["rev"] += 1
        return

    if action == "trace":
        _act_trace(state, seat, body)
        return

    if action == "fill":
        _act_fill(state, seat, body)
        return

    if action == "vote":
        _act_vote(state, seat, body)
        return

    if action == "like":
        if phase not in ("draw", "reveal") or seat == state["drawer"] or state["drawer"] is None:
            raise Illegal("notNow")
        if seat in state["likes"]:
            return
        state["likes"].append(seat)
        drawer = state["players"][state["drawer"]]
        drawer["likes"] += 1
        _gain(state, state["drawer"], LIKE_POINTS)
        if phase == "reveal" and state["gallery"]:
            state["gallery"][-1]["likes"] = len(state["likes"])
        state["rev"] += 1
        return

    if action == "skip":
        # The artist gives up the turn (nothing to draw it with): the word is shown to all.
        if phase not in ("choose", "draw") or seat != state["drawer"]:
            raise Illegal("notYourTurn")
        if phase == "choose":
            _begin_draw(state, 0)
        _end_turn(state)
        return

    raise Illegal("badAction")


# ============================== ink ==============================

def _point(v) -> int:
    return int(v)


def ink(state: dict, seat: int | None, body: dict) -> dict:
    """Adds the artist's strokes (if any) and returns what the caller has not seen yet."""
    phase = state["phase"]
    adds = body.get("add")
    if adds:
        if seat is None or seat != state["drawer"] or phase != "draw":
            raise Illegal("notYourTurn")
        if str(body.get("turn") or "") != state["ink_turn"]:
            raise Illegal("staleInk")
        if not isinstance(adds, list):
            raise Illegal("badInk")
        _add_ink(state, adds[:64])
    try:
        since = max(0, int(body.get("since") or 0))
    except (TypeError, ValueError):
        since = 0
    if str(body.get("turn") or "") != state["ink_turn"]:
        since = 0
    ops = state["ink"][since:since + INK_PAGE] if phase in ("draw", "reveal") else []
    return {"turn": state["ink_turn"], "from": since, "ops": ops, "total": len(state["ink"]),
            "phase": phase, "rev": state["rev"]}


def _add_ink(state: dict, adds: list) -> None:
    twist = state["twist"]
    for op in adds:
        if not isinstance(op, list) or not op or len(state["ink"]) >= MAX_OPS:
            continue
        kind = op[0]
        try:
            if kind == "b" and len(op) == 5:
                color, size = int(op[1]), int(op[2])
                x, y = _point(op[3]), _point(op[4])
                if not (0 <= color < COLORS and 1 <= size <= 4 and 0 <= x <= INK_W and 0 <= y <= INK_H):
                    continue
                if twist == "oneline" and state["strokes"] >= 1:
                    continue
                if twist == "noerase" and color == ERASER:
                    continue
                if twist == "mono":
                    color = 0
                state["strokes"] += 1
                state["ink"].append(["b", color, size, x, y])
                state["ink_points"] += 1
            elif kind == "m" and 3 <= len(op) <= 1 + MAX_OP_POINTS * 2 and len(op) % 2 == 1:
                if not state["ink"] or state["ink_points"] >= MAX_POINTS:
                    continue
                pts = [_point(v) for v in op[1:]]
                if any(not (0 <= pts[i] <= (INK_W if i % 2 == 0 else INK_H)) for i in range(len(pts))):
                    continue
                if twist == "oneline" and state["strokes"] > 1:
                    continue
                state["ink"].append(["m", *pts])
                state["ink_points"] += len(pts) // 2
            elif kind in ("u", "c") and len(op) == 1:
                if twist in ("oneline", "noerase"):
                    continue
                state["ink"].append([kind])
            elif kind == "e" and len(op) == 1:
                # The pen lifted: after one line, a one-line drawing is finished.
                state["ink"].append(["e"])
        except (TypeError, ValueError):
            continue


# ============================== clock and bots ==============================

def _bot_step(state: dict) -> bool:
    moved = False
    t = now()
    word = state["word"] or {}
    others = [w["w"] for w in _pool(word.get("pack", MIX)) if w["w"] != word.get("w")] or ["..."]
    for key, due in list(state["bot_due"].items()):
        if t < due["at"]:
            continue
        seat = int(key)
        if seat >= len(state["players"]) or not state["players"][seat].get("bot") or key in state["solved"]:
            state["bot_due"].pop(key, None)
            continue
        if due["tries"] > 1 or not due["right"]:
            _log(state, "guess", seat, random.choice(others))
            due["tries"] -= 1
            due["at"] = t + random.uniform(4, 10)
            if due["tries"] <= 0 and not due["right"]:
                state["bot_due"].pop(key, None)
            state["rev"] += 1
            moved = True
            continue
        state["bot_due"].pop(key, None)
        _right(state, seat)
        moved = True
        if state["phase"] != "draw":
            break
    return moved


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    if phase in ("trace", "color", "vote", "result"):
        return _step_art(state)
    t = now()
    if phase == "choose":
        if t >= state["deadline"]:
            _begin_draw(state, random.randrange(len(state["options"])))
        return True
    if phase == "draw":
        total = max(1.0, state["deadline"] - state["phase_at"])
        share = (t - state["phase_at"]) / total
        letters = [i for i, ch in enumerate(state["word"]["w"]) if ch != " "]
        want = 0
        if share >= 0.45:
            want = 1
        if share >= 0.7:
            want = 1 if len(letters) <= 4 else 2
        if len(state["shown"]) < min(want, max(0, len(letters) - 1)):
            hidden = [i for i in letters if i not in state["shown"]]
            state["shown"].append(random.choice(hidden))
            state["rev"] += 1
        _bot_step(state)
        if state["phase"] == "draw" and state["strokes"] == 0 and t - state["phase_at"] > ABSENT_SECONDS:
            _log(state, "away", state["drawer"])
            _end_turn(state)
        if state["phase"] == "draw" and t >= state["deadline"]:
            _end_turn(state)
        return True
    if phase == "reveal":
        if t >= state["deadline"]:
            _next_turn(state)
        return True
    return False


# ============================== view ==============================

def _awards(state: dict) -> dict:
    players = state["players"]

    def best(key, reverse=True, allow_zero=False):
        pool = [i for i in range(len(players)) if allow_zero or players[i][key]]
        if not pool:
            return None
        return (max if reverse else min)(pool, key=lambda i: players[i][key])

    champion = max(range(len(players)), key=lambda i: players[i]["score"]) if players else None
    artist = best("likes")
    sharp = best("right")
    quick = best("fastest", reverse=False)
    favourite = max(state["gallery"], key=lambda g: g["likes"], default=None)
    return {
        "champion": champion, "artist": artist, "sharp": sharp, "quick": quick,
        "favourite": favourite if favourite and favourite["likes"] > 0 else None,
    }


def view_for(state: dict, seat: int | None) -> dict:
    t = now()
    phase = state["phase"]
    drawer = state["drawer"]
    word = state["word"]
    solved = state["solved"]
    over = phase == "reveal"
    knows = seat is not None and (seat == drawer or str(seat) in solved)
    view = {
        "game": "rasm", "phase": phase, "seat": seat,
        "isHost": seat is not None and seat == host_seat(state),
        "hostName": state["players"][host_seat(state)]["name"] if host_seat(state) is not None else "",
        "players": [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": bool(p.get("bot")),
                     "score": p["score"], "likes": p["likes"], "right": p["right"], "fastest": p["fastest"],
                     "solved": str(i) in solved, "gain": state["gains"].get(str(i), 0)}
                    for i, p in enumerate(state["players"])],
        "pack": state["pack"], "turns": state["turns"], "seconds": state["seconds"], "twists": state["twists"],
        "round": state["round"], "rounds": len(state["schedule"]),
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state["deadline"] else 0,
        "elapsed": int((t - state["phase_at"]) * 1000),
        "drawer": drawer, "twist": state["twist"] if phase in ("draw", "reveal") else None,
        "feed": state["feed"], "likes": len(state["likes"]),
        "liked": seat is not None and seat in state["likes"],
        "solvedCount": len(solved), "guessers": len(_guessers(state)) if drawer is not None else 0,
        "inkTurn": state["ink_turn"], "inkTotal": len(state["ink"]),
        "rev": state["rev"],
    }
    if phase == "setup":
        view["packs"] = [{"key": MIX, "label": _LOCALE["mix"]["label"], "blurb": _LOCALE["mix"]["blurb"],
                          "count": len(_pool(MIX))}] + [
            {"key": p["key"], "label": p["label"], "blurb": p.get("blurb", ""), "count": len(p["words"])}
            for p in _WORDS["packs"]]
        view["turnChoices"] = list(TURN_CHOICES)
        view["secondChoices"] = list(SECOND_CHOICES)
    if phase == "choose" and seat is not None and seat == drawer:
        view["options"] = [{"w": w["w"], "d": int(w.get("d", 2)),
                            "points": int(GUESS_BASE * LEVEL_FACTOR.get(int(w.get("d", 2)), 1))} for w in state["options"]]
        view["rerolled"] = state["rerolled"]
    if word and phase in ("draw", "reveal"):
        text = word["w"]
        view["word"] = {
            "text": text if (knows or over) else None,
            "pattern": pattern(text, state["shown"]) if not (knows or over) else text,
            "letters": len([ch for ch in text if ch != " "]),
            "level": int(word.get("d", 2)),
            "pack": word.get("pack", ""),
        }
        if seat is not None and str(seat) in solved:
            view["mine"] = solved[str(seat)]
        close = state["close"].get(str(seat)) if seat is not None else None
        if close:
            view["close"] = close
    view["mode"] = state.get("mode", "guess")
    if phase == "setup":
        view["modes"] = list(MODES)
    if state.get("mode", "guess") != "guess":
        view["rounds"] = state.get("art_rounds", 0)
        _art_view(state, seat, view)
    if phase == "final":
        view["awards"] = _awards(state)
        view["gallery"] = state["gallery"][-12:]
    return view


# ============================== trace and colour ==============================

def _sample(strokes: list, step: float) -> list[tuple[float, float]]:
    """Points every `step` units along every polyline (a lone dot counts once)."""
    out: list[tuple[float, float]] = []
    for line in strokes:
        if not line:
            continue
        px, py = line[0]
        out.append((px, py))
        carry = 0.0
        for x, y in line[1:]:
            dx, dy = x - px, y - py
            length = (dx * dx + dy * dy) ** 0.5
            if length <= 0:
                continue
            at = step - carry
            while at <= length:
                out.append((px + dx * at / length, py + dy * at / length))
                at += step
            carry = length - (at - step)
            px, py = x, y
    return out


def _grid(points: list[tuple[float, float]], cell: float) -> dict:
    grid: dict[tuple[int, int], list] = {}
    for x, y in points:
        grid.setdefault((int(x // cell), int(y // cell)), []).append((x, y))
    return grid


def _near(grid: dict, cell: float, x: float, y: float) -> bool:
    gx, gy = int(x // cell), int(y // cell)
    limit = cell * cell
    for ix in (gx - 1, gx, gx + 1):
        for iy in (gy - 1, gy, gy + 1):
            for qx, qy in grid.get((ix, iy), ()):
                if (qx - x) ** 2 + (qy - y) ** 2 <= limit:
                    return True
    return False


_TARGETS: dict[str, tuple[list, dict]] = {}


def _target(key: str) -> tuple[list, dict]:
    if key not in _TARGETS:
        points = _sample(ART[key]["strokes"], TRACE_STEP)
        _TARGETS[key] = (points, _grid(points, TRACE_RADIUS))
    return _TARGETS[key]


def trace_score(key: str, strokes: list) -> int:
    """0-100: how well `strokes` re-ink drawing `key`. Both missing lines and stray ink cost."""
    target, target_grid = _target(key)
    ink = _sample(strokes, TRACE_STEP)
    if len(ink) < 8 or not target:
        return 0
    ink_grid = _grid(ink, TRACE_RADIUS)
    coverage = sum(1 for x, y in target if _near(ink_grid, TRACE_RADIUS, x, y)) / len(target)
    precision = sum(1 for x, y in ink if _near(target_grid, TRACE_RADIUS, x, y)) / len(ink)
    if coverage + precision <= 0:
        return 0
    # The product punishes both halves: a scribble everywhere and half a drawing both stay low.
    return int(round(100 * coverage * precision))


def _clean_strokes(raw) -> list:
    if not isinstance(raw, list):
        raise Illegal("badInk")
    out, total = [], 0
    for line in raw[:400]:
        if not isinstance(line, list):
            continue
        clean = []
        for point in line:
            if total >= TRACE_MAX_POINTS:
                break
            try:
                x, y = int(point[0]), int(point[1])
            except (TypeError, ValueError, IndexError):
                continue
            clean.append([min(INK_W, max(0, x)), min(INK_H, max(0, y))])
            total += 1
        if clean:
            out.append(clean)
    return out


def _art_seconds(state: dict) -> int:
    if state["mode"] == "trace":
        return TRACE_SECONDS.get(state["seconds"], 60)
    return state["seconds"] + COLOR_EXTRA_SECONDS


def _start_art(state: dict) -> None:
    for p in state["players"]:
        p.update(score=0, drawn=0, right=0, likes=0, fastest=0.0)
    state["gallery"] = []
    state["art_used"] = []
    state["schedule"] = []
    state["round"] = 0
    state["art_rounds"] = state["turns"] * 2 + 1 if state["mode"] == "trace" else state["turns"]
    _next_art(state)


def _next_art(state: dict) -> None:
    if state["round"] >= state["art_rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0, drawer=None, word=None, art=None)
        state["rev"] += 1
        return
    keys = [k for k in ART if k not in state["art_used"]] or list(ART)
    key = random.choice(keys)
    state["art_used"].append(key)
    state["round"] += 1
    seconds = _art_seconds(state)
    state.update(phase=state["mode"], phase_at=now(), deadline=now() + seconds, drawer=None, word=None,
                 art=key, trace={}, trace_ink={}, last_trace={}, fills={}, votes={}, gains={}, feed=[], bot_due={})
    if state["mode"] == "trace":
        for index, seat in enumerate(state["players"]):
            if seat.get("bot"):
                state["bot_due"][str(index)] = {"done_at": now() + seconds * random.uniform(0.35, 0.9),
                                                "good": random.random() < 0.6, "cap": random.randint(55, 78),
                                                "tick": 0.0}
    state["rev"] += 1


def _finish_trace(state: dict, seat: int, entry: dict) -> None:
    rank = sum(1 for e in state["trace"].values() if e.get("done")) + 1
    took = round(max(0.1, now() - state["phase_at"]), 1)
    entry.update(done=took, rank=rank)
    points = TRACE_RANK_POINTS[min(rank, len(TRACE_RANK_POINTS)) - 1] + entry["score"]
    player = state["players"][seat]
    player["right"] += 1
    if not player["fastest"] or took < player["fastest"]:
        player["fastest"] = took
    _gain(state, seat, points)
    _log(state, "finish", seat, str(rank))
    if all(state["trace"].get(str(i), {}).get("done") for i in _humans(state)):
        _end_art(state)


def _act_trace(state: dict, seat: int, body: dict) -> None:
    if state["phase"] != "trace":
        raise Illegal("tooLate")
    entry = state["trace"].setdefault(str(seat), {"score": 0, "done": 0, "rank": 0})
    if entry["done"]:
        return
    t = now()
    if t - state["last_trace"].get(str(seat), 0) < TRACE_GAP:
        return
    state["last_trace"][str(seat)] = t
    strokes = _clean_strokes(body.get("strokes"))
    entry["score"] = trace_score(state["art"], strokes)
    state["trace_ink"][str(seat)] = strokes
    if entry["score"] >= TRACE_FINISH:
        _finish_trace(state, seat, entry)
    state["rev"] += 1


def _act_fill(state: dict, seat: int, body: dict) -> None:
    if state["phase"] != "color":
        raise Illegal("tooLate")
    raw = body.get("fills")
    if not isinstance(raw, list):
        raise Illegal("badInk")
    fills = []
    for item in raw[:MAX_FILLS]:
        try:
            x, y, c = int(item[0]), int(item[1]), int(item[2])
        except (TypeError, ValueError, IndexError):
            continue
        if 0 <= x <= INK_W and 0 <= y <= INK_H and 0 <= c < COLOR_PALETTE:
            fills.append([x, y, c])
    state["fills"][str(seat)] = fills
    state["rev"] += 1


def _entries(state: dict) -> list[int]:
    return [int(k) for k, v in state["fills"].items() if v and int(k) < len(state["players"])]


def _act_vote(state: dict, seat: int, body: dict) -> None:
    if state["phase"] != "vote":
        raise Illegal("tooLate")
    try:
        target = int(body.get("seat"))
    except (TypeError, ValueError):
        raise Illegal("badChoice") from None
    if target == seat:
        raise Illegal("notYourself")
    if target not in _entries(state):
        raise Illegal("badChoice")
    state["votes"][str(seat)] = target
    state["rev"] += 1
    entries = _entries(state)
    voters = [i for i in _humans(state) if any(e != i for e in entries)]
    if all(str(i) in state["votes"] for i in voters):
        _finish_vote(state)


def _art_name(state: dict) -> str:
    return ART[state["art"]]["name"] if state.get("art") in ART else ""


def _end_art(state: dict) -> None:
    if state["phase"] == "trace":
        for key, entry in state["trace"].items():
            if not entry.get("done") and entry.get("score", 0) >= TRACE_PARTIAL_FROM:
                _gain(state, int(key), int(entry["score"] * 1.2))
        done = sorted((e["rank"], int(k)) for k, e in state["trace"].items() if e.get("done"))
        if done:
            best = done[0][1]
        else:
            best = max((int(k) for k in state["trace"]), key=lambda k: state["trace"][str(k)]["score"], default=None)
        state["gallery"].append({"seat": best, "word": _art_name(state), "likes": 0, "solved": len(done)})
        state.update(phase="result", phase_at=now(), deadline=now() + RESULT_SECONDS, bot_due={})
        state["rev"] += 1
        return
    if len(_entries(state)) < 2:
        _finish_vote(state)
        return
    state.update(phase="vote", phase_at=now(), deadline=now() + COLOR_VOTE_SECONDS, votes={}, bot_due={})
    for index, seat in enumerate(state["players"]):
        if seat.get("bot"):
            state["bot_due"][str(index)] = {"at": now() + random.uniform(3, 12)}
    state["rev"] += 1


def _finish_vote(state: dict) -> None:
    tally: dict[int, int] = {}
    for target in state["votes"].values():
        tally[target] = tally.get(target, 0) + 1
    for seat in _entries(state):
        if len(state["fills"][str(seat)]) >= COLOR_MIN_FILLS:
            _gain(state, seat, COLOR_EFFORT_POINTS)
    for seat, count in tally.items():
        _gain(state, seat, VOTE_POINTS * count)
        state["players"][seat]["likes"] += count
    entries = _entries(state)
    winner = max(tally, key=lambda k: tally[k]) if tally else (entries[0] if entries else None)
    state["gallery"].append({"seat": winner, "word": _art_name(state),
                             "likes": tally.get(winner, 0) if winner is not None else 0, "solved": len(entries)})
    state.update(phase="result", phase_at=now(), deadline=now() + RESULT_SECONDS, bot_due={})
    state["rev"] += 1


def _step_art(state: dict) -> bool:
    phase = state["phase"]
    t = now()
    if phase == "trace":
        for key, due in list(state["bot_due"].items()):
            seat = int(key)
            entry = state["trace"].setdefault(key, {"score": 0, "done": 0, "rank": 0})
            if entry["done"] or t < due["tick"]:
                continue
            due["tick"] = t + 1.2
            share = min(1.0, (t - state["phase_at"]) / max(1.0, due["done_at"] - state["phase_at"]))
            entry["score"] = int(share * due["cap"])
            if due["good"] and t >= due["done_at"]:
                entry["score"] = random.randint(TRACE_FINISH, 92)
                state["bot_due"].pop(key, None)
                _finish_trace(state, seat, entry)
                if state["phase"] != "trace":
                    return True
            state["rev"] += 1
        if state["phase"] == "trace" and t >= state["deadline"]:
            _end_art(state)
        return True
    if phase == "color":
        if t >= state["deadline"]:
            _end_art(state)
        return True
    if phase == "vote":
        for key, due in list(state["bot_due"].items()):
            if t < due["at"]:
                continue
            state["bot_due"].pop(key, None)
            choices = [e for e in _entries(state) if e != int(key)]
            if choices:
                state["votes"][key] = random.choice(choices)
                state["rev"] += 1
        if t >= state["deadline"]:
            _finish_vote(state)
        return True
    if phase == "result":
        if t >= state["deadline"]:
            _next_art(state)
        return True
    return False


def _art_view(state: dict, seat: int | None, view: dict) -> None:
    phase = state["phase"]
    key = state.get("art")
    if key in ART and phase in ("trace", "color", "vote", "result"):
        art = ART[key]
        view["art"] = {"key": key, "name": art["name"], "level": art["level"], "strokes": art["strokes"]}
    progress = {}
    for index in range(len(state["players"])):
        entry = state["trace"].get(str(index)) or {}
        progress[str(index)] = {"score": entry.get("score", 0), "done": entry.get("done", 0), "rank": entry.get("rank", 0),
                                "fills": len(state["fills"].get(str(index)) or []),
                                "voted": str(index) in state["votes"]}
    view["progress"] = progress
    if seat is not None:
        view["myVote"] = state["votes"].get(str(seat))
    if state["mode"] == "color" and phase in ("vote", "result"):
        view["fills"] = {k: v for k, v in state["fills"].items() if v}
    if phase == "result":
        tally: dict[str, int] = {}
        for target in state["votes"].values():
            tally[str(target)] = tally.get(str(target), 0) + 1
        view["tally"] = tally
        if state["mode"] == "trace":
            top = sorted((e["rank"], k) for k, e in state["trace"].items() if e.get("done"))[:3]
            if not top:
                top = [(0, k) for k in sorted(state["trace"], key=lambda k: -state["trace"][k]["score"])[:1]]
            view["traceInk"] = {k: state["trace_ink"].get(k, []) for _rank, k in top}

