"""
Codenames - two teams, one spymaster each, 25 code words.

Seating first: every player takes one of four roles (red/blue spymaster,
red/blue operative) or lets the host arrange them. Whatever is still empty
when the host starts is filled by bots, so one person can play a whole match
against a bot team and four people get the classic table.

The spymaster sees the key and gives a one-word clue with a number; the
operatives mark cards and reveal them. A wrong colour ends the turn, the
assassin ends the game. Bots never read the key as operatives: they guess
from the words' tags, the same vocabulary their own spymaster clues from.
"""
from __future__ import annotations

import json
import pathlib
import random
import time

HERE = pathlib.Path(__file__).resolve().parent
_WORDS: dict[str, list[str]] = json.loads((HERE / "content" / "words.json").read_text(encoding="utf-8"))["words"]
_LOCALE = json.loads((HERE / "locales" / "ar.json").read_text(encoding="utf-8"))

TEAMS = ("red", "blue")
ROLES = ("spy", "op")
MAX_SEATS = 10
BOARD = 25
FIRST_COUNT = 9
SECOND_COUNT = 8
NEUTRAL_COUNT = 7
TIMER_CHOICES = (0, 90, 150)
BOT_CLUE_DELAY = 3.2
BOT_GUESS_DELAY = 2.2
BOT_MARK_DELAY = 1.1
# Tags too broad to make a fair clue.
VAGUE = {"\u0645\u0641\u0647\u0648\u0645", "\u0623\u062F\u0627\u0629", "\u0645\u0627\u062F\u0629"}


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def normalize(text: str) -> str:
    text = "".join(ch for ch in text.strip() if not ("\u064B" <= ch <= "\u065F" or ch in "\u0670\u0640"))
    for src, dst in (("\u0623", "\u0627"), ("\u0625", "\u0627"), ("\u0622", "\u0627"), ("\u0629", "\u0647"), ("\u0649", "\u064A")):
        text = text.replace(src, dst)
    if text.startswith("\u0627\u0644") and len(text) > 3:
        text = text[2:]
    return text


def _seat(person: dict, bot: bool = False) -> dict:
    return {"id": person["id"], "name": person["name"], "photo": person.get("photo", ""),
            "bot": bot, "team": None, "role": None}


def new_match(people: list[dict], host: int) -> dict:
    return {
        "game": "codenames", "host": host,
        "players": [_seat(p) for p in people[:MAX_SEATS]],
        "phase": "setup", "phase_at": now(), "deadline": 0.0, "timer": 0,
        "board": [], "start": "red", "turn": "red", "clue": None, "guesses": 0,
        "marks": {}, "history": [], "winner": None, "reason": "",
        "wins": {"red": 0, "blue": 0}, "games": 0, "bot_at": 0.0, "bot_plan": [],
        "rev": 0,
    }


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat.get("id") == user_id and not seat["bot"]:
            return index
    return None


def host_seat(state: dict) -> int | None:
    host = seat_of(state, state.get("host", 0))
    if host is not None:
        return host
    return next((i for i, p in enumerate(state["players"]) if not p["bot"]), None)


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    humans = [p for p in state["players"] if not p["bot"]]
    if len(humans) >= MAX_SEATS:
        raise Illegal("full")
    seat = _seat(person)
    if state["phase"] != "setup":
        # Mid-game: take over a bot operative if there is one, otherwise watch
        # the board as an extra operative of the smaller team.
        bot = next((p for p in state["players"] if p["bot"] and p["role"] == "op"), None)
        if bot is not None:
            bot.update(id=seat["id"], name=seat["name"], photo=seat["photo"], bot=False)
            state["rev"] += 1
            return
        seat["team"] = min(TEAMS, key=lambda t: sum(1 for p in state["players"] if p["team"] == t))
        seat["role"] = "op"
    state["players"].append(seat)
    state["rev"] += 1


# ============================== seating ==============================

def _members(state: dict, team: str, role: str) -> list[int]:
    return [i for i, p in enumerate(state["players"]) if p["team"] == team and p["role"] == role]


def _arrange(state: dict) -> None:
    """Humans as operatives first (bots give good clues), a human spymaster
    only when that team also has a human to guess."""
    humans = [i for i, p in enumerate(state["players"]) if not p["bot"]]
    order = {1: [("red", "op")],
             2: [("red", "op"), ("red", "spy")],
             3: [("red", "op"), ("red", "spy"), ("blue", "op")],
             4: [("red", "op"), ("red", "spy"), ("blue", "op"), ("blue", "spy")]}
    plan = order.get(len(humans)) or order[4]
    random.shuffle(humans)
    for n, index in enumerate(humans):
        if n < len(plan):
            team, role = plan[n]
        else:
            team, role = TEAMS[n % 2], "op"
        state["players"][index].update(team=team, role=role)


def _fill_bots(state: dict) -> None:
    names = [n for n in _LOCALE["bots"] if n not in {p["name"] for p in state["players"]}]
    counter = 1
    for team in TEAMS:
        for role in ROLES:
            if not _members(state, team, role):
                name = names.pop(0) if names else f"{_LOCALE['bot']} {counter}"
                seat = _seat({"id": -counter, "name": name}, bot=True)
                seat.update(team=team, role=role)
                state["players"].append(seat)
                counter += 1


def _drop_bots(state: dict) -> None:
    state["players"] = [p for p in state["players"] if not p["bot"]]


# ============================== board ==============================

def _deal(state: dict) -> None:
    words = random.sample(list(_WORDS), BOARD)
    first = state["start"]
    second = "blue" if first == "red" else "red"
    kinds = [first] * FIRST_COUNT + [second] * SECOND_COUNT + ["neutral"] * NEUTRAL_COUNT + ["assassin"]
    random.shuffle(kinds)
    state["board"] = [{"w": w, "k": k, "up": False, "by": None} for w, k in zip(words, kinds)]
    state.update(turn=first, clue=None, guesses=0, marks={}, history=[], winner=None, reason="")


def _left(state: dict, team: str) -> int:
    return sum(1 for c in state["board"] if c["k"] == team and not c["up"])


def _begin(state: dict) -> None:
    _fill_bots(state)
    state["start"] = random.choice(TEAMS) if state["games"] == 0 else ("blue" if state["start"] == "red" else "red")
    _deal(state)
    _enter(state, "clue")


def _enter(state: dict, phase: str) -> None:
    t = now()
    state["phase"] = phase
    state["phase_at"] = t
    state["deadline"] = t + state["timer"] if state["timer"] and phase in ("clue", "guess") else 0.0
    state["bot_at"] = 0.0
    state["bot_plan"] = []
    state["rev"] += 1


def _other(team: str) -> str:
    return "blue" if team == "red" else "red"


def _end_turn(state: dict) -> None:
    state["turn"] = _other(state["turn"])
    state["clue"] = None
    state["guesses"] = 0
    state["marks"] = {}
    _enter(state, "clue")


def _finish(state: dict, winner: str, reason: str) -> None:
    state["winner"] = winner
    state["reason"] = reason
    state["wins"][winner] += 1
    state["games"] += 1
    for card in state["board"]:
        card.setdefault("late", not card["up"])
    _enter(state, "over")


def _give_clue(state: dict, seat: int, word: str, number: int) -> None:
    team = state["turn"]
    clean = normalize(word)
    if not clean or " " in word.strip():
        raise Illegal("oneWord")
    if any(normalize(c["w"]) == clean for c in state["board"] if not c["up"]):
        raise Illegal("clueOnBoard")
    if not 0 <= number <= 9:
        raise Illegal("badNumber")
    state["clue"] = {"word": word.strip(), "n": number, "by": seat, "team": team}
    state["guesses"] = 0
    state["marks"] = {}
    state["history"].append({"team": team, "word": word.strip(), "n": number, "by": seat, "hits": []})
    _enter(state, "guess")


def _reveal(state: dict, seat: int, cell: int) -> None:
    card = state["board"][cell]
    team = state["turn"]
    card["up"] = True
    card["by"] = seat
    state["guesses"] += 1
    state["marks"].pop(str(cell), None)
    state["history"][-1]["hits"].append({"cell": cell, "k": card["k"]})
    state["rev"] += 1
    if card["k"] == "assassin":
        _finish(state, _other(team), "assassin")
        return
    for side in TEAMS:
        if _left(state, side) == 0:
            _finish(state, side, "all")
            return
    if card["k"] != team:
        _end_turn(state)
        return
    n = state["clue"]["n"] if state["clue"] else 0
    if n and state["guesses"] >= n + 1:
        _end_turn(state)
        return
    state["bot_at"] = 0.0


# ============================== actions ==============================

def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if seat is None:
        raise Illegal("watchingOnly")
    me = state["players"][seat]
    phase = state["phase"]
    is_host = seat == host_seat(state)

    if action == "take":
        if phase != "setup":
            raise Illegal("notNow")
        team, role = str(body.get("team")), str(body.get("role"))
        if team not in TEAMS or role not in ROLES:
            raise Illegal("badSeat")
        if role == "spy" and any(i != seat for i in _members(state, team, "spy")):
            raise Illegal("seatTaken")
        me.update(team=team, role=role)
        state["rev"] += 1
        return
    if action == "unseat":
        if phase != "setup":
            raise Illegal("notNow")
        me.update(team=None, role=None)
        state["rev"] += 1
        return
    if action == "auto":
        if phase != "setup":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        for p in state["players"]:
            p.update(team=None, role=None)
        _arrange(state)
        state["rev"] += 1
        return
    if action == "timer":
        if not is_host:
            raise Illegal("notHost")
        seconds = int(body.get("seconds", 0))
        if seconds not in TIMER_CHOICES:
            raise Illegal("badTimer")
        state["timer"] = seconds
        state["rev"] += 1
        return
    if action == "go":
        if phase != "setup":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        # Anyone still unseated gets a sensible place first.
        loose = [p for p in state["players"] if not p["bot"] and p["team"] is None]
        if loose:
            if all(p["team"] is None for p in state["players"]):
                _arrange(state)
            else:
                for p in loose:
                    team = min(TEAMS, key=lambda t: sum(1 for q in state["players"] if q["team"] == t))
                    role = "spy" if not _members(state, team, "spy") and _members(state, team, "op") else "op"
                    p.update(team=team, role=role)
        _begin(state)
        return
    if action == "again":
        if phase != "over":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        _begin(state)
        return
    if action == "seats":
        if phase != "over":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        _drop_bots(state)
        _enter(state, "setup")
        return

    if me["team"] != state["turn"]:
        raise Illegal("notYourTurn")
    if action == "clue":
        if phase != "clue" or me["role"] != "spy":
            raise Illegal("notYourTurn")
        try:
            number = int(body.get("n", 1))
        except (TypeError, ValueError):
            raise Illegal("badNumber") from None
        _give_clue(state, seat, str(body.get("word") or ""), number)
        return
    if phase != "guess" or me["role"] != "op":
        raise Illegal("notYourTurn")
    if action == "mark":
        cell = _cell(state, body)
        marks = state["marks"].setdefault(str(cell), [])
        if seat in marks:
            marks.remove(seat)
        else:
            marks.append(seat)
        if not marks:
            state["marks"].pop(str(cell), None)
        state["rev"] += 1
        return
    if action == "pick":
        _reveal(state, seat, _cell(state, body))
        return
    if action == "pass":
        if state["guesses"] == 0:
            raise Illegal("guessFirst")
        _end_turn(state)
        return
    raise Illegal("badAction")


def _cell(state: dict, body: dict) -> int:
    try:
        cell = int(body.get("cell", -1))
    except (TypeError, ValueError):
        raise Illegal("badCell") from None
    if not 0 <= cell < len(state["board"]) or state["board"][cell]["up"]:
        raise Illegal("badCell")
    return cell


# ============================== bots ==============================

def _tags(word: str) -> list[str]:
    return _WORDS.get(word, [])


def bot_clue(state: dict, team: str) -> tuple[str, int]:
    """The tag that covers most of our words without touching the assassin,
    weighed against the opponent's words and the neutrals it also covers."""
    hidden = [c for c in state["board"] if not c["up"]]
    board_words = {normalize(c["w"]) for c in hidden}
    used = {normalize(h["word"]) for h in state["history"]}
    scores: dict[str, tuple[float, int]] = {}
    tags = {t for c in hidden for t in _tags(c["w"])}
    for tag in tags:
        if tag in VAGUE or normalize(tag) in board_words or normalize(tag) in used:
            continue
        ours = sum(1 for c in hidden if c["k"] == team and tag in _tags(c["w"]))
        if not ours:
            continue
        theirs = sum(1 for c in hidden if c["k"] == _other(team) and tag in _tags(c["w"]))
        neutral = sum(1 for c in hidden if c["k"] == "neutral" and tag in _tags(c["w"]))
        deadly = any(c["k"] == "assassin" and tag in _tags(c["w"]) for c in hidden)
        if deadly:
            continue
        score = ours * 1.0 - theirs * 1.4 - neutral * 0.6 + random.random() * 0.2
        scores[tag] = (score, ours)
    if not scores:
        # Nothing clean left: name one of our own words' tags even if broad.
        ours = [c for c in hidden if c["k"] == team]
        for card in ours:
            for tag in _tags(card["w"]):
                if normalize(tag) not in board_words:
                    return tag, 1
        return _LOCALE["fallbackClue"], 1
    tag, (score, ours) = max(scores.items(), key=lambda kv: kv[1][0])
    # Claim only what we are fairly sure of: a crowded clue is trimmed.
    theirs = sum(1 for c in hidden if c["k"] != team and tag in _tags(c["w"]))
    return tag, max(1, min(ours, 4 if theirs == 0 else 2))


def bot_guesses(state: dict) -> list[int]:
    """What an operative bot would open for the current clue, best first.
    Reads only the words, never the key."""
    clue = state["clue"]
    if not clue:
        return []
    word = normalize(clue["word"])
    ranked: list[tuple[float, int]] = []
    for index, card in enumerate(state["board"]):
        if card["up"]:
            continue
        tags = [normalize(t) for t in _tags(card["w"])]
        name = normalize(card["w"])
        score = 0.0
        if word in tags:
            score += 3 - tags.index(word) * 0.3
        if len(word) >= 3 and (word in name or name in word):
            score += 2
        if score:
            ranked.append((score + random.random() * 0.1, index))
    ranked.sort(reverse=True)
    limit = clue["n"] if clue["n"] else len(ranked)
    return [i for _, i in ranked[:limit]]


def _bot_turn(state: dict) -> bool:
    t = now()
    team = state["turn"]
    if state["phase"] == "clue":
        spy = _members(state, team, "spy")
        if not spy or not state["players"][spy[0]]["bot"]:
            return False
        if not state["bot_at"]:
            state["bot_at"] = t + BOT_CLUE_DELAY
            return False
        if t < state["bot_at"]:
            return False
        word, n = bot_clue(state, team)
        _give_clue(state, spy[0], word, n)
        return True
    if state["phase"] == "guess":
        ops = _members(state, team, "op")
        humans = [i for i in ops if not state["players"][i]["bot"]]
        bots = [i for i in ops if state["players"][i]["bot"]]
        if humans or not bots:
            return False
        if not state["bot_at"]:
            state["bot_at"] = t + BOT_GUESS_DELAY
            state["bot_plan"] = bot_guesses(state)
            return False
        if t < state["bot_at"]:
            return False
        plan = [c for c in state["bot_plan"] if not state["board"][c]["up"]]
        bot = bots[0]
        if not plan:
            if state["guesses"] == 0:
                # A clue it cannot place: open a random hidden card rather than stall.
                hidden = [i for i, c in enumerate(state["board"]) if not c["up"]]
                plan = [random.choice(hidden)]
            else:
                _end_turn(state)
                return True
        cell = plan[0]
        # Mark first, then open, so people can follow what the bot is doing.
        if bot not in state["marks"].get(str(cell), []):
            state["marks"][str(cell)] = [bot]
            state["bot_at"] = t + BOT_MARK_DELAY
            state["rev"] += 1
            return True
        state["bot_plan"] = plan[1:]
        _reveal(state, bot, cell)
        if state["phase"] == "guess":
            state["bot_at"] = t + BOT_GUESS_DELAY
        return True
    return False


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "over"):
        return False
    if state["deadline"] and now() >= state["deadline"]:
        if phase == "clue":
            spy = _members(state, state["turn"], "spy")
            word, n = bot_clue(state, state["turn"])
            _give_clue(state, spy[0] if spy else 0, word, n)
            state["history"][-1]["auto"] = True
        elif state["guesses"] == 0 and phase == "guess":
            _end_turn(state)
        else:
            _end_turn(state)
        return True
    _bot_turn(state)
    return True


# ============================== view ==============================

def view_for(state: dict, seat: int | None) -> dict:
    t = now()
    phase = state["phase"]
    me = state["players"][seat] if seat is not None else None
    spymaster = bool(me and me["role"] == "spy")
    over = phase == "over"
    view = {
        "game": "codenames", "phase": phase, "seat": seat,
        "isHost": seat is not None and seat == host_seat(state),
        "players": [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": p["bot"],
                     "team": p["team"], "role": p["role"]} for p in state["players"]],
        "timer": state["timer"], "timerChoices": list(TIMER_CHOICES),
        "wins": state["wins"], "games": state["games"],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state["deadline"] else 0,
        "rev": state["rev"],
    }
    if phase == "setup":
        return view
    view.update({
        "turn": state["turn"], "start": state["start"],
        "clue": state["clue"], "guesses": state["guesses"],
        "left": {team: _left(state, team) for team in TEAMS},
        "total": {team: sum(1 for c in state["board"] if c["k"] == team) for team in TEAMS},
        "marks": state["marks"], "history": state["history"][-12:],
        "winner": state["winner"], "reason": state["reason"],
        "board": [{"w": c["w"], "up": c["up"], "by": c["by"],
                   "k": c["k"] if (c["up"] or spymaster or over) else None,
                   "late": bool(over and c.get("late"))}
                  for c in state["board"]],
    })
    if spymaster and phase == "clue" and me["team"] == state["turn"]:
        ops = _members(state, me["team"], "op")
        if ops and all(state["players"][i]["bot"] for i in ops):
            # The team's operative is a bot: offer clues it understands.
            view["suggest"] = _suggestions(state, me["team"])
    return view


def _suggestions(state: dict, team: str) -> list[dict]:
    hidden = [c for c in state["board"] if not c["up"]]
    board_words = {normalize(c["w"]) for c in hidden}
    out = []
    for tag in {t for c in hidden if c["k"] == team for t in _tags(c["w"])}:
        if tag in VAGUE or normalize(tag) in board_words:
            continue
        ours = sum(1 for c in hidden if c["k"] == team and tag in _tags(c["w"]))
        risky = any(c["k"] == "assassin" and tag in _tags(c["w"]) for c in hidden)
        out.append({"word": tag, "n": ours, "risky": risky})
    out.sort(key=lambda s: (s["risky"], -s["n"]))
    return out[:8]

