"""
X and O, three ways, played as a match.

Modes:
  classic  3x3, three in a row.
  fade     3x3, but each player keeps only three marks: placing a fourth
           wipes out your oldest. Nobody can fill the board, so nobody draws.
  big      4x4, four in a row.

A match is first to 1, 3 or 5 round wins. The starter alternates. An empty
seat is a bot: perfect in classic (with a little randomness in the opening),
searching a few moves ahead in the other two.

English only: every word a player reads lives in the client.
"""
from __future__ import annotations

import random
import time
from functools import lru_cache

MAX_SEATS = 2
MODES = ("classic", "fade", "big")
TARGETS = (1, 3, 5)
TURN_SECONDS = 20
ROUND_PAUSE = 2.8
MARKS = ("X", "O")
SLIP = 0.12


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def _seat(person: dict | None, index: int) -> dict:
    bot = person is None
    person = person or {"id": -(index + 1), "name": "", "photo": ""}
    return {"id": person["id"], "name": person.get("name", ""), "photo": person.get("photo", ""), "bot": bot}


def new_match(people: list[dict], host: int) -> dict:
    seats = [_seat(people[i] if i < len(people) else None, i) for i in range(MAX_SEATS)]
    return {"game": "xo", "host": host, "players": seats, "phase": "setup", "mode": "classic",
            "target": 3, "scores": [0, 0], "rev": 0, "round": 0, "starter": 0, "wins": {}}


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat["id"] == user_id and not seat["bot"]:
            return index
    return None


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    bot = next((p for p in state["players"] if p["bot"]), None)
    if bot is None:
        raise Illegal("full")
    bot.update(id=person["id"], name=person["name"], photo=person.get("photo", ""), bot=False)
    state["rev"] += 1


# ═══════════════════════════ geometry ═══════════════════════════

def size_of(mode: str) -> int:
    return 4 if mode == "big" else 3


def lines(n: int) -> list[tuple[int, ...]]:
    out = []
    for r in range(n):
        out.append(tuple(r * n + c for c in range(n)))
    for c in range(n):
        out.append(tuple(r * n + c for r in range(n)))
    out.append(tuple(i * n + i for i in range(n)))
    out.append(tuple(i * n + (n - 1 - i) for i in range(n)))
    return out


LINES = {3: lines(3), 4: lines(4)}


def winner_line(board: list[str], n: int) -> tuple[str, tuple[int, ...]] | None:
    for line in LINES[n]:
        first = board[line[0]]
        if first and all(board[i] == first for i in line):
            return first, line
    return None


# ═══════════════════════════ rounds ═══════════════════════════

def _round(state: dict) -> None:
    n = size_of(state["mode"])
    state["board"] = [""] * (n * n)
    state["order"] = [[], []]           # cells in the order each seat placed them
    state["turn"] = state["starter"]
    state["line"] = None
    state["round_winner"] = None
    state["phase"] = "playing"
    state["round"] += 1
    _clock(state)
    state["rev"] += 1


def _clock(state: dict) -> None:
    state["deadline"] = now() + TURN_SECONDS
    state["bot_at"] = now() + random.uniform(0.55, 1.1)


def place(state: dict, seat: int, cell: int) -> None:
    board = state["board"]
    if not 0 <= cell < len(board) or board[cell]:
        raise Illegal("illegalMove")
    mark = MARKS[seat]
    board[cell] = mark
    order = state["order"][seat]
    order.append(cell)
    faded = None
    if state["mode"] == "fade" and len(order) > 3:
        faded = order.pop(0)
        board[faded] = ""
    state["last"] = {"seat": seat, "cell": cell, "faded": faded, "at": int(now() * 1000)}
    n = size_of(state["mode"])
    won = winner_line(board, n)
    if won:
        state["line"] = list(won[1])
        _end_round(state, seat)
    elif all(board):
        _end_round(state, None)
    else:
        state["turn"] = 1 - seat
        _clock(state)
    state["rev"] += 1


def _end_round(state: dict, winner: int | None) -> None:
    state["round_winner"] = winner
    if winner is not None:
        state["scores"][winner] += 1
    state["starter"] = 1 - state["starter"]
    if winner is not None and state["scores"][winner] >= state["target"]:
        state["phase"] = "over"
        state["winner"] = winner
        who = state["players"][winner]
        if not who["bot"]:
            state["wins"][str(who["id"])] = int(state["wins"].get(str(who["id"]), 0)) + 1
    else:
        state["phase"] = "round"
        state["next_at"] = now() + ROUND_PAUSE


# ═══════════════════════════ the bot ═══════════════════════════

@lru_cache(maxsize=None)
def _minimax(board: str, me: str) -> int:
    """Classic 3x3: +1 if `me` (to move) wins with best play, 0 draw, -1 loss."""
    cells = list(board)
    other = "O" if me == "X" else "X"
    won = winner_line([c if c != "." else "" for c in cells], 3)
    if won:
        return 1 if won[0] == me else -1
    if "." not in cells:
        return 0
    best = -2
    for i, c in enumerate(cells):
        if c == ".":
            cells[i] = me
            best = max(best, -_minimax("".join(cells), other))
            cells[i] = "."
            if best == 1:
                break
    return best


def _classic_pick(board: list[str], mark: str) -> int:
    free = [i for i, c in enumerate(board) if not c]
    if len(free) == 9 and random.random() < 0.5:
        return random.choice(free)
    # Now and then it plays by feel instead of by proof, so a sharp player
    # can beat it; a perfect bot at noughts and crosses only ever draws.
    if len(free) <= 7 and random.random() < SLIP:
        return random.choice(free)
    other = "O" if mark == "X" else "X"
    key = "".join(c or "." for c in board)
    scored = []
    for i in free:
        trial = list(key)
        trial[i] = mark
        scored.append((-_minimax("".join(trial), other), random.random(), i))
    return max(scored)[2]


def _heuristic(board: list[str], n: int, mark: str) -> float:
    other = "O" if mark == "X" else "X"
    score = 0.0
    for line in LINES[n]:
        mine = sum(board[i] == mark for i in line)
        theirs = sum(board[i] == other for i in line)
        if mine and not theirs:
            score += 4 ** mine
        elif theirs and not mine:
            score -= 4 ** theirs * 1.1
    return score


def _simulate(state: dict, seat: int, cell: int) -> tuple[list[str], list[list[int]], str | None]:
    board = list(state["board"])
    order = [list(state["order"][0]), list(state["order"][1])]
    board[cell] = MARKS[seat]
    order[seat].append(cell)
    if state["mode"] == "fade" and len(order[seat]) > 3:
        board[order[seat].pop(0)] = ""
    won = winner_line(board, size_of(state["mode"]))
    return board, order, (won[0] if won else None)


def bot_pick(state: dict, seat: int) -> int:
    board = state["board"]
    mark = MARKS[seat]
    free = [i for i, c in enumerate(board) if not c]
    if state["mode"] == "classic":
        return _classic_pick(board, mark)
    n = size_of(state["mode"])
    # Win now; otherwise do not hand the other side a win on the next move.
    for cell in free:
        if _simulate(state, seat, cell)[2] == mark:
            return cell
    best, best_score = random.choice(free), -1e9
    for cell in free:
        board2, order2, _ = _simulate(state, seat, cell)
        probe = {**state, "board": board2, "order": order2}
        free2 = [i for i, c in enumerate(board2) if not c]
        threat = any(_simulate(probe, 1 - seat, c)[2] == MARKS[1 - seat] for c in free2)
        score = _heuristic(board2, n, mark) - (1000 if threat else 0) + random.random()
        if score > best_score:
            best, best_score = cell, score
    return best


# ═══════════════════════════ the table ═══════════════════════════

def _host(state: dict, seat: int | None) -> bool:
    if seat is None:
        return False
    ids = [p["id"] for p in state["players"]]
    return state["players"][seat]["id"] == state.get("host") or (state.get("host") not in ids and seat == 0)


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action in ("mode", "target", "go"):
        if not _host(state, seat):
            raise Illegal("notHost")
        if state["phase"] != "setup":
            raise Illegal("badPhase")
        if action == "mode":
            mode = str(body.get("mode") or "")
            if mode not in MODES:
                raise Illegal("badMode")
            state["mode"] = mode
        elif action == "target":
            target = int(body.get("target") or 0)
            if target not in TARGETS:
                raise Illegal("badTarget")
            state["target"] = target
        else:
            state["scores"] = [0, 0]
            state["round"] = 0
            state["winner"] = None
            state["starter"] = random.randrange(2)
            _round(state)
            return
        state["rev"] += 1
        return
    if seat is None:
        raise Illegal("watchingOnly")
    if action == "again":
        if state["phase"] != "over":
            raise Illegal("badPhase")
        state["phase"] = "setup"
        state["rev"] += 1
        return
    if action == "cell":
        if state["phase"] != "playing":
            raise Illegal("badPhase")
        if state["turn"] != seat:
            raise Illegal("notYourTurn")
        place(state, seat, int(body.get("cell", -1)))
        return
    raise Illegal("badAction")


def step(state: dict) -> bool:
    if state["phase"] == "round":
        if now() >= state.get("next_at", 0):
            _round(state)
        return True
    if state["phase"] != "playing":
        return False
    seat = state["turn"]
    if state["players"][seat]["bot"]:
        if now() >= state["bot_at"]:
            place(state, seat, bot_pick(state, seat))
        return True
    if now() >= state["deadline"]:
        place(state, seat, bot_pick(state, seat))
    return True


def view_for(state: dict, seat: int | None) -> dict:
    out = {
        "game": "xo", "rev": state["rev"], "phase": state["phase"], "seat": seat,
        "mode": state["mode"], "target": state["target"], "modes": list(MODES), "targets": list(TARGETS),
        "host": _host(state, seat), "scores": list(state["scores"]), "round": state["round"],
        "players": [{"name": p["name"], "photo": p["photo"], "bot": p["bot"], "mark": MARKS[i],
                     "wins": int(state["wins"].get(str(p["id"]), 0))} for i, p in enumerate(state["players"])],
    }
    if state.get("board") is None:
        return out
    fading = None
    if state["mode"] == "fade" and state["phase"] == "playing":
        order = state["order"][state["turn"]]
        if len(order) >= 3:
            fading = order[0]
    out.update({
        "board": list(state["board"]), "size": size_of(state["mode"]), "turn": state.get("turn", 0),
        "line": state.get("line"), "last": state.get("last"), "fading": fading,
        "roundWinner": state.get("round_winner"), "winner": state.get("winner"),
        "endsIn": max(0, int((state.get("deadline", 0) - now()) * 1000)) if state["phase"] == "playing" else 0,
    })
    return out

