"""A machine player for baloot.

Not a tree search and not a network, but the rules of play anyone who has sat
at a table knows: win with the cheapest card, never waste a valuable one on a
trick already lost, feed your partner when he is winning, and pull trump while
you hold the strength. That is enough to be a respectable partner and an
annoying opponent, and it answers in a fraction of a millisecond, which is
what matters when one person sits down with three machines.

It does not cheat: it reads only what a player in that seat can see.
"""
from __future__ import annotations

import random

from .. import cards
from ..cards import rank_of, suit_of
from . import engine
from .engine import team_of

# Rough card strength used only while bidding. Nothing to do with scoring,
# everything to do with confidence.
_BID_TRUMP = {"J": 9, "9": 7, "A": 5, "10": 3, "K": 2, "Q": 1, "8": 0, "7": 0}
_BID_PLAIN = {"A": 5, "10": 3, "K": 2, "Q": 1, "J": 1, "9": 0, "8": 0, "7": 0}


# ─────────────────────────── bidding ───────────────────────────

def _hokum_strength(hand: list[str], trump: str) -> int:
    trumps = [c for c in hand if suit_of(c) == trump]
    score = sum(_BID_TRUMP[rank_of(c)] for c in trumps)
    score += 2 * max(0, len(trumps) - 2)            # length is strength
    score += sum(_BID_PLAIN[rank_of(c)] for c in hand if suit_of(c) != trump) // 2
    # A void suit means an early cut.
    voids = sum(1 for s in cards.SUIT_ORDER
                if s != trump and not any(suit_of(c) == s for c in hand))
    return score + 2 * voids


def _sun_strength(hand: list[str]) -> int:
    score = sum(_BID_PLAIN[rank_of(c)] for c in hand)
    # Sun likes supported aces and dislikes long weak suits.
    for suit in cards.SUIT_ORDER:
        same = [c for c in hand if suit_of(c) == suit]
        if any(rank_of(c) == "A" for c in same) and len(same) >= 2:
            score += 2
    return score


def choose_bid(state: dict, seat: int) -> dict:
    """Returns {'call': ..., 'suit': ...}. Deliberately conservative: a failed
    contract hands the whole hand to the other side.
    """
    hand = state["hands"][seat]
    pending = state.get("pending_bid")
    if pending:
        # A hokum stands and this is our window to turn it. Over a partner's
        # hokum only a commanding sun hand speaks; over an opponent's, a good
        # one does. Ashkal hands the face-up card to our partner, so it wants
        # that card to be worth having in sun.
        ours = team_of(pending["seat"]) == team_of(seat)
        sun = _sun_strength(hand)
        if sun >= (21 if ours else 17):
            return {"call": "sun"}
        if (not ours and engine.may_ashkal(state, seat)
                and rank_of(state["flipped"]) in {"A", "10"} and sun >= 14):
            return {"call": "ashkal"}
        return {"call": "pass"}

    if state["bid_round"] == 1:
        suit = suit_of(state["flipped"])
        if _hokum_strength(hand, suit) >= 13:
            return {"call": "hokum", "suit": suit}
        if _sun_strength(hand) >= 17:
            return {"call": "sun"}
        # Ashkal without a standing hokum is only open when the majlis turns
        # the federation rule off. Then the old judgement applies: holding
        # almost none of the face-up suit, with a hand that backs a partner.
        if engine.may_ashkal(state, seat):
            mine = sum(1 for c in hand if suit_of(c) == suit)
            support = sum(_BID_PLAIN[rank_of(c)] for c in hand if suit_of(c) != suit)
            support += 3 * sum(1 for s in cards.SUIT_ORDER
                               if s != suit and not any(suit_of(c) == s for c in hand))
            if mine <= 1 and support >= 15:
                return {"call": "ashkal"}
        return {"call": "pass"}

    best_suit = max(cards.SUIT_ORDER, key=lambda s: _hokum_strength(hand, s))
    best = _hokum_strength(hand, best_suit)
    sun = _sun_strength(hand)
    # No special bar for the last speaker.
    #
    # He used to buy on almost anything rather than let the hand be thrown in,
    # and the table saw a machine "changing the hokum" on a hand nobody wanted
    # — which is also why waraq never once happened. A man who would not buy
    # this hand in third place does not buy it in fourth: if none of the four
    # wants it, the cards go back, and that is the rule doing its work.
    if sun >= 18 and sun >= best:
        return {"call": "sun"}
    if best >= 14:
        return {"call": "hokum", "suit": best_suit}
    return {"call": "pass"}


# ─────────────────────────── card play ───────────────────────────

def _value(card: str, trump: str | None) -> int:
    return cards.value(card, trump)


def _cheapest_winner(options: list[str], trick: list, lead: str,
                     trump: str | None) -> str | None:
    """The cheapest card that takes the trick. Winning cheaply is the game."""
    winners = []
    for card in options:
        plays = [(s, c) for s, c in trick] + [(99, card)]
        if cards.trick_winner(plays, lead, trump) == 99:
            winners.append(card)
    if not winners:
        return None
    return min(winners, key=lambda c: (_value(c, trump), cards.strength(c, trump)))


def _safest_discard(options: list[str], trump: str | None) -> str:
    """The cheapest throw: least valuable, then weakest, avoiding trump."""
    return min(options, key=lambda c: (
        1 if (trump and suit_of(c) == trump) else 0,
        _value(c, trump),
        cards.strength(c, trump),
    ))


def _fattest(options: list[str], trump: str | None) -> str:
    """The richest card to drop on a trick the partner already owns."""
    return max(options, key=lambda c: (
        _value(c, trump),
        -1 if (trump and suit_of(c) == trump) else 0,
    ))


def _lead_card(state: dict, seat: int, options: list[str], rng: random.Random) -> str:
    trump = state["trump"]
    hand = state["hands"][seat]

    if trump:
        mine = [c for c in options if suit_of(c) == trump]
        seen = {c for t in state["tricks"] for _, c in t["plays"] if suit_of(c) == trump}
        left = 8 - len(seen) - len(mine)
        # The declarer pulls trump out of the opponents' hands while he holds
        # the strongest one.
        if seat == state["declarer"] and mine and left > 0:
            strongest = max(mine, key=lambda c: cards.strength(c, trump))
            if cards.strength(strongest, trump) >= 7:
                return strongest

    # A supported ace usually wins, so lead it before it can be cut. Support is
    # a condition, not a description: an ace alone in its suit means the suit is
    # short for me and long for somebody else, and the first opponent to run
    # out cuts it, costing me eleven points by my own hand.
    for suit in cards.SUIT_ORDER:
        if trump and suit == trump:
            continue
        same = [c for c in options if suit_of(c) == suit]
        held = [c for c in hand if suit_of(c) == suit]
        if len(held) >= 2 and any(rank_of(c) == "A" for c in same):
            return next(c for c in same if rank_of(c) == "A")

    plain = [c for c in options if not (trump and suit_of(c) == trump)] or options
    # Lead from a short suit: it brings a cut closer and gives nothing away.
    lengths = {s: sum(1 for c in hand if suit_of(c) == s) for s in cards.SUIT_ORDER}
    return min(plain, key=lambda c: (_value(c, trump), lengths[suit_of(c)],
                                     cards.strength(c, trump), rng.random()))


def choose_card(state: dict, seat: int) -> str:
    options = engine.legal_moves(state, seat)
    if len(options) == 1:
        return options[0]
    rng = random.Random()
    trick = state["trick"] if engine.trick_open(state) else []
    trump = state["trump"]

    if not trick:
        return _lead_card(state, seat, options, rng)

    lead = state["lead_suit"]
    winner = cards.trick_winner([(s, c) for s, c in trick], lead, trump)
    partner_leads = team_of(winner) == team_of(seat)
    last_to_play = len(trick) == 3

    if partner_leads:
        # Partner is winning: fatten the trick if it is closing, otherwise keep
        # the valuable cards back.
        if last_to_play:
            return _fattest(options, trump)
        cheap = [c for c in options if _value(c, trump) <= 4]
        return _safest_discard(cheap or options, trump)

    win = _cheapest_winner(options, trick, lead, trump)
    if win is not None:
        # Do not spend an expensive trump on a poor trick while others still play.
        pot = sum(_value(c, trump) for _, c in trick)
        if (not last_to_play and trump and suit_of(win) == trump
                and _value(win, trump) >= 14 and pot < 10):
            return _safest_discard(options, trump)
        return win
    return _safest_discard(options, trump)


# ─────────────────────────── doubling ───────────────────────────

def _power(hand: list[str], trump: str | None) -> int:
    """Strength of a completed eight-card hand: the nerve to double."""
    return sum((_BID_TRUMP if (trump and suit_of(c) == trump) else _BID_PLAIN)[rank_of(c)]
               for c in hand)


# Rising thresholds: a double is nerve, gahwa is the whole match. The machine only
# gambles on a hand that carries it.
_LADDER_NEED = {"double": 24, "double_closed": 30, "three": 29, "four": 33,
                "gahwa": 41}


def choose_double(state: dict, seat: int) -> str:
    """A ladder call, or `skip`."""
    power = _power(state["hands"][seat], state["trump"])
    step_now = state.get("multiplier", 1)
    mine = team_of(seat) == team_of(state["declarer"])
    for call, after in engine.LADDER_AFTER.items():
        if after != step_now or engine.LADDER_BY_DECLARER[call] != mine:
            continue
        if power >= _LADDER_NEED[call]:
            return call
    return "skip"


# ─────────────────────────── driving the table ───────────────────────────

def _cheapest(state: dict, seat: int) -> str:
    return _safest_discard(engine.legal_moves(state, seat), state["trump"])


def _timeout(state: dict) -> bool:
    """Carries out what an expired clock means.

    Twice the system plays for the absent player, the cheapest legal card or a
    pass, and on the third the machine takes the seat until he presses "I'm
    back". This does not punish a moment of lost signal, and it does not freeze
    the table for someone who got up and left his phone.
    """
    phase = state["phase"]
    if phase == "doubling":
        team = state["double_turn"]
        speaker = next(s for s in engine.SEATS if team_of(s) == team)
        engine.double(state, speaker, "skip")
        return True
    seat = state.get("turn")
    if seat is None:
        return False
    state["misses"][seat] = state["misses"].get(seat, 0) + 1
    if state["misses"][seat] >= engine.MISS_LIMIT:
        state.setdefault("away", {})[str(seat)] = True
    if phase == "bidding":
        # A missed turn is a pass, always. Nothing is bought on a man's behalf
        # because his phone went to sleep.
        engine.bid(state, seat, "pass")
    elif phase == "playing":
        engine.play(state, seat, _cheapest(state, seat))
    else:
        return False
    return True


def _pending(state: dict) -> bool:
    """Is the table still waiting on a human clock? Then the driver stays awake."""
    if not state.get("deadline"):
        return False
    return any(not engine.is_auto(state, s) for s in engine.waiting_on(state))


def step(state: dict) -> bool:
    """Plays one move if the turn belongs to a machine, or carries out a
    timeout. Returns True when the driver should come back.

    One move at a time, never a burst: the interface shows each card as it
    lands, and three cards appearing at once is a trick nobody saw played.

    It also returns True while a pause is running or a human clock is ticking.
    Not because anything moved, but so the driver returns to find it finished.
    That is bounded by its nature: three timeouts and the machine takes over.
    """
    phase = state.get("phase")
    if phase == "match_done":
        return False
    if phase == "lobby":
        # A table of machines needs nobody's word, and a table of people gets
        # one minute to sort its seats out before it deals itself.
        if all(engine.is_auto(state, s) for s in engine.SEATS) or engine.expired(state):
            engine.start_match(state)
        return True
    if phase == "hand_done":
        # Nobody is waiting: an all-machine table would sit here forever.
        if all(engine.is_auto(state, s) for s in engine.SEATS):
            engine.next_hand(state)
            return True
        return False

    # A fresh deal is being shown. Nothing moves, and the clock has already
    # been given the extra time, so the first speaker gets his full turn.
    if engine.dealing(state):
        return True

    # While a finished trick is on display nothing moves either, then it is
    # swept and the count starts again. This is how all four players get to see
    # all four cards.
    if engine.holding(state):
        return True
    if engine.close_trick(state):
        return True

    if engine.expired(state) and _timeout(state):
        return True

    if phase == "bidding":
        seat = state["turn"]
        if not engine.is_auto(state, seat):
            return _pending(state)
        call = choose_bid(state, seat)
        engine.bid(state, seat, call["call"], call.get("suit"))
        return True

    if phase == "doubling":
        team = state.get("double_turn")
        seats = [s for s in engine.SEATS if team_of(s) == team]
        if any(not engine.is_auto(state, s) for s in seats):
            return _pending(state)
        # A fully machine team: the bolder of the two decides.
        calls = {s: choose_double(state, s) for s in seats}
        raiser = next((s for s, c in calls.items() if c != "skip"), None)
        engine.double(state, raiser if raiser is not None else seats[0],
                      calls.get(raiser, "skip"))
        return True

    if phase != "playing":
        return False

    # Declarations come before the card. A machine declares everything it holds
    # as soon as the window opens, one seat per step so each call is heard on
    # its own.
    if engine.declaring_open(state):
        for seat in engine.SEATS:
            if (engine.is_auto(state, seat) and state["found"].get(seat)
                    and seat not in state["declared"]):
                engine.declare(state, seat)
                return True
    window = state.get("baloot_window")
    if window is not None and engine.is_auto(state, window):
        engine.call_baloot(state, window)
        return True

    seat = state["turn"]
    hand = state["hands"][seat]
    # One card left is not a decision, so nobody is made to press for it. The
    # exception is a last card that could still be called on: a player holding
    # the trump king or queen would lose his twenty to our convenience.
    if len(hand) == 1 and not _may_call_baloot(state, seat, hand[0]):
        engine.play(state, seat, hand[0])
        return True
    if not engine.is_auto(state, seat):
        return _pending(state)
    engine.play(state, seat, choose_card(state, seat))
    return True


def _may_call_baloot(state: dict, seat: int, card: str) -> bool:
    """Would playing this card open a baloot window its owner has not used?"""
    trump = state.get("trump")
    return bool(trump and state.get("baloot_holder") == seat
                and state.get("baloot_called") is None
                and card[-1] == trump and card[:-1] in {"K", "Q"})

