"""
Pool (8-ball) - the rules, on top of physics.py.

Flow: the breaker shoots; the table stays open until someone legally pots
balls of one group (solids 1-7 or stripes 9-15), which becomes theirs.
A shot is legal when the cue ball first touches one of your balls (any
non-8 on an open table, the 8 once your group is cleared), and afterwards
some ball is pocketed or reaches a cushion, and the cue ball stays up.
A foul hands the opponent the cue ball anywhere on the table.
Potting your ball keeps your turn. Potting the 8 wins once your group is
clear - before that, or together with a foul, it loses.

Clients send an intention (angle, power, spin, cue placement); the server
simulates and keeps the result. The view carries the last shot's starting
positions and the cue's velocity so every client can replay it exactly.
"""
from __future__ import annotations

import json
import math
import pathlib
import random
import time

from . import physics as P

HERE = pathlib.Path(__file__).resolve().parent
_LOCALE = json.loads((HERE / "locales" / "ar.json").read_text(encoding="utf-8"))
SHOT_SECONDS = 50
MAX_SEATS = 2


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def group_of(ball: int) -> int | None:
    if 1 <= ball <= 7:
        return 0
    if 9 <= ball <= 15:
        return 1
    return None


def new_match(people: list[dict], host: int = 0) -> dict:
    players = []
    for i in range(2):
        if i < len(people):
            p = people[i]
            players.append({"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": False})
        else:
            players.append({"id": -(300 + i), "name": random.choice(_LOCALE["bots"]), "photo": "", "bot": True})
    breaker = random.randrange(2)
    return {
        "game": "pool", "players": players, "turn": breaker, "breaker": breaker,
        "balls": P.rack(), "groups": [None, None], "open": True, "breaking": True,
        "ballInHand": False, "phase": "playing", "winner": None, "reason": "",
        "shot": None, "shots": 0, "note": "break", "foul": "", "rev": 0,
        "deadline": time.time() + SHOT_SECONDS, "wins": [0, 0], "host": host,
    }


def seat_of(state: dict, user_id: int) -> int | None:
    for i, p in enumerate(state["players"]):
        if not p.get("bot") and p.get("id") == user_id:
            return i
    return None


def _remaining(state: dict, group: int | None) -> list[int]:
    return [b["id"] for b in state["balls"] if b["in"] and group is not None and group_of(b["id"]) == group]


def _targets(state: dict, seat: int) -> set[int]:
    mine = state["groups"][seat]
    if mine is None:
        return {b["id"] for b in state["balls"] if b["in"] and b["id"] not in (0, 8)}
    left = _remaining(state, mine)
    return set(left) if left else {8}


def _valid_spot(state: dict, x: float, y: float) -> bool:
    if not (P.R <= x <= P.W - P.R and P.R <= y <= P.H - P.R):
        return False
    for b in state["balls"]:
        if b["in"] and b["id"] != 0:
            dx = b["x"] - x
            dy = b["y"] - y
            if dx * dx + dy * dy < (2 * P.R + 0.5) * (2 * P.R + 0.5):
                return False
    return True


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action == "rematch_request":
        raise Illegal("badAction")
    if state["phase"] != "playing":
        raise Illegal("gameOver")
    if seat is None or seat != state["turn"]:
        raise Illegal("notYourTurn")
    if action != "shoot":
        raise Illegal("badAction")
    if body.get("rev") != state["rev"]:
        raise Illegal("staleMove")
    try:
        angle = float(body.get("angle"))
        power = float(body.get("power"))
        spin = float(body.get("spin") or 0.0)
    except (TypeError, ValueError):
        raise Illegal("badShot") from None
    if not all(math.isfinite(v) for v in (angle, power, spin)) or not 0.02 <= power <= 1.0:
        raise Illegal("badShot")
    spin = max(-1.0, min(1.0, spin))
    place = body.get("place")
    if state["ballInHand"] and isinstance(place, (list, tuple)) and len(place) == 2:
        try:
            x, y = float(place[0]), float(place[1])
        except (TypeError, ValueError):
            raise Illegal("badPlacement") from None
        if not _valid_spot(state, x, y):
            raise Illegal("badPlacement")
        cue = state["balls"][0]
        cue.update(x=x, y=y)
        cue["in"] = True
    _shoot(state, seat, angle, power, spin)


def _shoot(state: dict, seat: int, angle: float, power: float, spin: float) -> None:
    speed = P.MAX_SPEED * power
    vx = math.cos(angle) * speed
    vy = math.sin(angle) * speed
    before = [[b["id"], b["x"], b["y"]] for b in state["balls"] if b["in"]]
    targets = _targets(state, seat)
    mine = state["groups"][seat]
    result = P.simulate(state["balls"], vx, vy, spin)
    sunk = result["pocketed"]
    first = result["first"]
    scratch = 0 in sunk
    foul = ""
    if first is None:
        foul = "noHit"
    elif first not in targets:
        foul = "wrongFirst"
    elif not sunk and not result["railsAfter"]:
        foul = "noRail"
    if scratch:
        foul = "scratch"
    eight = 8 in sunk
    state["shots"] += 1
    state["shot"] = {"n": state["shots"], "seat": seat, "before": before, "vx": vx, "vy": vy, "spin": spin,
                     "pocketed": sunk, "foul": foul}
    # Everyone watches the shot roll out before the next one may start.
    state["busy_until"] = time.time() + result["steps"] * P.DT + 0.8
    breaking = state["breaking"]
    state["breaking"] = False

    if eight:
        if breaking:
            # The 8 on the break comes back to its spot.
            ball = next(b for b in state["balls"] if b["id"] == 8)
            ball.update(x=740.0 + 2 * (2 * P.R + 0.2) * 0.8660254, y=250.0)
            ball["in"] = True
            while not _spot_free(state, ball):
                ball["x"] += 2 * P.R + 1
        else:
            cleared = mine is not None and not _remaining(state, mine)
            win = cleared and not foul
            _end(state, seat if win else 1 - seat, "eight" if win else ("eightFoul" if cleared else "eightEarly"))
            return

    if state["open"] and not foul and not breaking:
        claimed = next((group_of(n) for n in sunk if group_of(n) is not None), None)
        if claimed is not None:
            state["groups"][seat] = claimed
            state["groups"][1 - seat] = 1 - claimed
            state["open"] = False
            mine = claimed

    if scratch:
        cue = state["balls"][0]
        cue["in"] = True
        cue.update(x=250.0, y=250.0)
        while not _spot_free(state, cue):
            cue["x"] -= 2 * P.R + 1

    if mine is not None:
        kept = any(group_of(n) == mine for n in sunk)
    else:
        kept = any(n not in (0, 8) for n in sunk)
    keep_turn = not foul and kept
    state["foul"] = foul
    state["ballInHand"] = bool(foul)
    state["note"] = "foul" if foul else ("again" if keep_turn else "turn")
    if not keep_turn:
        state["turn"] = 1 - seat
    state["deadline"] = state["busy_until"] + SHOT_SECONDS
    state["rev"] += 1


def _spot_free(state: dict, ball: dict) -> bool:
    for b in state["balls"]:
        if b is ball or not b["in"]:
            continue
        dx = b["x"] - ball["x"]
        dy = b["y"] - ball["y"]
        if dx * dx + dy * dy < (2 * P.R + 0.5) * (2 * P.R + 0.5):
            return False
    return True


def _end(state: dict, winner: int, reason: str) -> None:
    state["phase"] = "done"
    state["winner"] = winner
    state["reason"] = reason
    state["wins"][winner] += 1
    state["ballInHand"] = False
    state["rev"] += 1


# ============================== the clock and the bot ==============================

def _clear(state: dict, ax: float, ay: float, bx: float, by: float, skip: set[int]) -> bool:
    """Is the path of a ball from A to B free of other balls?"""
    dx = bx - ax
    dy = by - ay
    length2 = dx * dx + dy * dy
    if length2 <= 0:
        return True
    for b in state["balls"]:
        if not b["in"] or b["id"] in skip:
            continue
        t = ((b["x"] - ax) * dx + (b["y"] - ay) * dy) / length2
        if t <= 0 or t >= 1:
            continue
        px = ax + dx * t - b["x"]
        py = ay + dy * t - b["y"]
        if px * px + py * py < (2 * P.R) * (2 * P.R):
            return False
    return True


def _bot_plan(state: dict, seat: int, cx: float, cy: float) -> tuple[float, float, float] | None:
    best = None
    for b in state["balls"]:
        if not b["in"] or b["id"] not in _targets(state, seat):
            continue
        for index, (px, py) in enumerate(P.POCKETS):
            tx, ty = b["x"], b["y"]
            dx, dy = px - tx, py - ty
            dist = math.sqrt(dx * dx + dy * dy) or 1.0
            gx = tx - dx / dist * 2 * P.R
            gy = ty - dy / dist * 2 * P.R
            ax, ay = gx - cx, gy - cy
            aim = math.sqrt(ax * ax + ay * ay) or 1.0
            cut = (ax * dx + ay * dy) / (aim * dist)
            if cut < 0.25:
                continue
            if not _clear(state, cx, cy, gx, gy, {0, b["id"]}) or not _clear(state, tx, ty, px, py, {b["id"]}):
                continue
            score = cut * 3 - (aim + dist) / 900.0 - (0.15 if index in (1, 4) else 0.0)
            if best is None or score > best[0]:
                best = (score, math.atan2(ay, ax), min(1.0, 0.25 + (aim + dist) / 1500.0))
    if best is None:
        return None
    return best[1], best[2], 0.0


def step(state: dict) -> bool:
    if state["phase"] != "playing":
        return False
    seat = state["turn"]
    player = state["players"][seat]
    if not player.get("bot"):
        if time.time() > max(state["deadline"], state.get("busy_until", 0) + SHOT_SECONDS) + 1:
            # Out of time: the opponent gets the cue ball in hand.
            state["turn"] = 1 - seat
            state["ballInHand"] = True
            state["foul"] = "time"
            state["note"] = "foul"
            state["deadline"] = time.time() + SHOT_SECONDS
            state["rev"] += 1
            return True
        return True
    if time.time() < state.get("busy_until", 0) + 0.9:
        return True                   # the table is still rolling on screen
    cue = state["balls"][0]
    place = None
    if state["breaking"]:
        angle = math.atan2(250.0 - cue["y"] + random.uniform(-3, 3), 740.0 - cue["x"])
        _shoot(state, seat, angle, 0.95, 0.0)
        return True
    if state["ballInHand"]:
        for _ in range(60):
            x, y = random.uniform(60, 940), random.uniform(60, 440)
            if _valid_spot(state, x, y):
                plan = _bot_plan(state, seat, x, y)
                if plan:
                    place = (x, y)
                    break
        if place is None:
            place = (250.0, 250.0) if _valid_spot(state, 250.0, 250.0) else (200.0, 120.0)
        cue.update(x=place[0], y=place[1])
        cue["in"] = True
    plan = _bot_plan(state, seat, cue["x"], cue["y"])
    if plan is None:
        target = min((b for b in state["balls"] if b["in"] and b["id"] in _targets(state, seat)),
                     key=lambda b: (b["x"] - cue["x"]) ** 2 + (b["y"] - cue["y"]) ** 2)
        plan = (math.atan2(target["y"] - cue["y"], target["x"] - cue["x"]), 0.45, 0.0)
    angle, power, spin = plan
    angle += random.gauss(0, 0.012)
    _shoot(state, seat, angle, power, spin)
    return True


# ============================== view ==============================

def view_for(state: dict, seat: int | None) -> dict:
    t = time.time()
    return {
        "game": "pool", "seat": seat, "turn": state["turn"], "phase": state["phase"],
        "players": state["players"], "balls": state["balls"], "groups": state["groups"],
        "open": state["open"], "breaking": state["breaking"], "ballInHand": state["ballInHand"],
        "winner": state["winner"], "reason": state["reason"], "shot": state["shot"],
        "note": state["note"], "foul": state["foul"], "rev": state["rev"], "wins": state["wins"],
        "targets": sorted(_targets(state, seat)) if seat is not None and state["phase"] == "playing" else [],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)),
        "busyFor": max(0, int((state.get("busy_until", 0) - t) * 1000)),
        "remaining": [len(_remaining(state, 0)), len(_remaining(state, 1))],
    }

الالعاب/الجاسوس_بالصور/engine.py:
"""
الجاسوس بالصور — كلّكم ترون صورةً واحدة إلّا واحدًا يرى صورةً قريبة منها، وهو لا يدري.

الجولة: كلٌّ يكتب كلمةً واحدة تصف صورته (التلميح) ← تُكشف التلميحات ويصوّت كلٌّ على
من يظنّه الجاسوس ← يُكشف الجاسوس والصورتان ومن صوّت لمن.
النقاط: من صوّت على الجاسوس +١٠٠. وإن لم يُمسك (لم يأخذ أكثر الأصوات وحده) فله +٣٠٠.
"""
from __future__ import annotations

import json
import pathlib
import random

from games.party import (Illegal, base_view, drop_bots, fill_bots, host_seat, now, player_view,
                         seat_of, seats)
from games import party

HERE = pathlib.Path(__file__).resolve().parent
PAIRS = json.loads((HERE / "content" / "pairs.json").read_text(encoding="utf-8"))["pairs"]

MIN_SEATS = 3
MAX_SEATS = 10
ROUND_CHOICES = (3, 5, 7)
DEFAULT_ROUNDS = 5
CLUE_SECONDS = 45
VOTE_SECONDS = 35
REVEAL_SECONDS = 25
MAX_CLUE = 24
VOTE_POINTS = 100
ESCAPE_POINTS = 300
QUIET = ("setup", "reveal", "final")

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "MAX_SEATS"]


def new_match(people: list[dict], host: int) -> dict:
    state = {"game": "jasoos", "host": host, "players": seats(people, MAX_SEATS), "rounds": DEFAULT_ROUNDS,
             "round": 0, "phase": "setup", "phase_at": now(), "deadline": 0.0, "pair": None, "flip": False,
             "spy": None, "clues": {}, "votes": {}, "ready": [], "result": None, "used": [], "bot_due": {},
             "history": [], "rev": 0}
    fill_bots(state, MIN_SEATS)
    return state


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)


def set_bots(state: dict, on: bool) -> None:
    party.set_bots(state, on, MIN_SEATS, QUIET)


def _pic(state: dict, player_id: int) -> list:
    pair = PAIRS[state["pair"]]
    crowd, odd = (pair["b"], pair["a"]) if state["flip"] else (pair["a"], pair["b"])
    return odd if player_id == state["spy"] else crowd


def _begin_round(state: dict) -> None:
    drop_bots(state)
    if len(state["players"]) < MIN_SEATS:
        state["phase"] = "setup"
        state["rev"] += 1
        return
    fresh = [i for i in range(len(PAIRS)) if i not in state["used"]] or list(range(len(PAIRS)))
    state["pair"] = random.choice(fresh)
    state["used"] = (state["used"] + [state["pair"]])[-40:]
    state["flip"] = random.random() < 0.5
    state["spy"] = random.choice(state["players"])["id"]
    state["round"] += 1
    state.update(phase="clue", phase_at=now(), deadline=now() + CLUE_SECONDS, clues={}, votes={}, ready=[],
                 result=None)
    state["bot_due"] = {str(p["id"]): now() + random.uniform(5, 20) for p in state["players"] if p.get("bot")}
    state["rev"] += 1


def _open_votes(state: dict) -> None:
    state.update(phase="vote", phase_at=now(), deadline=now() + VOTE_SECONDS)
    state["bot_due"] = {str(p["id"]): now() + random.uniform(4, 14) for p in state["players"] if p.get("bot")}
    state["rev"] += 1


def _score(state: dict) -> None:
    spy = state["spy"]
    tally: dict[int, int] = {}
    for target in state["votes"].values():
        tally[target] = tally.get(target, 0) + 1
    top = max(tally.values()) if tally else 0
    leaders = [pid for pid, n in tally.items() if n == top]
    caught = top > 0 and leaders == [spy]
    gains = {str(p["id"]): 0 for p in state["players"]}
    for voter, target in state["votes"].items():
        if target == spy and int(voter) != spy:
            gains[voter] += VOTE_POINTS
    if not caught and str(spy) in gains:
        gains[str(spy)] += ESCAPE_POINTS
    for player in state["players"]:
        player["score"] += gains.get(str(player["id"]), 0)
    pair = PAIRS[state["pair"]]
    crowd, odd = (pair["b"], pair["a"]) if state["flip"] else (pair["a"], pair["b"])
    state["result"] = {"spy": spy, "caught": caught, "tally": {str(k): v for k, v in tally.items()},
                       "gains": gains, "crowd": {"pic": crowd[0], "label": crowd[1]},
                       "odd": {"pic": odd[0], "label": odd[1]},
                       "clues": dict(state["clues"]), "votes": dict(state["votes"])}
    state["history"].append({"spy": spy, "caught": caught})
    state.update(phase="reveal", phase_at=now(), deadline=now() + REVEAL_SECONDS, ready=[])
    state["rev"] += 1


def _after_reveal(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0)
        state["rev"] += 1
    else:
        _begin_round(state)


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needPlayers")
        _begin_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        for player in state["players"]:
            player["score"] = 0
        state.update(round=0, history=[], phase="setup", phase_at=now(), deadline=0.0, result=None,
                     clues={}, votes={}, ready=[])
        drop_bots(state)
        state["rev"] += 1
        return

    if action == "clue":
        if phase != "clue":
            raise Illegal("tooLate")
        text = " ".join(str(body.get("text") or "").split())[:MAX_CLUE]
        if not text:
            raise Illegal("emptyClue")
        if len(text.split()) > 2:
            raise Illegal("oneWord")
        state["clues"][str(me["id"])] = text
        state["rev"] += 1
        return

    if action == "vote":
        if phase != "vote":
            raise Illegal("tooLate")
        try:
            target = int(body.get("target"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        if target == me["id"]:
            raise Illegal("selfVote")
        if not any(p["id"] == target for p in state["players"]):
            raise Illegal("badTarget")
        state["votes"][str(me["id"])] = target
        state["rev"] += 1
        return

    if action == "ready":
        if phase == "reveal" and me["id"] not in state["ready"]:
            state["ready"].append(me["id"])
            state["rev"] += 1
        return

    raise Illegal("badAction")


# ============================== the bots ==============================

def _bot_clue(state: dict, bot_id: int) -> str:
    words = list(_pic(state, bot_id)[2])
    taken = set(state["clues"].values())
    random.shuffle(words)
    return next((w for w in words if w not in taken), words[0])


def _bot_vote(state: dict, bot_id: int) -> int | None:
    """البوت يعرف صورته فقط: يشكّ فيمن تلميحه لا يصف صورته، وأكثر فيمن يصف الصورة الأخرى."""
    mine = set(_pic(state, bot_id)[2])
    pair = PAIRS[state["pair"]]
    other = set(pair["a"][2]) | set(pair["b"][2])
    others = [p["id"] for p in state["players"] if p["id"] != bot_id]
    if not others:
        return None
    weights = []
    for pid in others:
        clue = state["clues"].get(str(pid), "")
        if not clue:
            weights.append(2.0)
        elif clue in mine:
            weights.append(0.4)
        elif clue in other:
            weights.append(4.0)
        else:
            weights.append(1.2)
    return random.choices(others, weights=weights)[0]


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    human_ids = [str(p["id"]) for p in state["players"] if not p.get("bot")]
    if phase in ("clue", "vote"):
        bucket = state["clues"] if phase == "clue" else state["votes"]
        humans_done = all(h in bucket for h in human_ids)
        for key, due in list(state["bot_due"].items()):
            if key not in bucket and (t >= due or humans_done or t >= state["deadline"]):
                if phase == "clue":
                    bucket[key] = _bot_clue(state, int(key))
                else:
                    vote = _bot_vote(state, int(key))
                    if vote is not None:
                        bucket[key] = vote
                state["bot_due"].pop(key, None)
                state["rev"] += 1
                return True
        if (humans_done and not state["bot_due"]) or t >= state["deadline"]:
            if phase == "clue":
                _open_votes(state)
            else:
                _score(state)
        return True
    if phase == "reveal":
        ready = human_ids and all(int(h) in state["ready"] for h in human_ids) and t - state["phase_at"] > 3
        if ready or t >= state["deadline"]:
            _after_reveal(state)
        return True
    return False


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    done = set()
    if phase == "clue":
        done = {int(k) for k in state["clues"]}
    elif phase == "vote":
        done = {int(k) for k in state["votes"]}
    elif phase == "reveal":
        done = set(state["ready"])
    view = base_view(state, seat)
    view["players"] = player_view(state, done)
    view["minSeats"] = MIN_SEATS
    if phase == "setup":
        view["roundChoices"] = list(ROUND_CHOICES)
    me = state["players"][seat]["id"] if seat is not None else None
    if phase in ("clue", "vote") and me is not None:
        view["pic"] = _pic(state, me)[0]
        view["myClue"] = state["clues"].get(str(me))
    if phase == "vote":
        view["clues"] = state["clues"]
        view["myVote"] = state["votes"].get(str(me)) if me is not None else None
    if phase == "reveal":
        view["result"] = state["result"]
    if phase == "final":
        caught = sum(1 for h in state["history"] if h["caught"])
        view["summary"] = {"caught": caught, "escaped": len(state["history"]) - caught}
    return view

