"""
محرّك شطرنج كامل القواعد.

تمثيل الرقعة `0x88`: مصفوفة من ١٢٨ خانة، نصفها وهميّ. وفائدتها أنّ فحص
الخروج من الرقعة يصير `sq & 0x88` — عمليةٌ واحدة بدل حسابِ صفٍّ وعمود عند كل
خطوة. وهذا ليس تحسينًا مبكّرًا بل وقايةٌ من أكثر أخطاء الشطرنج شيوعًا: حصانٌ
يقفز من طرف الرقعة فيظهر في الطرف الآخر.

القواعد كلّها هنا ولا استثناء: التبييت بشقّيه بشروطه الثلاثة، والأخذ في
المرور، والترقية، والكِش والمات والتعادل بالحصر، وقاعدة الخمسين نقلة،
والتكرار ثلاثًا، وعجز المادة عن المات.

الصحّة مُثبَتة بـ`perft`: عدّ أوراق شجرة النقلات إلى عمقٍ معيّن ومقارنته
بأرقامٍ منشورة متّفقٍ عليها. أيّ خطأ في أي قاعدة يظهر فورًا في العدد.
"""
from __future__ import annotations

WHITE, BLACK = "w", "b"

# اتجاهات الحركة في تمثيل 0x88
N, S, E, W = 16, -16, 1, -1
KNIGHT_DIRS = (33, 31, 18, 14, -33, -31, -18, -14)
BISHOP_DIRS = (17, 15, -17, -15)
ROOK_DIRS = (16, -16, 1, -1)
KING_DIRS = BISHOP_DIRS + ROOK_DIRS

SLIDERS = {"B": BISHOP_DIRS, "R": ROOK_DIRS, "Q": KING_DIRS}
FILES = "abcdefgh"

START_FEN = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"


def on_board(square: int) -> bool:
    return not (square & 0x88)


def to_algebraic(square: int) -> str:
    return FILES[square & 7] + str((square >> 4) + 1)


def from_algebraic(name: str) -> int:
    return (int(name[1]) - 1) * 16 + FILES.index(name[0])


def color_of(piece: str) -> str:
    return WHITE if piece.isupper() else BLACK


# ═══════════════════════════ الحالة ═══════════════════════════

def from_fen(fen: str = START_FEN) -> dict:
    board = [""] * 128
    rows, turn, castling, ep, half, full = fen.split()
    for rank_index, row in enumerate(rows.split("/")):
        square = (7 - rank_index) * 16
        for char in row:
            if char.isdigit():
                square += int(char)
            else:
                board[square] = char
                square += 1
    return {
        "board": board,
        "turn": turn,
        "castling": "" if castling == "-" else castling,
        "ep": -1 if ep == "-" else from_algebraic(ep),
        "half": int(half),
        "full": int(full),
        "history": [],          # بصمات الأوضاع، للتكرار ثلاثًا
        "moves": [],            # سجلّ النقلات بترميزها
        "last_move": None,
    }


def new_game() -> dict:
    state = from_fen()
    state["history"].append(_signature(state))
    return state


def fen(state: dict) -> str:
    rows = []
    for rank in range(7, -1, -1):
        row, gap = "", 0
        for file in range(8):
            piece = state["board"][rank * 16 + file]
            if piece:
                if gap:
                    row += str(gap)
                    gap = 0
                row += piece
            else:
                gap += 1
        if gap:
            row += str(gap)
        rows.append(row)
    ep = to_algebraic(state["ep"]) if state["ep"] >= 0 else "-"
    return (f"{'/'.join(rows)} {state['turn']} {state['castling'] or '-'} "
            f"{ep} {state['half']} {state['full']}")


def _signature(state: dict) -> str:
    """بصمة الوضع للتكرار: القطع والدور والتبييت والمرور، بلا العدّادات."""
    return " ".join(fen(state).split()[:4])


# ═══════════════════════════ الهجوم والكِش ═══════════════════════════

def king_square(state: dict, color: str) -> int:
    target = "K" if color == WHITE else "k"
    for square in range(128):
        if on_board(square) and state["board"][square] == target:
            return square
    return -1


def attacked(state: dict, square: int, by: str) -> bool:
    """هل الخانة مهدّدة من لونٍ ما؟ أساسُ كلّ فحصٍ للشرعية."""
    board = state["board"]
    # البيادق: تهدّد قطريًّا إلى الأمام، فنبحث عنها في الاتجاه المعاكس.
    step = -16 if by == WHITE else 16
    pawn = "P" if by == WHITE else "p"
    for side in (E, W):
        origin = square + step + side
        if on_board(origin) and board[origin] == pawn:
            return True

    knight = "N" if by == WHITE else "n"
    for direction in KNIGHT_DIRS:
        origin = square + direction
        if on_board(origin) and board[origin] == knight:
            return True

    king = "K" if by == WHITE else "k"
    for direction in KING_DIRS:
        origin = square + direction
        if on_board(origin) and board[origin] == king:
            return True

    for dirs, names in ((BISHOP_DIRS, "BQ"), (ROOK_DIRS, "RQ")):
        wanted = names if by == WHITE else names.lower()
        for direction in dirs:
            origin = square + direction
            while on_board(origin):
                piece = board[origin]
                if piece:
                    if piece in wanted:
                        return True
                    break
                origin += direction
    return False


def in_check(state: dict, color: str | None = None) -> bool:
    color = color or state["turn"]
    square = king_square(state, color)
    return square >= 0 and attacked(state, square, BLACK if color == WHITE else WHITE)


# ═══════════════════════════ توليد النقلات ═══════════════════════════

def _pseudo_moves(state: dict) -> list[dict]:
    board, turn = state["board"], state["turn"]
    moves: list[dict] = []

    def add(origin: int, target: int, **extra) -> None:
        moves.append({"from": origin, "to": target, **extra})

    for origin in range(128):
        if not on_board(origin):
            continue
        piece = board[origin]
        if not piece or color_of(piece) != turn:
            continue
        kind = piece.upper()

        if kind == "P":
            step = N if turn == WHITE else S
            start_rank = 1 if turn == WHITE else 6
            last_rank = 7 if turn == WHITE else 0
            ahead = origin + step
            if on_board(ahead) and not board[ahead]:
                if (ahead >> 4) == last_rank:
                    for promo in "QRBN":
                        add(origin, ahead, promo=promo)
                else:
                    add(origin, ahead)
                    double = ahead + step
                    if (origin >> 4) == start_rank and on_board(double) and not board[double]:
                        add(origin, double, double=True)
            for side in (E, W):
                target = origin + step + side
                if not on_board(target):
                    continue
                victim = board[target]
                if victim and color_of(victim) != turn:
                    if (target >> 4) == last_rank:
                        for promo in "QRBN":
                            add(origin, target, promo=promo)
                    else:
                        add(origin, target)
                elif target == state["ep"]:
                    add(origin, target, ep=True)
            continue

        if kind == "N" or kind == "K":
            for direction in (KNIGHT_DIRS if kind == "N" else KING_DIRS):
                target = origin + direction
                if on_board(target) and (not board[target] or color_of(board[target]) != turn):
                    add(origin, target)
            continue

        for direction in SLIDERS[kind]:
            target = origin + direction
            while on_board(target):
                victim = board[target]
                if not victim:
                    add(origin, target)
                elif color_of(victim) != turn:
                    add(origin, target)
                    break
                else:
                    break
                target += direction

    _add_castles(state, moves)
    return moves


def _add_castles(state: dict, moves: list[dict]) -> None:
    """
    التبييت بشروطه الثلاثة: الحقّ باقٍ، والطريق خالية، والملك لا يمرّ بكِش.
    وإهمال أيّ واحدٍ منها يولّد نقلاتٍ غير قانونية لا يكشفها إلّا العدّ.
    """
    board, turn = state["board"], state["turn"]
    rights = state["castling"]
    home = 0 if turn == WHITE else 112
    enemy = BLACK if turn == WHITE else WHITE
    king = "K" if turn == WHITE else "k"
    rook = "R" if turn == WHITE else "r"

    if board[home + 4] != king:
        return
    if attacked(state, home + 4, enemy):
        return

    short = "K" if turn == WHITE else "k"
    long_side = "Q" if turn == WHITE else "q"

    if short in rights and board[home + 7] == rook:
        if not board[home + 5] and not board[home + 6]:
            if not attacked(state, home + 5, enemy) and not attacked(state, home + 6, enemy):
                moves.append({"from": home + 4, "to": home + 6, "castle": "K"})
    if long_side in rights and board[home] == rook:
        if not board[home + 1] and not board[home + 2] and not board[home + 3]:
            if not attacked(state, home + 3, enemy) and not attacked(state, home + 2, enemy):
                moves.append({"from": home + 4, "to": home + 2, "castle": "Q"})


def legal_moves(state: dict) -> list[dict]:
    """النقلات المشروعة: كل شبه‑نقلةٍ لا تترك ملكَ صاحبها تحت الكِش."""
    mover = state["turn"]
    out = []
    for move in _pseudo_moves(state):
        undo = push(state, move, check_legal=False)
        if not in_check(state, mover):
            out.append(move)
        pop(state, undo)
    return out


# ═══════════════════════════ التنفيذ والتراجع ═══════════════════════════

def push(state: dict, move: dict, check_legal: bool = True) -> dict:
    board = state["board"]
    origin, target = move["from"], move["to"]
    piece = board[origin]
    undo = {
        "move": move, "piece": piece, "captured": board[target],
        "castling": state["castling"], "ep": state["ep"],
        "half": state["half"], "full": state["full"], "turn": state["turn"],
        "captured_square": target,
    }

    board[target] = piece
    board[origin] = ""

    if move.get("ep"):
        victim = target - 16 if state["turn"] == WHITE else target + 16
        undo["captured"] = board[victim]
        undo["captured_square"] = victim
        board[victim] = ""

    if move.get("promo"):
        board[target] = move["promo"] if state["turn"] == WHITE else move["promo"].lower()

    if move.get("castle"):
        home = origin & 0xF0
        if move["castle"] == "K":
            board[home + 5], board[home + 7] = board[home + 7], ""
        else:
            board[home + 3], board[home] = board[home], ""

    # حقوق التبييت تسقط بحركة الملك أو الطابية أو بأسرها في مكانها.
    rights = state["castling"]
    for square, flag in ((0, "Q"), (7, "K"), (112, "q"), (119, "k")):
        if origin == square or target == square:
            rights = rights.replace(flag, "")
    if piece in "Kk":
        rights = rights.replace("KQ" if piece == "K" else "kq", "")
        for flag in ("KQ" if piece == "K" else "kq"):
            rights = rights.replace(flag, "")
    state["castling"] = rights

    state["ep"] = (origin + target) // 2 if move.get("double") else -1
    state["half"] = 0 if (piece.upper() == "P" or undo["captured"]) else state["half"] + 1
    if state["turn"] == BLACK:
        state["full"] += 1
    state["turn"] = BLACK if state["turn"] == WHITE else WHITE

    if check_legal:
        state["history"].append(_signature(state))
        state["moves"].append(notation(undo["piece"], move, undo["captured"]))
        state["last_move"] = {"from": to_algebraic(origin), "to": to_algebraic(target)}
    return undo


def pop(state: dict, undo: dict) -> None:
    board = state["board"]
    move = undo["move"]
    origin, target = move["from"], move["to"]

    board[origin] = undo["piece"]
    board[target] = ""
    if undo["captured"]:
        board[undo["captured_square"]] = undo["captured"]

    if move.get("castle"):
        home = origin & 0xF0
        if move["castle"] == "K":
            board[home + 7], board[home + 5] = board[home + 5], ""
        else:
            board[home], board[home + 3] = board[home + 3], ""

    state["castling"] = undo["castling"]
    state["ep"] = undo["ep"]
    state["half"] = undo["half"]
    state["full"] = undo["full"]
    state["turn"] = undo["turn"]


def notation(piece: str, move: dict, captured: str) -> str:
    """ترميزٌ مبسّط يكفي لعرض السجلّ: e2e4 أو e7e8q."""
    text = to_algebraic(move["from"]) + to_algebraic(move["to"])
    return text + (move["promo"].lower() if move.get("promo") else "")


# ═══════════════════════════ نهاية المباراة ═══════════════════════════

def _material_draw(state: dict) -> bool:
    """عجز المادة: ملكان، أو ملك وفيل/حصان، أو ملكان بفيلين على لونٍ واحد."""
    pieces = [p for p in state["board"] if p and p.upper() != "K"]
    if not pieces:
        return True
    if len(pieces) == 1 and pieces[0].upper() in "BN":
        return True
    if len(pieces) == 2 and all(p.upper() == "B" for p in pieces):
        squares = [s for s in range(128) if on_board(s) and state["board"][s].upper() == "B"]
        return ((squares[0] >> 4) + (squares[0] & 7)) % 2 == ((squares[1] >> 4) + (squares[1] & 7)) % 2
    return False


def status(state: dict) -> dict:
    moves = legal_moves(state)
    checked = in_check(state)
    if not moves:
        if checked:
            winner = BLACK if state["turn"] == WHITE else WHITE
            return {"over": True, "result": "checkmate", "winner": winner}
        return {"over": True, "result": "stalemate", "winner": None}
    if state["half"] >= 100:
        return {"over": True, "result": "fifty", "winner": None}
    if state["history"].count(_signature(state)) >= 3:
        return {"over": True, "result": "repetition", "winner": None}
    if _material_draw(state):
        return {"over": True, "result": "material", "winner": None}
    return {"over": False, "result": "check" if checked else "playing", "winner": None}


# ═══════════════════════════ التحقّق ═══════════════════════════

def perft(state: dict, depth: int) -> int:
    """عدّ أوراق شجرة النقلات — مقياسُ صحّة القواعد لا مقياسُ قوّة."""
    if depth == 0:
        return 1
    total = 0
    for move in legal_moves(state):
        undo = push(state, move, check_legal=False)
        total += perft(state, depth - 1)
        pop(state, undo)
    return total

