"""
A chess match around the rules in `engine.py` and the search in `ai.py`.

What the table adds to the rules:
  * a setup screen: side (white, black, random), bot strength, and a clock;
  * two people play each other, one person plays the bot;
  * clocks that run on the server, and a flag that falls: bullet, blitz,
    rapid, classical with an increment, "daily" (a day for every move), or a
    custom base and increment;
  * hints (three a game), take-backs against the bot (asked of a friend),
    resigning, draw offers;
  * readable notation (Nf3, exd5, O-O, e8=Q#) and the pieces each side took.

English only: every word a player reads lives in the client.
"""
from __future__ import annotations

import random
import time

from . import ai
from . import engine as ch

MAX_SEATS = 2
LEVELS = ("easy", "normal", "hard")
# Seconds the search may think, per strength. The driver waits on it, so it is
# kept short: depth is what makes "hard" hard, not patience.
THINK = {"easy": 0.12, "normal": 0.45, "hard": 1.1}
CLOCKS = (0, 3, 5, 10, 15)
# Time controls as "minutes+increment"; "daily" gives a full day per move.
PRESETS = ("1+0", "2+1", "3+0", "3+2", "5+0", "5+3", "10+0", "10+5", "15+10", "30+0", "daily")
DAY = 86400.0
HINTS = 3
VALUE = {"P": 1, "N": 3, "B": 3, "R": 5, "Q": 9, "K": 0}
START = {"P": 8, "N": 2, "B": 2, "R": 2, "Q": 1, "K": 1}


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def _seat(person: dict | None, bot: bool = False) -> dict:
    person = person or {"id": -1, "name": "", "photo": ""}
    return {"id": person["id"], "name": person.get("name", ""), "photo": person.get("photo", ""),
            "bot": bot, "color": "w"}


def new_match(people: list[dict], host: int) -> dict:
    humans = [_seat(p) for p in people[:MAX_SEATS]]
    if len(humans) < 2:
        humans.append(_seat({"id": -2, "name": "", "photo": ""}, bot=True))
    return {
        "game": "chess", "host": host, "players": humans, "phase": "setup",
        "side": "white", "level": "normal", "clock": 0, "inc": 0, "daily": False,
        "board": None, "rev": 0, "wins": {},
        "result": "", "winner": None, "over_reason": "",
    }


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat["id"] == user_id and not seat["bot"]:
            return index
    return None


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    bot = next((p for p in state["players"] if p["bot"]), None)
    if bot is None or state["phase"] == "playing":
        raise Illegal("full")
    bot.update(id=person["id"], name=person["name"], photo=person.get("photo", ""), bot=False)
    state["rev"] += 1


def _host(state: dict, seat: int | None) -> None:
    if seat is None:
        raise Illegal("watchingOnly")
    if state["players"][seat]["id"] != state.get("host") and seat != 0:
        raise Illegal("notHost")


def _versus_bot(state: dict) -> bool:
    return any(p["bot"] for p in state["players"])


# ═══════════════════════════ starting ═══════════════════════════

def _begin(state: dict) -> None:
    side = state.get("side", "white")
    if side == "random":
        side = random.choice(("white", "black"))
    first = "w" if side == "white" else "b"
    state["players"][0]["color"] = first
    state["players"][1]["color"] = "b" if first == "w" else "w"
    board = ch.new_game()
    state["board"] = board
    minutes = float(state.get("clock", 0))
    if state.get("daily"):
        state["clocks"] = {"w": DAY, "b": DAY}
    else:
        state["clocks"] = {"w": minutes * 60.0, "b": minutes * 60.0} if minutes else None
    state["takeback_offer"] = None
    state["turn_at"] = now()
    state["san"] = []
    state["snaps"] = []
    state["hints"] = {"0": HINTS, "1": HINTS}
    state["hint"] = {}
    state["draw_offer"] = None
    state["result"], state["winner"], state["over_reason"] = "", None, ""
    state["phase"] = "playing"
    state["bot_at"] = now() + 0.9
    state["started"] = now()
    state["rev"] += 1


def _color_seat(state: dict, color: str) -> int:
    return 0 if state["players"][0]["color"] == color else 1


# ═══════════════════════════ notation ═══════════════════════════

def san(board: dict, move: dict, legal: list[dict]) -> str:
    piece = board["board"][move["from"]]
    kind = piece.upper()
    target = ch.to_algebraic(move["to"])
    capture = bool(board["board"][move["to"]]) or bool(move.get("ep"))
    if move.get("castle"):
        text = "O-O" if move["castle"] == "K" else "O-O-O"
    elif kind == "P":
        text = (ch.to_algebraic(move["from"])[0] + "x" if capture else "") + target
        if move.get("promo"):
            text += "=" + move["promo"].upper()
    else:
        rivals = [m for m in legal if m is not move and m["to"] == move["to"]
                  and board["board"][m["from"]] == piece and m["from"] != move["from"]]
        clue = ""
        if rivals:
            here = ch.to_algebraic(move["from"])
            if all(ch.to_algebraic(m["from"])[0] != here[0] for m in rivals):
                clue = here[0]
            elif all(ch.to_algebraic(m["from"])[1] != here[1] for m in rivals):
                clue = here[1]
            else:
                clue = here
        text = kind + clue + ("x" if capture else "") + target
    undo = ch.push(board, move, check_legal=False)
    try:
        if ch.in_check(board):
            text += "#" if not ch.legal_moves(board) else "+"
    finally:
        ch.pop(board, undo)
    return text


# ═══════════════════════════ moving ═══════════════════════════

def _tick(state: dict) -> None:
    clocks = state.get("clocks")
    if not clocks or state["phase"] != "playing":
        return
    turn = state["board"]["turn"]
    spent = now() - state["turn_at"]
    clocks[turn] = max(0.0, clocks[turn] - spent)
    state["turn_at"] = now()


def _snapshot(state: dict) -> dict:
    b = state["board"]
    return {"fen": ch.fen(b), "history": list(b["history"]), "moves": list(b["moves"]),
            "last": b.get("last_move"), "san": list(state["san"]),
            "clocks": dict(state["clocks"]) if state.get("clocks") else None}


def _restore(state: dict, snap: dict) -> None:
    board = ch.from_fen(snap["fen"])
    board["history"] = list(snap["history"])
    board["moves"] = list(snap["moves"])
    board["last_move"] = snap["last"]
    state["board"] = board
    state["san"] = list(snap["san"])
    if snap.get("clocks"):
        state["clocks"] = dict(snap["clocks"])
    state["turn_at"] = now()


def _play(state: dict, move: dict) -> None:
    board = state["board"]
    legal = ch.legal_moves(board)
    state["snaps"].append(_snapshot(state))
    del state["snaps"][:-40]
    text = san(board, move, legal)
    mover = board["turn"]
    _tick(state)
    ch.push(board, move)
    clocks = state.get("clocks")
    if clocks:
        if state.get("daily"):
            clocks[mover] = DAY
        else:
            clocks[mover] += float(state.get("inc", 0))
    state["san"].append(text)
    state["hint"] = {}
    state["draw_offer"] = None
    state["takeback_offer"] = None
    state["last_capture"] = "x" in text
    state["rev"] += 1
    info = ch.status(board)
    if info["over"]:
        _finish(state, info["result"], info["winner"])
    else:
        state["bot_at"] = now() + random.uniform(0.45, 0.95)


def _finish(state: dict, reason: str, winner: str | None) -> None:
    state["phase"] = "over"
    state["over_reason"] = reason
    state["winner"] = winner
    state["result"] = "win" if winner else "draw"
    if winner:
        who = state["players"][_color_seat(state, winner)]
        key = str(who["id"])
        state["wins"][key] = int(state["wins"].get(key, 0)) + 1
    state["rev"] += 1


def _find(board: dict, origin: str, target: str, promo: str) -> dict:
    for move in ch.legal_moves(board):
        if (ch.to_algebraic(move["from"]) == origin and ch.to_algebraic(move["to"]) == target
                and (not move.get("promo") or move["promo"] == promo)):
            return move
    raise Illegal("illegalMove")


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action in ("side", "level", "clock", "tc", "go"):
        _host(state, seat)
        if state["phase"] == "playing" and action != "level":
            raise Illegal("badPhase")
        if action == "side":
            value = str(body.get("side") or "")
            if value not in ("white", "black", "random"):
                raise Illegal("badSide")
            state["side"] = value
        elif action == "level":
            value = str(body.get("level") or "")
            if value not in LEVELS:
                raise Illegal("badLevel")
            state["level"] = value
        elif action == "clock":
            value = int(body.get("minutes") or 0)
            if value not in CLOCKS:
                raise Illegal("badClock")
            state["clock"] = value
            state["inc"], state["daily"] = 0, False
        elif action == "tc":
            _time_control(state, body)
        else:
            _begin(state)
        state["rev"] += 1
        return

    if seat is None:
        raise Illegal("watchingOnly")
    me = state["players"][seat]
    if action == "again":
        if state["phase"] != "over":
            raise Illegal("badPhase")
        if not _versus_bot(state):
            state["side"] = "black" if me["color"] == "w" else "white"
        state["phase"] = "setup"
        state["rev"] += 1
        return
    if state["phase"] != "playing":
        raise Illegal("badPhase")
    board = state["board"]

    if action == "move":
        if board["turn"] != me["color"]:
            raise Illegal("notYourTurn")
        promo = str(body.get("promo") or "Q").upper()[:1]
        if promo not in "QRBN":
            promo = "Q"
        _play(state, _find(board, str(body.get("from") or ""), str(body.get("to") or ""), promo))
    elif action == "hint":
        if board["turn"] != me["color"]:
            raise Illegal("notYourTurn")
        left = int(state["hints"].get(str(seat), 0))
        if left <= 0:
            raise Illegal("noHints")
        scratch = {**board, "board": list(board["board"]), "history": list(board["history"]),
                   "moves": list(board["moves"])}
        saved = ai.LEVELS.get("normal")
        ai.LEVELS["normal"] = 0.5
        try:
            move = ai.choose(scratch, "normal")
        finally:
            ai.LEVELS["normal"] = saved
        if move is None:
            raise Illegal("noHints")
        state["hints"][str(seat)] = left - 1
        state["hint"] = {str(seat): {"from": ch.to_algebraic(move["from"]),
                                     "to": ch.to_algebraic(move["to"])}}
        state["rev"] += 1
    elif action == "undo":
        if not _versus_bot(state):
            raise Illegal("friendsNoUndo")
        _take_back(state, me["color"])
        state["bot_at"] = now() + 1.5
    elif action == "takeback":
        # Between friends a take-back is asked, and the other one decides.
        if _versus_bot(state):
            raise Illegal("badAction")
        if not state["snaps"]:
            raise Illegal("nothingToUndo")
        state["takeback_offer"] = seat
        state["rev"] += 1
    elif action in ("takebackyes", "takebackno"):
        asker = state.get("takeback_offer")
        if asker is None or asker == seat:
            raise Illegal("noOffer")
        state["takeback_offer"] = None
        if action == "takebackyes":
            _take_back(state, state["players"][asker]["color"])
        state["rev"] += 1
    elif action == "resign":
        _tick(state)
        _finish(state, "resign", "b" if me["color"] == "w" else "w")
    elif action == "draw":
        if _versus_bot(state):
            score = ai.evaluate(board) * (1 if board["turn"] == "w" else -1)
            mine = score if me["color"] == "w" else -score
            if len(state["san"]) >= 30 and mine > -60:
                _finish(state, "agreed", None)
            else:
                raise Illegal("drawDeclined")
        else:
            offer = state.get("draw_offer")
            if offer is not None and offer != seat:
                _finish(state, "agreed", None)
            else:
                state["draw_offer"] = seat
                state["rev"] += 1
    elif action == "nodraw":
        state["draw_offer"] = None
        state["rev"] += 1
    else:
        raise Illegal("badAction")


def _take_back(state: dict, color: str) -> None:
    """Back to the last time it was `color` to move."""
    target = None
    while state["snaps"]:
        snap = state["snaps"].pop()
        if ch.from_fen(snap["fen"])["turn"] == color:
            target = snap
            break
    if target is None:
        raise Illegal("nothingToUndo")
    _restore(state, target)
    state["hint"] = {}
    state["takeback_offer"] = None
    state["rev"] += 1


def _time_control(state: dict, body: dict) -> None:
    """A preset ("3+2", "daily") or a custom base in minutes and increment in seconds."""
    preset = str(body.get("preset") or "")
    if preset == "daily":
        state["clock"], state["inc"], state["daily"] = 0, 0, True
        return
    if preset:
        if preset not in PRESETS:
            raise Illegal("badClock")
        base, inc = preset.split("+")
        minutes, extra = float(base), int(inc)
    else:
        try:
            minutes = float(body.get("minutes") or 0)
            extra = int(body.get("inc") or 0)
        except (TypeError, ValueError):
            raise Illegal("badClock") from None
    if not (0 <= minutes <= 180 and 0 <= extra <= 60) or (minutes == 0 and extra):
        raise Illegal("badClock")
    state["clock"] = int(minutes) if minutes == int(minutes) else minutes
    state["inc"], state["daily"] = extra, False


# ═══════════════════════════ the pulse ═══════════════════════════

def step(state: dict) -> bool:
    if state["phase"] != "playing":
        return False
    board = state["board"]
    clocks = state.get("clocks")
    if clocks:
        turn = board["turn"]
        if clocks[turn] - (now() - state["turn_at"]) <= 0:
            _tick(state)
            clocks[turn] = 0.0
            other = "b" if turn == "w" else "w"
            _finish(state, "time", other)
            return True
    seat = _color_seat(state, board["turn"])
    # True keeps the room's driver awake: a bot still to move, or a clock
    # that may run out, both need it to come back.
    if not state["players"][seat]["bot"]:
        return bool(clocks)
    if now() < state.get("bot_at", 0):
        return True
    scratch = {**board, "board": list(board["board"]), "history": list(board["history"]),
               "moves": list(board["moves"])}
    level = state.get("level", "normal")
    saved = ai.LEVELS.get(level)
    ai.LEVELS[level] = THINK.get(level, 0.45)
    try:
        move = ai.choose(scratch, level)
    finally:
        ai.LEVELS[level] = saved
    if move is None:
        return False
    # The move came from a copy; find its twin among the real board's moves.
    real = _find(board, ch.to_algebraic(move["from"]), ch.to_algebraic(move["to"]),
                 (move.get("promo") or "Q"))
    _play(state, real)
    return True


# ═══════════════════════════ the view ═══════════════════════════

def captured(board: dict) -> dict:
    left = {"w": dict.fromkeys(START, 0), "b": dict.fromkeys(START, 0)}
    for piece in board["board"]:
        if piece:
            left["w" if piece.isupper() else "b"][piece.upper()] += 1
    # What each colour has taken is what the other is missing.
    taken = {"w": [], "b": []}
    for color, other in (("w", "b"), ("b", "w")):
        for kind in "QRBNP":
            taken[color] += [kind if other == "w" else kind.lower()] * max(0, START[kind] - left[other][kind])
    score = sum(VALUE[p.upper()] for p in taken["w"]) - sum(VALUE[p.upper()] for p in taken["b"])
    return {"w": taken["w"], "b": taken["b"], "lead": score}


def view_for(state: dict, seat: int | None) -> dict:
    players = [{"name": p["name"], "photo": p["photo"], "bot": p["bot"], "color": p["color"],
                "id": p["id"] if not p["bot"] else 0, "seat": i,
                "wins": int(state["wins"].get(str(p["id"]), 0))}
               for i, p in enumerate(state["players"])]
    host_seat = next((i for i, p in enumerate(state["players"]) if p["id"] == state.get("host")), 0)
    out = {
        "game": "chess", "rev": state["rev"], "phase": state["phase"], "seat": seat,
        "players": players, "host": seat is not None and seat == host_seat,
        "side": state.get("side"), "level": state.get("level"), "clock": state.get("clock"),
        "levels": list(LEVELS), "clocks": list(CLOCKS), "versusBot": _versus_bot(state),
        "inc": int(state.get("inc", 0)), "daily": bool(state.get("daily")), "presets": list(PRESETS),
        "serverNow": int(now() * 1000),
    }
    board = state.get("board")
    if not board:
        return out
    me = state["players"][seat] if seat is not None else None
    color = me["color"] if me else None
    squares = []
    for rank in range(7, -1, -1):
        for file in range(8):
            index = rank * 16 + file
            squares.append({"sq": ch.to_algebraic(index), "p": board["board"][index]})
    moves: dict[str, list[str]] = {}
    mine = state["phase"] == "playing" and color == board["turn"]
    if mine:
        for move in ch.legal_moves(board):
            moves.setdefault(ch.to_algebraic(move["from"]), []).append(ch.to_algebraic(move["to"]))
    checked = ch.in_check(board)
    clocks = state.get("clocks")
    live = None
    if clocks:
        live = dict(clocks)
        if state["phase"] == "playing":
            live[board["turn"]] = max(0.0, live[board["turn"]] - (now() - state["turn_at"]))
        live = {k: int(v * 1000) for k, v in live.items()}
    out.update({
        "squares": squares, "turn": board["turn"], "myColor": color, "moves": moves,
        "check": checked,
        "checkSquare": ch.to_algebraic(ch.king_square(board, board["turn"])) if checked else "",
        "lastMove": board.get("last_move"), "san": list(state.get("san", [])),
        "lastCapture": bool(state.get("last_capture")),
        "captured": captured(board),
        "clockMs": live, "running": state["phase"] == "playing",
        "hint": (state.get("hint") or {}).get(str(seat)) if seat is not None else None,
        "hintsLeft": int((state.get("hints") or {}).get(str(seat), 0)) if seat is not None else 0,
        "canUndo": bool(_versus_bot(state) and state.get("snaps") and me and state["phase"] == "playing"),
        "drawOffer": state.get("draw_offer"),
        "takebackOffer": state.get("takeback_offer"),
        "result": state.get("result"), "winner": state.get("winner"),
        "reason": state.get("over_reason"),
    })
    return out

