"""
المحقّق — قضيّة صغيرة وستّة مشتبهين، لكلٍّ منهم مكانٌ وشيءٌ معه ولبس.

كل لاعب يستلم سرًّا دليلًا أو دليلين من نوع «الفاعل ما كان في المطبخ». لا أحد يكفيه
دليله وحده: تنشرون أدلّتكم على لوحة التحقيق، وتشطبون من تنفيه الأدلّة، ثم تتّهمون.
وإن كنتم أربعة فأكثر فبينكم «شريك» يعرف الفاعل، وأدلّته كاذبة تنفي الفاعل نفسه —
فإذا تناقضت اللوحة فابحثوا عمّن نشر ما لا يستقيم.

النقاط: اتّهامٌ صحيح ٣٠٠، وكل دليلٍ صادق تنشره ٥٠. والشريك إن نجا الفاعل ٥٠٠.
"""
from __future__ import annotations

import json
import pathlib
import random

from games import party
from games.party import Illegal, base_view, drop_bots, fill_bots, host_seat, now, player_view, seat_of, seats

HERE = pathlib.Path(__file__).resolve().parent
DATA = json.loads((HERE / "content" / "cases.json").read_text(encoding="utf-8"))
TRAITS = list(DATA["traits"])

MIN_SEATS = 3
MAX_SEATS = 8
SUSPECTS = 6
ACCOMPLICE_FROM = 4
ROUND_CHOICES = (3, 5)
DEFAULT_ROUNDS = 3
INVESTIGATE_SECONDS = 150
ACCUSE_SECONDS = 35
REVEAL_SECONDS = 25
RIGHT_POINTS = 300
CLUE_POINTS = 50
ESCAPE_POINTS = 500
QUIET = ("setup", "reveal", "final")

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "MAX_SEATS"]

_PHRASE = {"place": "الفاعل ما كان في {v}", "item": "الفاعل ما كان معه {v}", "wear": "الفاعل ما كان لابس {v}"}


def clue_text(trait: str, value: str) -> str:
    return _PHRASE[trait].format(v=value)


def new_match(people: list[dict], host: int) -> dict:
    state = {"game": "muhaqiq", "host": host, "players": seats(people, MAX_SEATS), "rounds": DEFAULT_ROUNDS,
             "round": 0, "phase": "setup", "phase_at": now(), "deadline": 0.0, "case": None, "clues": [],
             "accomplice": None, "votes": {}, "ready": [], "result": None, "bot_due": {}, "used": [],
             "history": [], "rev": 0}
    fill_bots(state, MIN_SEATS)
    return state


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)


def set_bots(state: dict, on: bool) -> None:
    party.set_bots(state, on, MIN_SEATS, QUIET)


def _build_case(state: dict) -> None:
    fresh = [i for i in range(len(DATA["crimes"])) if i not in state["used"]] or list(range(len(DATA["crimes"])))
    crime = random.choice(fresh)
    state["used"] = (state["used"] + [crime])[-6:]
    people = random.sample(DATA["suspects"], SUSPECTS)
    while True:
        suspects = [{"id": i, "icon": icon, "name": name,
                     **{t: random.choice(DATA["traits"][t]["values"]) for t in TRAITS}}
                    for i, (icon, name) in enumerate(people)]
        culprit = random.randrange(SUSPECTS)
        twin = any(all(s[t] == suspects[culprit][t] for t in TRAITS) for s in suspects if s["id"] != culprit)
        if not twin:
            break
    guilty = suspects[culprit]
    # Every true clue rules out a value the culprit does not have, but some suspect has.
    pool = [(t, v) for t in TRAITS for v in {s[t] for s in suspects} if v != guilty[t]]
    random.shuffle(pool)
    chosen, alive = [], {s["id"] for s in suspects} - {culprit}
    for t, v in pool:
        hit = {s["id"] for s in suspects if s[t] == v and s["id"] in alive}
        if hit:
            chosen.append((t, v))
            alive -= hit
        if not alive:
            break
    extra = [c for c in pool if c not in chosen]
    players = [p["id"] for p in state["players"]]
    accomplice = random.choice(players) if len(players) >= ACCOMPLICE_FROM else None
    honest = [pid for pid in players if pid != accomplice]
    random.shuffle(honest)
    while len(chosen) < len(honest) + 1 and extra:
        chosen.append(extra.pop())
    clues = []
    for n, (t, v) in enumerate(chosen):
        clues.append({"id": len(clues), "trait": t, "value": v, "owner": honest[n % len(honest)], "true": True,
                      "shared": False})
    if accomplice is not None:
        for t in random.sample(TRAITS, 2):
            clues.append({"id": len(clues), "trait": t, "value": guilty[t], "owner": accomplice, "true": False,
                          "shared": False})
    c = DATA["crimes"][crime]
    state["case"] = {"icon": c["icon"], "title": c["title"], "story": c["story"], "suspects": suspects,
                     "culprit": culprit}
    state["clues"] = clues
    state["accomplice"] = accomplice


def _begin_round(state: dict) -> None:
    drop_bots(state)
    if len(state["players"]) < MIN_SEATS:
        state["phase"] = "setup"
        state["rev"] += 1
        return
    _build_case(state)
    state["round"] += 1
    state.update(phase="investigate", phase_at=now(), deadline=now() + INVESTIGATE_SECONDS, votes={}, ready=[],
                 result=None)
    state["bot_due"] = {str(c["id"]): now() + random.uniform(8, 70)
                        for c in state["clues"] if c["owner"] < 0}
    state["rev"] += 1


def _open_accuse(state: dict) -> None:
    state.update(phase="accuse", phase_at=now(), deadline=now() + ACCUSE_SECONDS, ready=[])
    state["bot_due"] = {str(p["id"]): now() + random.uniform(4, 16) for p in state["players"] if p.get("bot")}
    state["rev"] += 1


def _score(state: dict) -> None:
    case = state["case"]
    culprit = case["culprit"]
    tally: dict[int, int] = {}
    for target in state["votes"].values():
        tally[target] = tally.get(target, 0) + 1
    top = max(tally.values()) if tally else 0
    caught = top > 0 and [s for s, n in tally.items() if n == top] == [culprit]
    gains = {str(p["id"]): 0 for p in state["players"]}
    for voter, target in state["votes"].items():
        if target == culprit and int(voter) != state["accomplice"]:
            gains[voter] = gains.get(voter, 0) + RIGHT_POINTS
    for clue in state["clues"]:
        if clue["shared"] and clue["true"] and str(clue["owner"]) in gains:
            gains[str(clue["owner"])] += CLUE_POINTS
    if state["accomplice"] is not None and not caught and str(state["accomplice"]) in gains:
        gains[str(state["accomplice"])] += ESCAPE_POINTS
    for player in state["players"]:
        player["score"] += gains.get(str(player["id"]), 0)
    state["result"] = {"culprit": culprit, "caught": caught, "accomplice": state["accomplice"],
                       "tally": {str(k): v for k, v in tally.items()}, "votes": dict(state["votes"]),
                       "gains": gains,
                       "clues": [{"text": clue_text(c["trait"], c["value"]), "owner": c["owner"], "true": c["true"],
                                  "shared": c["shared"]} for c in state["clues"]]}
    state["history"].append({"caught": caught})
    state.update(phase="reveal", phase_at=now(), deadline=now() + REVEAL_SECONDS, ready=[])
    state["rev"] += 1


def _after_reveal(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0)
        state["rev"] += 1
    else:
        _begin_round(state)


def _share(state: dict, clue: dict) -> None:
    if not clue["shared"]:
        clue["shared"] = True
        clue["at"] = now()
        state["rev"] += 1


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needPlayers")
        _begin_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        for player in state["players"]:
            player["score"] = 0
        state.update(round=0, history=[], phase="setup", phase_at=now(), deadline=0.0, result=None, case=None,
                     clues=[], votes={}, ready=[])
        drop_bots(state)
        state["rev"] += 1
        return

    if action == "share":
        if phase != "investigate":
            raise Illegal("tooLate")
        try:
            cid = int(body.get("clue"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        clue = next((c for c in state["clues"] if c["id"] == cid and c["owner"] == me["id"]), None)
        if clue is None:
            raise Illegal("notYours")
        _share(state, clue)
        return

    if action == "ready":
        if phase in ("investigate", "reveal") and me["id"] not in state["ready"]:
            state["ready"].append(me["id"])
            state["rev"] += 1
        return

    if action == "accuse":
        if phase != "accuse":
            raise Illegal("tooLate")
        try:
            target = int(body.get("suspect"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        if not 0 <= target < len(state["case"]["suspects"]):
            raise Illegal("badTarget")
        state["votes"][str(me["id"])] = target
        state["rev"] += 1
        return

    raise Illegal("badAction")


# ============================== the bots ==============================

def _survivors(suspects: list[dict], clues: list[dict]) -> list[int]:
    return [s["id"] for s in suspects if not any(s[c["trait"]] == c["value"] for c in clues)]


def _bot_guess(state: dict, bot_id: int) -> int:
    case = state["case"]
    if bot_id == state["accomplice"]:
        wrong = [s["id"] for s in case["suspects"] if s["id"] != case["culprit"]]
        board = [c for c in state["clues"] if c["shared"]]
        live = [s for s in _survivors(case["suspects"], board) if s != case["culprit"]]
        return random.choice(live or wrong)
    known = [c for c in state["clues"] if c["shared"] or c["owner"] == bot_id]
    left = _survivors(case["suspects"], known)
    if not left:
        # Contradiction: drop the clues of whichever author makes the board make sense again.
        best = None
        for author in {c["owner"] for c in known if c["owner"] != bot_id}:
            trial = _survivors(case["suspects"], [c for c in known if c["owner"] != author])
            if trial and (best is None or len(trial) < len(best)):
                best = trial
        left = best or [s["id"] for s in case["suspects"]]
    return random.choice(left)


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    human_ids = [p["id"] for p in state["players"] if not p.get("bot")]
    if phase == "investigate":
        for key, due in list(state["bot_due"].items()):
            if t >= due:
                clue = next((c for c in state["clues"] if str(c["id"]) == key), None)
                if clue is not None:
                    _share(state, clue)
                state["bot_due"].pop(key, None)
                return True
        if (human_ids and all(h in state["ready"] for h in human_ids)) or t >= state["deadline"]:
            for clue in state["clues"]:
                if clue["owner"] < 0:
                    _share(state, clue)
            _open_accuse(state)
        return True
    if phase == "accuse":
        humans_done = all(str(h) in state["votes"] for h in human_ids)
        for key, due in list(state["bot_due"].items()):
            if key not in state["votes"] and (t >= due or humans_done or t >= state["deadline"]):
                state["votes"][key] = _bot_guess(state, int(key))
                state["bot_due"].pop(key, None)
                state["rev"] += 1
                return True
        if (humans_done and not state["bot_due"]) or t >= state["deadline"]:
            _score(state)
        return True
    if phase == "reveal":
        ready = human_ids and all(h in state["ready"] for h in human_ids) and t - state["phase_at"] > 3
        if ready or t >= state["deadline"]:
            _after_reveal(state)
        return True
    return False


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    if phase == "accuse":
        done = {int(k) for k in state["votes"]}
    elif phase in ("investigate", "reveal"):
        done = set(state["ready"])
    else:
        done = set()
    view = base_view(state, seat)
    view["players"] = player_view(state, done)
    view["minSeats"] = MIN_SEATS
    view["traits"] = {t: DATA["traits"][t]["label"] for t in TRAITS}
    if phase == "setup":
        view["roundChoices"] = list(ROUND_CHOICES)
    case = state["case"]
    me = state["players"][seat]["id"] if seat is not None else None
    if case and phase in ("investigate", "accuse", "reveal"):
        view["case"] = {k: case[k] for k in ("icon", "title", "story", "suspects")}
        board = sorted((c for c in state["clues"] if c["shared"]), key=lambda c: c.get("at", 0))
        view["board"] = [{"id": c["id"], "text": clue_text(c["trait"], c["value"]), "trait": c["trait"],
                          "value": c["value"], "by": c["owner"]} for c in board]
        if me is not None:
            view["mine"] = [{"id": c["id"], "text": clue_text(c["trait"], c["value"]), "shared": c["shared"]}
                            for c in state["clues"] if c["owner"] == me]
            if me == state["accomplice"]:
                view["accomplice"] = True
                view["culprit"] = case["culprit"]
        view["hasAccomplice"] = state["accomplice"] is not None
    if phase == "accuse" and me is not None:
        view["myVote"] = state["votes"].get(str(me))
    if phase == "reveal":
        view["result"] = state["result"]
    if phase == "final":
        caught = sum(1 for h in state["history"] if h["caught"])
        view["summary"] = {"caught": caught, "escaped": len(state["history"]) - caught}
    return view

