"""
المزاد — كلٌّ يبدأ بألف عملة، وتُعرض قطعٌ بتقديرٍ تقريبي؛ وقيمتها الحقيقية لا تُعرف إلا بعد البيع.

بعض القطع مزيّفة لا تساوي شيئًا، وبعضها كنزٌ بضعف التقدير. ومع كل قطعة يهمس الخبير
لواحدٍ فقط بحقيقتها — فإن رأيته يزايد بقوّة: هل يعرف شيئًا أم يورّطك؟
المزايدة حيّة: كلّ مزايدةٍ تمدّ الوقت، ومن بقي أعلاها حين ينتهي الوقت اشتراها.
الفائز صاحب أكبر ثروة في الختام: ما بقي من عملاته + قيمة ما اشتراه.
"""
from __future__ import annotations

import json
import pathlib
import random

from games import party
from games.party import Illegal, base_view, drop_bots, host_seat, now, player_view, seat_of, seats

HERE = pathlib.Path(__file__).resolve().parent
ITEMS = json.loads((HERE / "content" / "items.json").read_text(encoding="utf-8"))["items"]

MIN_SEATS = 2
BOT_FILL = 4
MAX_SEATS = 8
START_COINS = 1000
ROUND_CHOICES = (6, 8, 10)
DEFAULT_ROUNDS = 8
OPEN_SECONDS = 16
EXTEND_SECONDS = 7
SOLD_SECONDS = 7
QUIET = ("setup", "sold", "final")
KINDS = (("real", 0.6), ("fake", 0.2), ("treasure", 0.2))

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "MAX_SEATS"]


def increment(amount: int) -> int:
    return 10 if amount < 200 else 20 if amount < 500 else 50


def _r10(value: float) -> int:
    return max(10, int(round(value / 10.0)) * 10)


def new_match(people: list[dict], host: int) -> dict:
    state = {"game": "mazad", "host": host, "players": seats(people, MAX_SEATS), "rounds": DEFAULT_ROUNDS,
             "round": 0, "phase": "setup", "phase_at": now(), "deadline": 0.0, "lot": None, "top": None,
             "bids": [], "coins": {}, "won": {}, "result": None, "bot_at": 0.0, "bot_value": {}, "used": [],
             "rev": 0}
    party.fill_bots(state, BOT_FILL)
    return state


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)
    state["coins"].setdefault(str(person["id"]), START_COINS)


def set_bots(state: dict, on: bool) -> None:
    party.set_bots(state, on, BOT_FILL, QUIET)
    for p in state["players"]:
        state["coins"].setdefault(str(p["id"]), START_COINS)


def _coins(state: dict, pid) -> int:
    return int(state["coins"].setdefault(str(pid), START_COINS))


def _worth(state: dict, pid) -> int:
    return _coins(state, pid) + sum(w["value"] for w in state["won"].get(str(pid), []))


def _next_lot(state: dict) -> None:
    drop_bots(state)
    for p in state["players"]:
        state["coins"].setdefault(str(p["id"]), START_COINS)
    fresh = [i for i in range(len(ITEMS)) if i not in state["used"]] or list(range(len(ITEMS)))
    index = random.choice(fresh)
    state["used"].append(index)
    icon, name, base = ITEMS[index]
    kind = random.choices([k for k, _ in KINDS], weights=[w for _, w in KINDS])[0]
    factor = {"real": random.uniform(0.85, 1.2), "fake": random.uniform(0.04, 0.2),
              "treasure": random.uniform(1.8, 2.6)}[kind]
    tipped = random.choice(state["players"])["id"] if state["players"] else None
    state["lot"] = {"icon": icon, "name": name, "low": _r10(base * 0.7), "high": _r10(base * 1.4),
                    "value": _r10(base * factor), "kind": kind, "tipped": tipped}
    state["round"] += 1
    state.update(phase="bid", phase_at=now(), deadline=now() + OPEN_SECONDS, top=None, bids=[], result=None,
                 bot_at=now() + random.uniform(3, 6))
    state["bot_value"] = {}
    for p in state["players"]:
        if p.get("bot"):
            if p["id"] == tipped:
                guess = {"real": 1.1, "fake": 0.15, "treasure": 2.0}[kind]
            else:
                guess = random.uniform(0.8, 1.3)
            state["bot_value"][str(p["id"])] = _r10(base * guess)
    for p in state["players"]:
        p["score"] = _worth(state, p["id"])
    state["rev"] += 1


def _sell(state: dict) -> None:
    lot = state["lot"]
    top = state["top"]
    if top:
        pid = str(top["id"])
        state["coins"][pid] = _coins(state, pid) - top["amount"]
        state["won"].setdefault(pid, []).append({"icon": lot["icon"], "name": lot["name"], "price": top["amount"],
                                                 "value": lot["value"], "kind": lot["kind"]})
    state["result"] = {"buyer": top["id"] if top else None, "price": top["amount"] if top else 0,
                       "value": lot["value"], "kind": lot["kind"], "tipped": lot["tipped"],
                       "profit": (lot["value"] - top["amount"]) if top else 0}
    for p in state["players"]:
        p["score"] = _worth(state, p["id"])
    state.update(phase="sold", phase_at=now(), deadline=now() + SOLD_SECONDS)
    state["rev"] += 1


def _after_sold(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0)
        state["rev"] += 1
    else:
        _next_lot(state)


def _bid(state: dict, pid: int, amount: int) -> None:
    top = state["top"]
    least = (top["amount"] + increment(top["amount"])) if top else increment(0)
    if top and top["id"] == pid:
        raise Illegal("topBidder")
    if amount < least:
        raise Illegal("bidTooLow")
    if amount > _coins(state, pid):
        raise Illegal("tooPoor")
    state["top"] = {"id": pid, "amount": amount}
    state["bids"] = (state["bids"] + [{"id": pid, "amount": amount, "at": now()}])[-8:]
    state["deadline"] = max(state["deadline"], now() + EXTEND_SECONDS)
    state["bot_at"] = now() + random.uniform(1.2, 3.2)
    state["rev"] += 1


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        for p in state["players"]:
            state["coins"].setdefault(str(p["id"]), START_COINS)
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needPlayers")
        _next_lot(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        state.update(round=0, used=[], coins={}, won={}, phase="setup", phase_at=now(), deadline=0.0,
                     lot=None, top=None, bids=[], result=None)
        drop_bots(state)
        for p in state["players"]:
            p["score"] = START_COINS
        state["rev"] += 1
        return

    if action == "bid":
        if phase != "bid":
            raise Illegal("tooLate")
        try:
            amount = int(body.get("amount"))
        except (TypeError, ValueError):
            raise Illegal("badBid") from None
        _bid(state, me["id"], amount)
        return

    if action == "ready":
        return

    raise Illegal("badAction")


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    if phase == "bid":
        if t >= state["deadline"]:
            _sell(state)
            return True
        if t >= state["bot_at"]:
            top = state["top"]
            nxt = (top["amount"] + increment(top["amount"])) if top else increment(0)
            keen = []
            for p in state["players"]:
                if not p.get("bot") or (top and top["id"] == p["id"]):
                    continue
                cap = min(state["bot_value"].get(str(p["id"]), 0), _coins(state, p["id"]))
                if state["lot"]["kind"] != "treasure" or p["id"] != state["lot"]["tipped"]:
                    cap = min(cap, int(_coins(state, p["id"]) * 0.7))
                if nxt <= cap:
                    keen.append((p, cap))
            if keen and random.random() < 0.8:
                p, cap = random.choice(keen)
                jump = increment(nxt) * random.choice([0, 0, 1, 2])
                _bid(state, p["id"], min(cap, nxt + jump))
            else:
                state["bot_at"] = t + random.uniform(1.5, 3.5)
        return True
    if phase == "sold":
        if t >= state["deadline"]:
            _after_sold(state)
        return True
    return False


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    view = base_view(state, seat)
    view["players"] = player_view(state)
    for row in view["players"]:
        row["coins"] = _coins(state, row["id"])
        row["items"] = len(state["won"].get(str(row["id"]), []))
    view["minSeats"] = MIN_SEATS
    view["startCoins"] = START_COINS
    if phase == "setup":
        view["roundChoices"] = list(ROUND_CHOICES)
    me = state["players"][seat]["id"] if seat is not None else None
    lot = state["lot"]
    if lot and phase in ("bid", "sold"):
        view["lot"] = {"icon": lot["icon"], "name": lot["name"], "low": lot["low"], "high": lot["high"]}
        if me is not None and me == lot["tipped"]:
            view["tip"] = lot["kind"]
        view["top"] = state["top"]
        view["bids"] = [{"id": b["id"], "amount": b["amount"]} for b in state["bids"]]
        view["step"] = increment(state["top"]["amount"]) if state["top"] else increment(0)
    if phase == "sold":
        view["result"] = state["result"]
    if phase == "final":
        view["won"] = state["won"]
    return view

