"""
Barra Al-Salfa - one of you is "outside the story".

Everyone gets the same secret word except one player, the outsider, who only
knows the topic. Players question each other in a chain (the one who answers
asks next), everyone watching for the answer that does not fit. Then the
table votes. Whoever is accused or not, the outsider gets a last chance: pick
the secret word out of eight words from the topic.

Round scoring:
  caught (the outsider alone has the most votes): everyone else +200
  escaped: the outsider +500
  each vote that pointed at the outsider: +100 to the voter
  the outsider picks the right word: +300

What stays on the server: the word (never sent to the outsider), who the
outsider is (only told to the outsider, and to all at the result), and the
guess options (only sent to the outsider).

Modes and options (chosen by the host):
  classic: the outsider knows they are outside and only sees the topic.
  undercover: the outsider gets a close decoy word from the same topic and is
    not told; they learn it only when the guess comes.
  clues: before the questions, everyone writes one short clue at the same
    time; the clues are shown together, then the questions are shorter.
  suspicion: during the round anyone may mark up to two players they suspect;
    the counts are public, who marked whom is not.

Bots (the host turns them on or off from the room): they fill the table to
four seats and play every phase. Their knowledge lives in content/brain.json:
a few hints per word, questions and vague answers per topic.
  - A bot that knows the word answers with an unused hint of it, and measures
    everyone's clues and answers against the hints of the word and of the
    other words in the topic: a player whose words fit another word better,
    or nothing at all, becomes its suspect (plus a little of what the table
    suspects, and some noise per round so bots do not all agree).
  - The outsider bot reads the table the other way: it scores every word of
    the topic by how well the others' words fit it, answers vaguely until one
    word stands out, then bluffs with that word's hints, writes its clue last,
    deflects the vote to the table's favourite suspect, and guesses the best
    scoring option.
"""
from __future__ import annotations

import json
import pathlib
import random
import time

HERE = pathlib.Path(__file__).resolve().parent
_CONTENT = json.loads((HERE / "content" / "topics.json").read_text(encoding="utf-8"))
BRAIN = json.loads((HERE / "content" / "brain.json").read_text(encoding="utf-8"))
TOPICS = {t["key"]: t for t in _CONTENT["topics"]}
MIX = "mix"

MIN_SEATS = 3
MAX_SEATS = 10
ROUND_CHOICES = (3, 5, 7)
DEFAULT_ROUNDS = 5
REVEAL_SECONDS = 30
TURN_SECONDS = 45
ANSWER_SECONDS = 45
VOTE_SECONDS = 40
GUESS_SECONDS = 25
RESULT_SECONDS = 16
GUESS_OPTIONS = 8
MAX_TEXT = 90

CAUGHT_POINTS = 200
ESCAPE_POINTS = 500
GOOD_VOTE_POINTS = 100
GUESS_POINTS = 300
MODES = ("classic", "undercover")
CLUE_SECONDS = 40
CLUE_TEXT = 24
MAX_SUSPECTS = 2
BOT_TABLE = 4
GUESS_NOISE = 1.3
INSIDER_VAGUE = 0.25
BOTS_ON_START = True  # tables.py: a room with bots on fills the table at the start


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def _clean(text: object) -> str:
    return " ".join(str(text or "").split())[:MAX_TEXT]


# ============================== match ==============================

def new_match(people: list[dict], host: int) -> dict:
    seats = [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": False,
              "score": 0, "caught_votes": 0, "outsider_points": 0}
             for p in people[:MAX_SEATS]]
    return {
        "game": "salfa", "host": host, "players": seats,
        "topic": MIX, "rounds": DEFAULT_ROUNDS, "round": 0,
        "phase": "setup", "phase_at": now(), "deadline": 0.0,
        "word": "", "topic_now": "", "outsider": None, "last_outsider": None,
        "seen": [], "asker": None, "target": None, "question": "", "log": [],
        "asked": 0, "vote_calls": [], "votes": {}, "options": [], "guess": None,
        "result": None, "ready": [], "used": [], "rev": 0,
        "mode": "classic", "clues_on": False, "decoy": "", "clues": {}, "suspects": {},
        "no_bots": True, "bot_due": {}, "bot_noise": {},
    }


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat.get("id") == user_id:
            return index
    return None


def host_seat(state: dict) -> int | None:
    host = seat_of(state, state.get("host", 0))
    return host if host is not None else (0 if state["players"] else None)


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    if state["phase"] not in ("setup", "result", "final"):
        raise Illegal("waitForRound")
    if len(state["players"]) >= MAX_SEATS:
        raise Illegal("full")
    state["players"].append({"id": person["id"], "name": person["name"], "photo": person.get("photo", ""),
                             "bot": False, "score": 0, "caught_votes": 0, "outsider_points": 0})
    state["rev"] += 1


def _set_phase(state: dict, phase: str, seconds: float) -> None:
    state["phase"] = phase
    state["phase_at"] = now()
    state["deadline"] = now() + seconds if seconds else 0.0
    state["rev"] += 1


def _begin_round(state: dict) -> None:
    if state.get("no_bots") and any(p.get("bot") for p in state["players"]):
        _drop_bots(state)
        if len(state["players"]) < MIN_SEATS:
            state["round"] = 0
            _set_phase(state, "setup", 0)
            return
    if not state.get("no_bots", True):
        _fill_bots(state)
    players = state["players"]
    state["round"] += 1
    key = state["topic"] if state["topic"] != MIX else random.choice(list(TOPICS))
    topic = TOPICS[key]
    fresh = [w for w in topic["words"] if f"{key}:{w}" not in state["used"]] or topic["words"]
    word = random.choice(fresh)
    state["used"].append(f"{key}:{word}")
    candidates = [i for i in range(len(players)) if i != state["last_outsider"]] or list(range(len(players)))
    outsider = random.choice(candidates)
    others = [w for w in topic["words"] if w != word]
    options = random.sample(others, min(GUESS_OPTIONS - 1, len(others))) + [word]
    random.shuffle(options)
    decoy = random.choice(others) if state.get("mode") == "undercover" and others else ""
    state.update(word=word, topic_now=key, outsider=outsider, last_outsider=outsider, seen=[],
                 asker=random.randrange(len(players)), target=None, question="", log=[], asked=0,
                 vote_calls=[], votes={}, options=options, guess=None, result=None, ready=[],
                 decoy=decoy, clues={}, suspects={}, bot_due={},
                 bot_noise={str(i): {str(j): random.random() * 0.6 for j in range(len(players))}
                            for i, p in enumerate(players) if p.get("bot")})
    _set_phase(state, "reveal", REVEAL_SECONDS)


def _question_limit(state: dict) -> int:
    if state.get("clues_on"):
        return max(3, len(state["players"]))
    return max(4, len(state["players"]) * 2)


def _after_reveal(state: dict) -> None:
    if state.get("clues_on"):
        _set_phase(state, "clues", CLUE_SECONDS)
    else:
        _set_phase(state, "questions", TURN_SECONDS)


def _fold(text: str) -> str:
    out = "".join(ch for ch in text if ch.isalnum())
    for a, b in (("\u0623", "\u0627"), ("\u0625", "\u0627"), ("\u0622", "\u0627"), ("\u0629", "\u0647"), ("\u0649", "\u064a")):
        out = out.replace(a, b)
    return out.lower()


def _open_vote(state: dict) -> None:
    state["asker"] = None
    state["target"] = None
    _set_phase(state, "vote", VOTE_SECONDS)


def _tally(state: dict) -> None:
    counts: dict[int, int] = {}
    for target in state["votes"].values():
        counts[target] = counts.get(target, 0) + 1
    best = max(counts.values()) if counts else 0
    top = [seat for seat, count in counts.items() if count == best]
    accused = top[0] if len(top) == 1 and best > 0 else None
    state["result"] = {"accused": accused, "caught": accused == state["outsider"],
                       "counts": {str(k): v for k, v in counts.items()}}
    _set_phase(state, "guess", GUESS_SECONDS)


def _score(state: dict) -> None:
    outsider = state["outsider"]
    result = state["result"]
    gains = {str(i): 0 for i in range(len(state["players"]))}
    if result["caught"]:
        for i in range(len(state["players"])):
            if i != outsider:
                gains[str(i)] += CAUGHT_POINTS
    else:
        gains[str(outsider)] += ESCAPE_POINTS
    for voter, target in state["votes"].items():
        if target == outsider and int(voter) != outsider:
            gains[voter] += GOOD_VOTE_POINTS
            state["players"][int(voter)]["caught_votes"] += 1
    right = state["guess"] == state["word"]
    if right:
        gains[str(outsider)] += GUESS_POINTS
    for seat, gain in gains.items():
        state["players"][int(seat)]["score"] += gain
    state["players"][outsider]["outsider_points"] += gains[str(outsider)]
    result.update(gains=gains, guessRight=right, guess=state["guess"], decoy=state.get("decoy", ""))
    _set_phase(state, "result", RESULT_SECONDS)


# ============================== actions ==============================

def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if seat is None:
        raise Illegal("notSeated")
    phase = state["phase"]
    is_host = seat == host_seat(state)

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        topic = str(body.get("topic") or state["topic"])
        if topic != MIX and topic not in TOPICS:
            raise Illegal("badPack")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["topic"] = topic
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        if str(body.get("mode") or "") in MODES:
            state["mode"] = str(body["mode"])
        if "clues" in body:
            state["clues_on"] = bool(body.get("clues"))
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needThree")
        _begin_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        for p in state["players"]:
            p.update(score=0, caught_votes=0, outsider_points=0)
        state.update(round=0, result=None, log=[], used=[])
        _set_phase(state, "setup", 0)
        return

    if action == "seen":
        if phase == "reveal" and seat not in state["seen"]:
            state["seen"].append(seat)
            state["rev"] += 1
        return

    if action == "clue":
        if phase != "clues":
            raise Illegal("tooLate")
        text = _clean(body.get("text"))[:CLUE_TEXT]
        if not text:
            raise Illegal("emptyClue")
        # Saying the word itself would end the game for everyone.
        secret = state["decoy"] if seat == state["outsider"] and state["decoy"] else state["word"]
        if seat != state["outsider"] or state["decoy"]:
            if _fold(secret) and _fold(secret) in _fold(text):
                raise Illegal("noSecret")
        state["clues"][str(seat)] = text
        state["rev"] += 1
        if len(state["clues"]) >= len(state["players"]):
            _set_phase(state, "questions", TURN_SECONDS)
        return

    if action == "suspect":
        if phase not in ("clues", "questions", "vote"):
            raise Illegal("tooLate")
        try:
            target = int(body.get("target"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        if target == seat or not 0 <= target < len(state["players"]):
            raise Illegal("badTarget")
        mine = state["suspects"].setdefault(str(seat), [])
        if target in mine:
            mine.remove(target)
        else:
            mine.append(target)
            del mine[:-MAX_SUSPECTS]
        state["rev"] += 1
        return

    if action == "ask":
        if phase != "questions":
            raise Illegal("tooLate")
        if seat != state["asker"] or state["target"] is not None:
            raise Illegal("notYourTurn")
        try:
            target = int(body.get("target"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        if target == seat or not 0 <= target < len(state["players"]):
            raise Illegal("badTarget")
        _ask(state, seat, target, _clean(body.get("text")))
        return

    if action == "answer":
        if phase != "questions":
            raise Illegal("tooLate")
        if seat != state["target"]:
            raise Illegal("notYourTurn")
        _answer(state, _clean(body.get("text")))
        return

    if action == "callvote":
        if phase != "questions":
            raise Illegal("tooLate")
        if seat not in state["vote_calls"]:
            state["vote_calls"].append(seat)
            state["rev"] += 1
        if len(state["vote_calls"]) * 2 > len(state["players"]):
            _open_vote(state)
        return

    if action == "vote":
        if phase != "vote":
            raise Illegal("tooLate")
        try:
            target = int(body.get("target"))
        except (TypeError, ValueError):
            raise Illegal("badTarget") from None
        if target == seat or not 0 <= target < len(state["players"]):
            raise Illegal("badTarget")
        state["votes"][str(seat)] = target
        state["rev"] += 1
        if len(state["votes"]) >= len(state["players"]):
            _tally(state)
        return

    if action == "guess":
        if phase != "guess":
            raise Illegal("tooLate")
        if seat != state["outsider"]:
            raise Illegal("notOutsider")
        choice = str(body.get("word") or "")
        if choice not in state["options"]:
            raise Illegal("badOption")
        state["guess"] = choice
        _score(state)
        return

    if action == "ready":
        if phase == "result" and seat not in state["ready"]:
            state["ready"].append(seat)
            state["rev"] += 1
        return

    raise Illegal("badAction")


def _ask(state: dict, asker: int, target: int, text: str) -> None:
    state["target"] = target
    state["question"] = text
    state["log"].append({"asker": asker, "target": target, "q": text, "a": None})
    del state["log"][:-8]
    state["deadline"] = now() + ANSWER_SECONDS
    state["rev"] += 1


def _answer(state: dict, text: str) -> None:
    if state["log"]:
        state["log"][-1]["a"] = text
    answerer = state["target"]
    state["asked"] += 1
    state["target"] = None
    state["question"] = ""
    if state["asked"] >= _question_limit(state):
        _open_vote(state)
        return
    state["asker"] = answerer
    state["deadline"] = now() + TURN_SECONDS
    state["rev"] += 1


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    _bots_tick(state)
    phase = state["phase"]
    if phase in ("setup", "final"):
        return True
    t = now()
    players = len(state["players"])
    if phase == "reveal":
        if len(state["seen"]) >= players or t >= state["deadline"]:
            _after_reveal(state)
        return True
    if phase == "clues":
        if t >= state["deadline"]:
            _set_phase(state, "questions", TURN_SECONDS)
        return True
    if phase == "questions":
        if t >= state["deadline"]:
            if state["target"] is None:
                # The asker went quiet: the question passes to someone else.
                last = state["log"][-1]["asker"] if state["log"] else None
                choices = [i for i in range(players) if i != state["asker"] and i != last] or \
                          [i for i in range(players) if i != state["asker"]]
                _ask(state, state["asker"], random.choice(choices), "")
            else:
                _answer(state, "")
        return True
    if phase == "vote":
        if t >= state["deadline"]:
            _tally(state)
        return True
    if phase == "guess":
        if t >= state["deadline"]:
            _score(state)
        return True
    if phase == "result":
        everyone = all(i in state["ready"] for i in range(players))
        if (everyone and t - state["phase_at"] > 3) or t >= state["deadline"]:
            if state["round"] >= state["rounds"]:
                _set_phase(state, "final", 0)
            else:
                _begin_round(state)
        return True
    return False


# ============================== view ==============================

def view_for(state: dict, seat: int | None) -> dict:
    t = now()
    phase = state["phase"]
    over = phase in ("result", "final")
    outsider = state["outsider"]
    me_out = seat is not None and seat == outsider and phase not in ("setup",)
    view = {
        "game": "salfa", "phase": phase, "seat": seat,
        "isHost": seat is not None and seat == host_seat(state),
        "hostName": state["players"][host_seat(state)]["name"] if host_seat(state) is not None else "",
        "players": [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "score": p["score"],
                     "caught": p["caught_votes"], "sly": p["outsider_points"],
                     "seen": i in state["seen"], "voted": str(i) in state["votes"],
                     "ready": i in state["ready"], "calling": i in state["vote_calls"], "bot": bool(p.get("bot"))}
                    for i, p in enumerate(state["players"])],
        "topic": state["topic"], "rounds": state["rounds"], "round": state["round"],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state["deadline"] else 0,
        "elapsed": int((t - state["phase_at"]) * 1000),
        "minPlayers": MIN_SEATS, "rev": state["rev"],
        "mode": state.get("mode", "classic"), "cluesOn": bool(state.get("clues_on")),
        "bots": not state.get("no_bots", True),
    }
    if phase == "setup":
        view["topics"] = [{"key": MIX, "label": "", "art": "mix"}] + [
            {"key": k, "label": v["label"], "art": v.get("art", k)} for k, v in TOPICS.items()]
        view["roundChoices"] = list(ROUND_CHOICES)
        view["modes"] = list(MODES)
        return view
    if phase == "final":
        return view
    topic = TOPICS.get(state["topic_now"], {})
    view["topicNow"] = {"key": state["topic_now"], "label": topic.get("label", ""), "art": topic.get("art", "mix")}
    undercover = bool(state.get("decoy"))
    # Undercover: the outsider is not told until the guess.
    view["isOutsider"] = me_out and (not undercover or phase in ("guess", "result"))
    # The rule that IS the game: the word never reaches the outsider.
    if me_out and not over:
        view["word"] = state["decoy"] if undercover and phase != "guess" else ""
    else:
        view["word"] = state["word"]
    counts: dict[str, int] = {}
    for targets in state.get("suspects", {}).values():
        for target in targets:
            counts[str(target)] = counts.get(str(target), 0) + 1
    view["suspected"] = counts
    view["mySuspects"] = state.get("suspects", {}).get(str(seat), []) if seat is not None else []
    if phase == "clues":
        view["cluesIn"] = [int(k) for k in state["clues"]]
        view["myClue"] = state["clues"].get(str(seat), "") if seat is not None else ""
    elif state.get("clues"):
        view["clues"] = state["clues"]
    view["asker"] = state["asker"]
    view["target"] = state["target"]
    view["question"] = state["question"]
    view["log"] = state["log"]
    view["asked"] = state["asked"]
    view["questionLimit"] = _question_limit(state)
    if phase == "vote":
        view["myVote"] = state["votes"].get(str(seat)) if seat is not None else None
    if phase == "guess":
        view["accusedCaught"] = state["result"]["caught"]
        view["accused"] = state["result"]["accused"]
        view["outsider"] = outsider
        if me_out:
            view["options"] = state["options"]
    if phase == "result":
        view["outsider"] = outsider
        view["result"] = state["result"]
        view["votes"] = state["votes"]
    return view


# ============================== bots ==============================

def _bot_names() -> list[str]:
    return list(BRAIN.get("names") or ["Bot"])


def set_bots(state: dict, on: bool) -> None:
    """On: bots fill the table to four seats (between rounds). Off: they leave now
    between rounds, or when the current round ends (a round cannot lose its outsider)."""
    state["no_bots"] = not on
    if on:
        if state["phase"] in ("setup", "final"):
            _fill_bots(state)
        state["rev"] += 1
        return
    if state["phase"] in ("setup", "final"):
        _drop_bots(state)
    state["rev"] += 1


def _fill_bots(state: dict) -> None:
    taken = {p["name"] for p in state["players"]}
    names = [n for n in _bot_names() if n not in taken]
    random.shuffle(names)
    while len(state["players"]) < BOT_TABLE:
        index = len(state["players"])
        state["players"].append({"id": -(500 + index), "name": names.pop() if names else f"Bot {index}",
                                 "photo": "", "bot": True, "score": 0, "caught_votes": 0, "outsider_points": 0})


def _drop_bots(state: dict) -> None:
    state["players"] = [p for p in state["players"] if not p.get("bot")]
    state.update(outsider=None, last_outsider=None, seen=[], ready=[], votes={}, vote_calls=[],
                 clues={}, suspects={}, bot_due={}, bot_noise={}, asker=None, target=None)
    state["rev"] += 1


def _tokens(text: str) -> set[str]:
    return {w for w in (_fold(part) for part in str(text or "").split()) if len(w) >= 2}


_HINT_TOKENS: dict[str, set[str]] = {}


def _hint_tokens(word: str) -> set[str]:
    if word not in _HINT_TOKENS:
        bag: set[str] = set()
        for hint in BRAIN["hints"].get(word, []):
            bag |= _tokens(hint)
        _HINT_TOKENS[word] = bag
    return _HINT_TOKENS[word]


def _fit(text: str, word: str) -> float:
    """How well a free answer points at a word: shared hint words, or a word close to one."""
    said = _tokens(text)
    if not said:
        return 0.0
    hints = _hint_tokens(word)
    score = 0.0
    for token in said:
        if token in hints:
            score += 1.0
        elif len(token) >= 3 and any(len(h) >= 3 and (token in h or h in token) for h in hints):
            score += 0.6
    folded = _fold(word)
    if folded and any(folded in t or (len(t) >= 3 and t in folded) for t in said):
        score += 1.5
    return score


def _texts_by(state: dict) -> dict[int, list[str]]:
    out: dict[int, list[str]] = {i: [] for i in range(len(state["players"]))}
    for seat, clue in state.get("clues", {}).items():
        out.setdefault(int(seat), []).append(clue)
    for row in state["log"]:
        if row.get("a") is not None:
            out.setdefault(row["target"], []).append(row["a"])
    return out


def _belief(state: dict, seat: int) -> str:
    """The word this bot thinks everyone has ("" for an outsider who knows it is outside)."""
    if seat != state["outsider"]:
        return state["word"]
    return state.get("decoy", "")


def _knows_outside(state: dict, seat: int) -> bool:
    return seat == state["outsider"] and (not state.get("decoy") or state["phase"] in ("guess", "result"))


def _suspicion(state: dict, seat: int) -> dict[int, float]:
    word = _belief(state, seat)
    topic = TOPICS.get(state["topic_now"], {"words": []})
    texts = _texts_by(state)
    noise = state.get("bot_noise", {}).get(str(seat), {})
    marks: dict[int, int] = {}
    for targets in state.get("suspects", {}).values():
        for target in targets:
            marks[target] = marks.get(target, 0) + 1
    out: dict[int, float] = {}
    for other in range(len(state["players"])):
        if other == seat:
            continue
        said = texts.get(other, [])
        score = noise.get(str(other), 0.3)
        if said:
            mine = sum(_fit(t, word) for t in said) if word else 0.0
            best_other = max((sum(_fit(t, w) for t in said) for w in topic["words"] if w != word), default=0.0)
            score += max(0.0, best_other - mine) * 0.7 - mine * 0.6
            if mine == 0:
                score += 0.9
            score += 0.7 * sum(1 for t in said if not t.strip())
        score += 0.3 * marks.get(other, 0)
        out[other] = score
    return out


def _guess_scores(state: dict, seat: int) -> dict[str, float]:
    """The outsider bot's map of the topic: which word do the others' words fit best?"""
    topic = TOPICS.get(state["topic_now"], {"words": []})
    texts = [t for other, said in _texts_by(state).items() if other != seat for t in said]
    decoy = state.get("decoy", "")
    # A steady misreading per word and round: bots read the table well, not perfectly.
    noise = state.setdefault("bot_noise", {}).setdefault(f"w{seat}", {})
    for w in topic["words"]:
        if w not in noise:
            noise[w] = random.gauss(0, GUESS_NOISE)
    return {w: sum(_fit(t, w) for t in texts) + noise[w] for w in topic["words"] if w != decoy}


def _used_texts(state: dict) -> set[str]:
    used = set(state.get("clues", {}).values())
    used |= {row["a"] for row in state["log"] if row.get("a")}
    return used


def _vague(state: dict) -> str:
    return random.choice(BRAIN["vague"].get(state["topic_now"]) or ["..."])


def _bot_line(state: dict, seat: int) -> str:
    """A clue or an answer: a fresh hint of the word it believes in, or a bluff."""
    used = _used_texts(state)
    word = _belief(state, seat)
    undercover = seat == state["outsider"] and state.get("decoy")
    if undercover:
        # Undercover and unaware, until the others clearly describe another word.
        scores = _guess_scores(state, seat)
        best = max(scores, key=scores.get) if scores else ""
        own = sum(_fit(t, word) for other, said in _texts_by(state).items() if other != seat for t in said)
        if best and scores[best] >= own + 2.0:
            word = best
    elif seat == state["outsider"]:
        scores = _guess_scores(state, seat)
        ranked = sorted(scores.values(), reverse=True)
        best = max(scores, key=scores.get) if scores else ""
        if best and ranked[0] >= 1.5 and ranked[0] - (ranked[1] if len(ranked) > 1 else 0) >= 0.8:
            word = best
        else:
            return _vague(state)
    # Insiders stay a little vague too, so the outsider cannot just read the word off them.
    if seat != state["outsider"] and random.random() < INSIDER_VAGUE:
        return _vague(state)
    hints = [h for h in BRAIN["hints"].get(word, []) if h not in used]
    return random.choice(hints) if hints else _vague(state)


def _due(state: dict, seat: int, token: str, low: float, high: float) -> bool:
    """True once this bot's thinking time for `token` has passed (the first call starts the clock)."""
    slot = state["bot_due"].get(str(seat))
    t = now()
    if not slot or slot[0] != token:
        state["bot_due"][str(seat)] = [token, t + random.uniform(low, high)]
        return False
    return t >= slot[1]


def _try(state: dict, seat: int, action: str, body: dict) -> bool:
    try:
        act(state, seat, action, body)
        return True
    except Illegal:
        return False


def _top(scores: dict) -> int | None:
    return max(scores, key=scores.get) if scores else None


def _bots_tick(state: dict) -> None:
    for seat in range(len(state["players"])):
        if seat >= len(state["players"]) or not state["players"][seat].get("bot"):
            continue
        phase = state["phase"]
        if phase in ("setup", "final"):
            return
        _bot_turn(state, seat, phase)


def _bot_turn(state: dict, seat: int, phase: str) -> None:
    rnd = state["round"]
    if phase == "reveal":
        if seat not in state["seen"] and _due(state, seat, f"seen{rnd}", 1.5, 4):
            _try(state, seat, "seen", {})
        return

    if phase == "clues":
        if str(seat) in state["clues"]:
            return
        outside = _knows_outside(state, seat)
        others_in = len(state["clues"]) >= len(state["players"]) - 1
        late = state["deadline"] - now() < 6
        # The outsider writes last, after reading everyone else's clue.
        if outside and not (others_in or late):
            return
        if _due(state, seat, f"clue{rnd}", 4, 10) or (outside and (others_in or late)):
            for _ in range(4):
                if _try(state, seat, "clue", {"text": _bot_line(state, seat)[:CLUE_TEXT]}):
                    return
            _try(state, seat, "clue", {"text": _vague(state)[:CLUE_TEXT]})
        return

    if phase == "questions":
        if state["target"] is None and state["asker"] == seat:
            if _due(state, seat, f"ask{rnd}:{state['asked']}", 3, 7):
                _bot_ask(state, seat)
            return
        if state["target"] == seat:
            if _due(state, seat, f"ans{rnd}:{state['asked']}", 3, 7):
                _try(state, seat, "answer", {"text": _bot_line(state, seat)})
            return
        _bot_think(state, seat)
        return

    if phase == "vote":
        if str(seat) not in state["votes"] and _due(state, seat, f"vote{rnd}", 3, 9):
            target = _vote_target(state, seat)
            if target is not None:
                _try(state, seat, "vote", {"target": target})
        return

    if phase == "guess":
        if seat == state["outsider"] and _due(state, seat, f"guess{rnd}", 3, 7):
            scores = _guess_scores(state, seat)
            options = [o for o in state["options"] if o != state.get("decoy")] or state["options"]
            _try(state, seat, "guess", {"word": max(options, key=lambda w: scores.get(w, 0.0))})
        return

    if phase == "result":
        if seat not in state["ready"] and _due(state, seat, f"ready{rnd}", 3, 6):
            _try(state, seat, "ready", {})


def _bot_ask(state: dict, seat: int) -> None:
    players = len(state["players"])
    last = state["log"][-1]["asker"] if state["log"] else None
    choices = [i for i in range(players) if i not in (seat, last)] or [i for i in range(players) if i != seat]
    if _knows_outside(state, seat):
        target = random.choice(choices)
    else:
        scores = _suspicion(state, seat)
        ranked = sorted(choices, key=lambda i: scores.get(i, 0), reverse=True)
        # Usually press the main suspect, sometimes test someone else.
        target = ranked[0] if random.random() < 0.65 else random.choice(choices)
    asked = {row["q"] for row in state["log"]}
    every = BRAIN["questions"].get(state["topic_now"]) or ["?"]
    pool = [q for q in every if q not in asked] or every
    _try(state, seat, "ask", {"target": target, "text": random.choice(pool)})


def _bot_think(state: dict, seat: int) -> None:
    """Between turns: mark a suspect, and call the vote once the picture is clear."""
    answered = sum(1 for row in state["log"] if row.get("a") is not None)
    if answered < 2 or not _due(state, seat, f"think{state['round']}:{answered}", 2, 6):
        return
    limit = _question_limit(state)
    if _knows_outside(state, seat):
        # Blend in: echo the table's favourite suspect.
        marks: dict[int, float] = {}
        for targets in state["suspects"].values():
            for target in targets:
                if target != seat:
                    marks[target] = marks.get(target, 0) + 1 + random.random() * 0.5
        target = _top(marks)
        confident = answered >= limit * 0.7
    else:
        scores = _suspicion(state, seat)
        target = _top(scores)
        ranked = sorted(scores.values(), reverse=True)
        clear = bool(ranked) and ranked[0] >= 1.6 and (len(ranked) < 2 or ranked[0] - ranked[1] >= 0.6)
        confident = clear or answered >= limit * 0.75
    if target is not None and target not in state["suspects"].get(str(seat), []):
        _try(state, seat, "suspect", {"target": target})
    if confident and answered >= 3 and seat not in state["vote_calls"]:
        _try(state, seat, "callvote", {})


def _vote_target(state: dict, seat: int) -> int | None:
    if _knows_outside(state, seat):
        # Vote with the crowd, away from itself.
        counts: dict[int, float] = {}
        for target in state["votes"].values():
            if target != seat:
                counts[target] = counts.get(target, 0) + 1
        for targets in state["suspects"].values():
            for target in targets:
                if target != seat:
                    counts[target] = counts.get(target, 0) + 0.5
        if counts:
            return _top(counts)
        return random.choice([i for i in range(len(state["players"])) if i != seat])
    return _top(_suspicion(state, seat))

