"""
Escape Tower: the shared state of one trip in a room.

Pure functions over `room["tower"]` (no I/O, no clock of their own: every call
is handed `stamp`, the server time in seconds). The crew pulse carries the
client's operations in and a delta back out, so a shared trip needs no timer
and no socket of its own.

Modes:
  together  one tower for everyone: the puzzle keys are shared, a floor is
            solved once, and the lift leaves when everyone is aboard (or
            BOARD_WAIT seconds after the first one stepped on).
  race      the same rooms for everyone, each solving alone; progress is shared.
  each      every player on a challenge of their own; progress is shared.
"""
from __future__ import annotations

import re

MODES = ("together", "race", "each")
TIERS = {"first": 3, "short": 5, "adventure": 8, "expert": 13, "summit": 21, "daily": 7, "race": 6}
ROOM_ID = re.compile(r"^[A-Z][0-9]{1,2}$")
KEY = re.compile(r"^f([0-9]{1,2})\.([A-Za-z0-9_]{1,24})$")
MAX_KEYS = 96
MAX_VALUE = 48
WRITES_PER_SEC = 30.0
BOARD_WAIT = 15.0
MAX_OPS = 24
MAX_LIST = 24


class TowerError(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def fresh() -> dict:
    return {
        "rev": 0, "reset": 0, "phase": "lobby", "mode": "together", "tier": "", "seed": 0,
        "list": [], "floor": 0, "keys": {}, "krev": {}, "solved": [], "skipped": [],
        "votes": [], "aboard": [], "aboard_at": 0.0, "progress": {}, "started": 0.0,
        "ended": 0.0, "bucket": WRITES_PER_SEC, "bucket_at": 0.0, "result": None,
    }


def state(room: dict) -> dict:
    tw = room.get("tower")
    if not isinstance(tw, dict):
        tw = fresh()
        room["tower"] = tw
    return tw


def _bump(tw: dict) -> int:
    tw["rev"] += 1
    return tw["rev"]


def _clean_value(value):
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        if value != value or abs(value) > 1e9:
            return None
        return round(float(value), 4) if isinstance(value, float) else int(value)
    if isinstance(value, str) and len(value) <= MAX_VALUE:
        return value
    return None


def _spend(tw: dict, stamp: float) -> bool:
    """One write from the room's bucket (WRITES_PER_SEC a second)."""
    elapsed = max(0.0, stamp - float(tw.get("bucket_at") or 0.0))
    tw["bucket"] = min(WRITES_PER_SEC, float(tw.get("bucket", WRITES_PER_SEC)) + elapsed * WRITES_PER_SEC)
    tw["bucket_at"] = stamp
    if tw["bucket"] < 1:
        return False
    tw["bucket"] -= 1
    return True


def start(tw: dict, mode: str, tier: str, seed, rooms, stamp: float) -> None:
    if mode not in MODES:
        raise TowerError("badMode")
    if tier not in TIERS:
        raise TowerError("badTier")
    if not isinstance(seed, int) or isinstance(seed, bool) or not 0 <= seed < 2 ** 31:
        raise TowerError("badSeed")
    if not isinstance(rooms, list) or not 1 <= len(rooms) <= MAX_LIST:
        raise TowerError("badList")
    if any(not isinstance(r, str) or not ROOM_ID.match(r) for r in rooms) or len(set(rooms)) != len(rooms):
        raise TowerError("badList")
    if mode != "each" and len(rooms) != TIERS[tier]:
        raise TowerError("badList")
    if tw["phase"] == "play" and tw["seed"] == seed and tw["list"] == rooms and tw["mode"] == mode:
        return  # the same start sent twice (an answer lost on the way): already running
    tw.update(phase="play", mode=mode, tier=tier, seed=seed, list=list(rooms), floor=0,
              keys={}, krev={}, solved=[], skipped=[], votes=[], aboard=[], aboard_at=0.0,
              progress={}, started=stamp, ended=0.0, result=None)
    tw["reset"] = _bump(tw)


def _key_floor(key: str) -> int:
    m = KEY.match(key)
    if not m:
        raise TowerError("badKey")
    return int(m.group(1))


def put(tw: dict, key: str, value, stamp: float, expect=None, compare: bool = False) -> bool:
    """A shared puzzle key on the current floor (together mode). Returns whether it was written."""
    if tw["phase"] != "play" or tw["mode"] != "together":
        raise TowerError("notShared")
    if not isinstance(key, str):
        raise TowerError("badKey")
    if _key_floor(key) != tw["floor"]:
        raise TowerError("oldFloor")
    clean = _clean_value(value)
    if clean is None:
        raise TowerError("badValue")
    keys = tw["keys"]
    if key not in keys and len(keys) >= MAX_KEYS:
        raise TowerError("tooMany")
    if compare and keys.get(key) != _clean_value(expect) and not (expect is None and key not in keys):
        return False
    if not _spend(tw, stamp):
        raise TowerError("tooFast")
    keys[key] = clean
    tw["krev"][key] = _bump(tw)
    return True


def _advance(tw: dict, stamp: float) -> None:
    """The lift leaves: on to the next floor (its keys start empty), or the end."""
    floor = tw["floor"]
    prefix = f"f{floor}."
    for key in [k for k in tw["keys"] if k.startswith(prefix)]:
        tw["keys"].pop(key, None)
        tw["krev"].pop(key, None)
    tw["aboard"] = []
    tw["aboard_at"] = 0.0
    tw["votes"] = []
    tw["floor"] = floor + 1
    tw["reset"] = _bump(tw)


def _active(active: list[int], tw: dict) -> list[int]:
    return [pid for pid in active if isinstance(pid, int)]


def solve(tw: dict, floor, skipped: bool, active: list[int], stamp: float) -> None:
    if tw["phase"] != "play" or tw["mode"] != "together" or floor != tw["floor"]:
        return
    if floor in tw["solved"]:
        return
    tw["solved"].append(floor)
    if skipped:
        tw["skipped"].append(floor)
    _bump(tw)
    if floor >= len(tw["list"]) - 1:
        finish(tw, active, stamp)


def vote_skip(tw: dict, me: int, floor, active: list[int], stamp: float) -> None:
    if tw["phase"] != "play" or tw["mode"] != "together" or floor != tw["floor"] or floor in tw["solved"]:
        return
    if me not in tw["votes"]:
        tw["votes"].append(me)
        _bump(tw)
    voters = [v for v in tw["votes"] if v in active]
    if len(voters) * 2 > max(1, len(_active(active, tw))):
        solve(tw, floor, True, active, stamp)


def board(tw: dict, me: int, floor, active: list[int], stamp: float) -> None:
    """He stepped on the lift of a solved floor."""
    if tw["phase"] != "play" or tw["mode"] != "together" or floor != tw["floor"] or floor not in tw["solved"]:
        return
    if me not in tw["aboard"]:
        tw["aboard"].append(me)
        if not tw["aboard_at"]:
            tw["aboard_at"] = stamp
        _bump(tw)
    tick(tw, active, stamp)


def tick(tw: dict, active: list[int], stamp: float) -> None:
    """Called with every pulse: the lift leaves once all are aboard, or BOARD_WAIT after the first."""
    if tw["phase"] != "play" or tw["mode"] != "together" or not tw["aboard"]:
        return
    everyone = set(_active(active, tw))
    if everyone <= set(tw["aboard"]) or stamp - tw["aboard_at"] >= BOARD_WAIT:
        _advance(tw, stamp)


def progress(tw: dict, me: int, floor, stars, ms, done, total, active: list[int], stamp: float) -> None:
    """Race and each-their-own: how far he is (floor reached, stars so far, time, finished)."""
    if tw["phase"] != "play" or tw["mode"] == "together":
        return
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in (floor, stars, ms, total)):
        raise TowerError("badProgress")
    if not (0 <= floor <= MAX_LIST and 0 <= stars <= 3 * MAX_LIST and 0 <= ms < 10 ** 8 and 1 <= total <= MAX_LIST):
        raise TowerError("badProgress")
    tw["progress"][str(me)] = {"floor": floor, "stars": stars, "ms": ms, "done": bool(done), "total": total}
    _bump(tw)
    people = _active(active, tw)
    if people and all(tw["progress"].get(str(pid), {}).get("done") for pid in people):
        finish(tw, active, stamp)


def finish(tw: dict, active: list[int], stamp: float) -> None:
    if tw["phase"] == "done":
        return
    tw["phase"] = "done"
    tw["ended"] = stamp
    players = []
    if tw["mode"] == "together":
        stars = 3 * (len(tw["solved"]) - len(tw["skipped"])) + len(tw["skipped"])
        players = [{"id": pid, "score": stars} for pid in _active(active, tw)]
    else:
        for pid, row in tw["progress"].items():
            try:
                players.append({"id": int(pid), "score": int(row.get("stars", 0)) + (5 if row.get("done") else 0)})
            except (TypeError, ValueError):
                continue
    tw["result"] = {"phase": "done", "players": players}
    _bump(tw)


def to_lobby(tw: dict) -> None:
    keep_rev = tw["rev"]
    tw.clear()
    tw.update(fresh())
    tw["rev"] = keep_rev
    tw["reset"] = _bump(tw)


def apply(room: dict, me: int, is_host: bool, ops, active: list[int], stamp: float) -> list[str]:
    """Applies a pulse's operations in order. A bad one is skipped (its code returned), the rest still run."""
    tw = state(room)
    errors: list[str] = []
    if isinstance(ops, list):
        for op in ops[:MAX_OPS]:
            if not isinstance(op, list) or not op or not isinstance(op[0], str):
                errors.append("badOp")
                continue
            kind, args = op[0], op[1:]
            try:
                if kind == "start":
                    if not is_host:
                        raise TowerError("notHost")
                    if len(args) != 4:
                        raise TowerError("badOp")
                    start(tw, args[0], args[1], args[2], args[3], stamp)
                elif kind == "set" and len(args) == 2:
                    put(tw, args[0], args[1], stamp)
                elif kind == "cas" and len(args) == 3:
                    put(tw, args[0], args[2], stamp, expect=args[1], compare=True)
                elif kind == "solve" and len(args) == 1:
                    solve(tw, args[0], False, active, stamp)
                elif kind == "skip" and len(args) == 1:
                    vote_skip(tw, me, args[0], active, stamp)
                elif kind == "aboard" and len(args) == 1:
                    board(tw, me, args[0], active, stamp)
                elif kind == "progress" and len(args) == 5:
                    progress(tw, me, args[0], args[1], args[2], args[3], args[4], active, stamp)
                elif kind == "finish":
                    if not is_host:
                        raise TowerError("notHost")
                    if tw["phase"] == "play":
                        finish(tw, active, stamp)
                elif kind == "lobby":
                    if not is_host:
                        raise TowerError("notHost")
                    to_lobby(tw)
                else:
                    raise TowerError("badOp")
            except TowerError as err:
                errors.append(err.code)
    tick(tw, active, stamp)
    return errors


def delta(room: dict, since, stamp: float) -> dict:
    """What a client that has seen up to `since` needs: the meta every time, the keys changed since."""
    tw = state(room)
    since = since if isinstance(since, int) and not isinstance(since, bool) else -1
    out = {
        "rev": tw["rev"], "phase": tw["phase"], "mode": tw["mode"], "tier": tw["tier"],
        "seed": tw["seed"], "list": tw["list"], "floor": tw["floor"], "solved": tw["solved"],
        "skipped": tw["skipped"], "votes": len(tw["votes"]), "aboard": tw["aboard"],
        "progress": tw["progress"], "now": int(stamp * 1000),
        "started": int(tw["started"] * 1000),
        "leave": max(0.0, BOARD_WAIT - (stamp - tw["aboard_at"])) if tw["aboard_at"] else -1,
    }
    if since < tw["reset"]:
        out["full"] = True
        out["keys"] = dict(tw["keys"])
    else:
        out["keys"] = {k: v for k, v in tw["keys"].items() if tw["krev"].get(k, 0) > since}
    return out


def summary(room: dict) -> dict:
    """A line for the room's own view (who is how high), without the keys."""
    tw = room.get("tower")
    if not isinstance(tw, dict):
        return {"phase": "lobby"}
    return {"phase": tw["phase"], "mode": tw["mode"], "tier": tw["tier"], "floor": tw["floor"], "floors": len(tw["list"])}

