"""
Rock, paper, scissors as a duel: first to 3 (or 1, or 5) round wins.

Both players choose in secret; when both have chosen (or the clock runs
out), the table counts down and both hands open together. An empty seat is a
bot that watches what its opponent tends to throw and answers it most of
the time, so repeating yourself is punished.

English only: every word a player reads lives in the client.
"""
from __future__ import annotations

import random
import time
from collections import Counter

MAX_SEATS = 2
MOVES = ("rock", "paper", "scissors")
BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}
COUNTER = {loser: winner for winner, loser in BEATS.items()}   # what beats x
TARGETS = (1, 3, 5)
CHOOSE_SECONDS = 12
REVEAL_SECONDS = 3.2


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def _seat(person: dict | None, index: int) -> dict:
    bot = person is None
    person = person or {"id": -(index + 1), "name": "", "photo": ""}
    return {"id": person["id"], "name": person.get("name", ""), "photo": person.get("photo", ""), "bot": bot}


def new_match(people: list[dict], host: int) -> dict:
    seats = [_seat(people[i] if i < len(people) else None, i) for i in range(MAX_SEATS)]
    return {"game": "rps", "host": host, "players": seats, "phase": "setup", "target": 3,
            "scores": [0, 0], "round": 0, "history": [[], []], "rev": 0, "wins": {}}


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat["id"] == user_id and not seat["bot"]:
            return index
    return None


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    bot = next((p for p in state["players"] if p["bot"]), None)
    if bot is None:
        raise Illegal("full")
    bot.update(id=person["id"], name=person["name"], photo=person.get("photo", ""), bot=False)
    state["rev"] += 1


def _host(state: dict, seat: int | None) -> bool:
    if seat is None:
        return False
    ids = [p["id"] for p in state["players"]]
    return state["players"][seat]["id"] == state.get("host") or (state.get("host") not in ids and seat == 0)


def _round(state: dict) -> None:
    state["picks"] = [None, None]
    state["phase"] = "choose"
    state["round"] += 1
    state["deadline"] = now() + CHOOSE_SECONDS
    state["bot_at"] = now() + random.uniform(1.0, 3.2)
    state["result"] = None
    state["rev"] += 1


def bot_move(state: dict, seat: int) -> str:
    """Counter what the other side throws most, most of the time."""
    theirs = state["history"][1 - seat][-8:]
    if len(theirs) >= 2 and random.random() < 0.62:
        # Recent throws count twice: people repeat what just worked.
        weights = Counter(theirs) + Counter(theirs[-3:])
        likely = weights.most_common(1)[0][0]
        return COUNTER[likely]
    return random.choice(MOVES)


def _reveal(state: dict) -> None:
    a, b = state["picks"]
    winner = None if a == b else (0 if BEATS[a] == b else 1)
    state["history"][0].append(a)
    state["history"][1].append(b)
    if winner is not None:
        state["scores"][winner] += 1
    state["result"] = {"picks": [a, b], "winner": winner, "at": int(now() * 1000)}
    state["phase"] = "reveal"
    state["next_at"] = now() + REVEAL_SECONDS
    state["rev"] += 1


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if action in ("target", "go"):
        if not _host(state, seat):
            raise Illegal("notHost")
        if state["phase"] != "setup":
            raise Illegal("badPhase")
        if action == "target":
            target = int(body.get("target") or 0)
            if target not in TARGETS:
                raise Illegal("badTarget")
            state["target"] = target
            state["rev"] += 1
        else:
            state["scores"] = [0, 0]
            state["round"] = 0
            state["winner"] = None
            _round(state)
        return
    if seat is None:
        raise Illegal("watchingOnly")
    if action == "again":
        if state["phase"] != "over":
            raise Illegal("badPhase")
        state["phase"] = "setup"
        state["rev"] += 1
        return
    if action == "pick":
        if state["phase"] != "choose":
            raise Illegal("badPhase")
        move = str(body.get("move") or "")
        if move not in MOVES:
            raise Illegal("badMove")
        if state["picks"][seat] is not None:
            raise Illegal("alreadyPlayed")
        state["picks"][seat] = move
        state["rev"] += 1
        if all(state["picks"]):
            _reveal(state)
        return
    raise Illegal("badAction")


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase == "reveal":
        if now() >= state["next_at"]:
            leader = max(range(2), key=lambda i: state["scores"][i])
            if state["scores"][leader] >= state["target"]:
                state["phase"] = "over"
                state["winner"] = leader
                who = state["players"][leader]
                if not who["bot"]:
                    state["wins"][str(who["id"])] = int(state["wins"].get(str(who["id"]), 0)) + 1
                state["rev"] += 1
            else:
                _round(state)
        return True
    if phase != "choose":
        return False
    for seat in range(2):
        if state["picks"][seat] is None:
            if state["players"][seat]["bot"] and now() >= state["bot_at"]:
                state["picks"][seat] = bot_move(state, seat)
                state["rev"] += 1
            elif now() >= state["deadline"]:
                state["picks"][seat] = random.choice(MOVES)
                state["rev"] += 1
    if all(state["picks"]):
        _reveal(state)
    return True


def view_for(state: dict, seat: int | None) -> dict:
