        "mine": picks[seat] if seat is not None else None,
        "result": state.get("result") if state["phase"] in ("reveal", "over") else None,
        "winner": state.get("winner"),
        "endsIn": max(0, int((state.get("deadline", 0) - now()) * 1000)) if state["phase"] == "choose" else 0,
