"""
Candy room -- the candy game is always played inside a room.

Two ways to play:
  * free (the default): everyone plays their own levels of the full game, and
    the others watch each player's board live, talk on the mic and chat.
  * race: the host starts a race; everyone plays the same seeded board against
    one clock, and the best score wins. Afterwards the room goes back to free.

The board itself runs in each player's browser (the same engine as the solo
game, seeded identically, so the race is fair). The server keeps the clock,
the scores and a compact copy of every board so the others can watch live:
one character per cell (' ' hole, '.' empty, '#' blocker, '0'-'5' candy,
'a'-'f' special candy of that colour, '*' rainbow).

Bots are stand-ins that score at a human-like pace and shuffle a fake board.
This file holds no player text; the client owns every label.
"""
from __future__ import annotations

import random

from games import party
from games.party import Illegal, base_view, drop_bots, host_seat, now, player_view, seat_of

MIN_SEATS = 2
BOT_FILL = 2
MAX_SEATS = 8
DURATIONS = (60, 90, 120)
DEFAULT_DURATION = 90
COUNTDOWN = 4.0
GRACE = 5.0
BOARD_CHARS = set(" .#*0123456789abcdef")
BOARD_MAX = 100
QUIET = ("free", "setup", "final")
BOT_QUIET = ("setup", "final")

# Set by the server: does this user hold Shahd's game-perks badge (a gold frame in the room)?
PERKS = None

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "MAX_SEATS"]


def new_match(people: list[dict], host: int) -> dict:
    state = {
        "game": "candy", "host": host, "players": party.seats(people, MAX_SEATS), "rounds": 1,
        "round": 0, "phase": "free", "free": {}, "phase_at": now(), "deadline": 0.0, "start_at": 0.0,
        "duration": DEFAULT_DURATION, "seed": 0, "boards": {}, "finished": [], "bot_plan": {},
        "cells": 72, "rev": 0,
    }
    return state


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)


def set_bots(state: dict, on: bool) -> None:
    # bots only ever race; in free play they would sit idle
    state["no_bots"] = not on
    if state["phase"] == "free":
        drop_bots(state)
        state["rev"] += 1
        return
    party.set_bots(state, on, BOT_FILL, BOT_QUIET)


def _humans(state: dict) -> list[dict]:
    return [p for p in state["players"] if not p.get("bot")]


def _fake_board(cells: int) -> str:
    out = []
    for _ in range(cells):
        roll = random.random()
        if roll < 0.06:
            out.append("abcde"[random.randrange(5)])
        else:
            out.append(str(random.randrange(5)))
    return "".join(out)


def _start(state: dict) -> None:
    t = now()
    state.update(
        phase="play", phase_at=t, round=1, seed=random.randrange(1, 2 ** 31 - 1),
        start_at=t + COUNTDOWN, deadline=t + COUNTDOWN + state["duration"],
        boards={}, finished=[], bot_plan={},
    )
    for p in state["players"]:
        p["score"] = 0
        if p.get("bot"):
            # points per second, a little different for every bot
            state["bot_plan"][str(p["id"])] = {"rate": random.uniform(260.0, 520.0), "at": state["start_at"]}
            state["boards"][str(p["id"])] = _fake_board(state["cells"])
    state["rev"] += 1


def _end(state: dict) -> None:
    state.update(phase="final", phase_at=now(), deadline=0.0)
    state["rev"] += 1


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    pid = me["id"]
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action == "race":
        if not is_host:
            raise Illegal("notHost")
        if phase != "free":
            raise Illegal("tooLate")
        state.update(phase="setup", phase_at=now(), round=0)
        if not state.get("no_bots"):
            party.fill_bots(state, BOT_FILL)
        state["rev"] += 1
        return

    if action == "free":
        if not is_host:
            raise Illegal("notHost")
        if phase not in ("setup", "final"):
            raise Illegal("tooLate")
        state.update(phase="free", phase_at=now(), round=0, deadline=0.0, start_at=0.0,
                     boards={}, finished=[], bot_plan={})
        drop_bots(state)
        for p in state["players"]:
            p["score"] = 0
        state["rev"] += 1
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            seconds = int(body.get("rounds") or state["duration"])
        except (TypeError, ValueError):
            seconds = state["duration"]
        state["duration"] = seconds if seconds in DURATIONS else DEFAULT_DURATION
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needPlayers")
        _start(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        state.update(round=0, phase="free", phase_at=now(), deadline=0.0, start_at=0.0,
                     boards={}, finished=[], bot_plan={})
        drop_bots(state)
        for p in state["players"]:
            p["score"] = 0
        state["rev"] += 1
        return

    if action == "progress" and phase == "free":
        try:
            level = max(0, min(999, int(body.get("level") or 0)))
            score = max(0, min(50_000_000, int(body.get("score") or 0)))
            top = max(0, min(999, int(body.get("top") or 0)))
        except (TypeError, ValueError):
            return
        board = str(body.get("board") or "")[:BOARD_MAX]
        if board and not all(ch in BOARD_CHARS for ch in board):
            board = ""
        row = {"level": level, "score": score, "board": board, "top": top}
        if state["free"].get(str(pid)) != row:
            state["free"][str(pid)] = row
            state["rev"] += 1
        return

    if action == "progress":
        if phase != "play":
            raise Illegal("tooLate")
        t = now()
        if t < state["start_at"] - 1 or t > state["deadline"] + GRACE:
            return
        try:
            score = int(body.get("score") or 0)
        except (TypeError, ValueError):
            score = 0
        # a generous ceiling against forged numbers: nobody scores this fast
        ceiling = 6000 + int(max(0.0, t - state["start_at"]) * 6000)
        score = max(me["score"], min(score, ceiling))
        board = str(body.get("board") or "")[:BOARD_MAX]
        changed = score != me["score"]
        if board and all(ch in BOARD_CHARS for ch in board):
            if state["boards"].get(str(pid)) != board:
                state["boards"][str(pid)] = board
                state["cells"] = len(board)
                changed = True
        me["score"] = score
        if changed:
            state["rev"] += 1
        return

    if action == "finish":
        if phase != "play":
            return
        if str(pid) not in state["finished"]:
            state["finished"].append(str(pid))
            state["rev"] += 1
        people = _humans(state)
        if now() >= state["deadline"] - 1 and all(str(p["id"]) in state["finished"] for p in people):
            _end(state)
        return

    raise Illegal("badAction")


def step(state: dict) -> bool:
    if state["phase"] != "play":
        return False
    t = now()
    if t < state["start_at"]:
        return True
    playing = t < state["deadline"]
    for p in state["players"]:
        plan = state["bot_plan"].get(str(p["id"]))
        if not p.get("bot") or not plan or not playing or t < plan["at"]:
            continue
        gap = random.uniform(0.9, 2.4)
        p["score"] += int(plan["rate"] * gap * random.uniform(0.4, 1.7))
        plan["at"] = t + gap
        board = list(state["boards"].get(str(p["id"])) or _fake_board(state["cells"]))
        for _ in range(random.randrange(4, 12)):
            board[random.randrange(len(board))] = str(random.randrange(5)) if random.random() > 0.08 else "abcde"[random.randrange(5)]
        state["boards"][str(p["id"])] = "".join(board)
        state["rev"] += 1
    if not playing:
        for p in state["players"]:
            if p.get("bot") and str(p["id"]) not in state["finished"]:
                state["finished"].append(str(p["id"]))
        people = _humans(state)
        if t >= state["deadline"] + GRACE or all(str(p["id"]) in state["finished"] for p in people):
            _end(state)
    return True


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    view = base_view(state, seat)
    t = now()
    done = {int(k) for k in state["finished"]} if phase == "play" else set()
    view["players"] = player_view(state, done)
    for p, row in zip(state["players"], view["players"]):
        if "perks" not in p:
            try:
                p["perks"] = bool(not p.get("bot") and PERKS and PERKS(int(p["id"])))
            except Exception:  # noqa: BLE001
                p["perks"] = False
        row["perks"] = p["perks"]
    view["minSeats"] = MIN_SEATS
    # the setup card highlights the chosen length through `rounds`
    view["rounds"] = state["duration"] if phase == "setup" else 1
    if phase == "free":
        view["free"] = dict(state.get("free") or {})
    view["duration"] = state["duration"]
    if phase == "setup":
        view["roundChoices"] = list(DURATIONS)
    if phase == "play":
        view["seed"] = state["seed"]
        view["startsIn"] = max(0, int((state["start_at"] - t) * 1000))
        view["boards"] = dict(state["boards"])
        view["finished"] = list(state["finished"])
    return view

