"""
سباق الحروف — حرفٌ واحد وستّ خانات: اسم، حيوان، نبات، جماد، بلد، أكلة.

الجولة: كلٌّ يملأ خاناته بكلماتٍ تبدأ بالحرف. أوّل من يكمل الستّ ويضغط «وقّف!» يقلّص
الوقت على الباقين إلى عشر ثوانٍ ← مراجعة: تظهر إجابات الكل، ولكلٍّ أن يعترض على إجابة
غيره (إن اعترض نصف الباقين أو أكثر سقطت) ← النتيجة.
النقاط: إجابةٌ صحيحة لم يكتبها غيرك ١٠، ومكرّرة ٥، وأوّل من وقّف +٥.
"""
from __future__ import annotations

import json
import pathlib
import random
import re

from games import party
from games.party import Illegal, base_view, drop_bots, host_seat, now, player_view, seat_of, seats

HERE = pathlib.Path(__file__).resolve().parent
WORDS = json.loads((HERE / "content" / "words.json").read_text(encoding="utf-8"))

CATEGORIES = [("name", "اسم"), ("animal", "حيوان"), ("plant", "نبات"),
              ("object", "جماد"), ("country", "بلد"), ("food", "أكلة")]
KEYS = [k for k, _ in CATEGORIES]
LETTERS = list("ابتجحخدرزسشصطعفقكلمنهوي")
MIN_SEATS = 1
BOT_FILL = 3
MAX_SEATS = 10
ROUND_CHOICES = (3, 5, 7)
DEFAULT_ROUNDS = 5
WRITE_SECONDS = 90
STOP_SECONDS = 10
REVIEW_SECONDS = 30
RESULT_SECONDS = 20
MAX_WORD = 24
UNIQUE, SHARED, STOP_BONUS = 10, 5, 5
QUIET = ("setup", "result", "final")

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "MAX_SEATS"]

_MARKS = re.compile(r"[ً-ٰٟـ]")


def norm(text: str) -> str:
    text = _MARKS.sub("", str(text or "")).strip()
    text = re.sub(r"[أإآٱ]", "ا", text).replace("ى", "ي").replace("ة", "ه")
    return " ".join(text.split())


def starts_with(text: str, letter: str) -> bool:
    word = norm(text)
    if not word:
        return False
    if word.startswith(letter):
        return True
    return word.startswith("ال") and word[2:].startswith(letter)


def _known(category: str, text: str) -> bool:
    word = norm(text)
    bare = word[2:] if word.startswith("ال") else word
    for w in WORDS.get(category, []):
        n = norm(w)
        if n == word or (n[2:] if n.startswith("ال") else n) == bare:
            return True
    return False


def new_match(people: list[dict], host: int) -> dict:
    state = {"game": "huroof", "host": host, "players": seats(people, MAX_SEATS), "rounds": DEFAULT_ROUNDS,
             "round": 0, "phase": "setup", "phase_at": now(), "deadline": 0.0, "letter": "", "used": [],
             "answers": {}, "done": [], "stopper": None, "rejects": {}, "ready": [], "result": None,
             "bot_due": {}, "rev": 0}
    party.fill_bots(state, BOT_FILL)
    return state


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)


def set_bots(state: dict, on: bool) -> None:
    party.set_bots(state, on, BOT_FILL, QUIET)


def _begin_round(state: dict) -> None:
    drop_bots(state)
    fresh = [l for l in LETTERS if l not in state["used"]] or LETTERS
    state["letter"] = random.choice(fresh)
    state["used"].append(state["letter"])
    state["round"] += 1
    state.update(phase="write", phase_at=now(), deadline=now() + WRITE_SECONDS, answers={}, done=[],
                 stopper=None, rejects={}, ready=[], result=None)
    state["bot_due"] = {str(p["id"]): now() + random.uniform(30, 75) for p in state["players"] if p.get("bot")}
    state["rev"] += 1


def _bot_answers(state: dict) -> dict:
    letter = state["letter"]
    out = {}
    for key in KEYS:
        options = [w for w in WORDS.get(key, []) if starts_with(w, letter)]
        if options and random.random() < 0.72:
            out[key] = random.choice(options)
    return out


def _open_review(state: dict) -> None:
    for key in list(state["bot_due"]):
        state["answers"][key] = _bot_answers(state)
    state["bot_due"] = {}
    state.update(phase="review", phase_at=now(), deadline=now() + REVIEW_SECONDS, ready=[])
    state["rev"] += 1


def _verdicts(state: dict) -> dict:
    """لكل لاعبٍ ولكل خانة: «ok» أو «dup» أو «bad» (لا تبدأ بالحرف) أو «out» (اعترضوا عليها) أو «empty»."""
    letter = state["letter"]
    human_ids = [p["id"] for p in state["players"] if not p.get("bot")]
    out: dict[str, dict[str, str]] = {}
    for p in state["players"]:
        pid = str(p["id"])
        mine = state["answers"].get(pid, {})
        row = {}
        for key in KEYS:
            text = mine.get(key, "")
            if not text:
                row[key] = "empty"
            elif not starts_with(text, letter):
                row[key] = "bad"
            else:
                judges = [h for h in human_ids if h != p["id"]]
                marks = len(state["rejects"].get(f"{pid}:{key}", []))
                row[key] = "out" if marks and judges and marks * 2 >= len(judges) else "ok"
        out[pid] = row
    for key in KEYS:
        seen: dict[str, list[str]] = {}
        for pid, row in out.items():
            if row[key] == "ok":
                seen.setdefault(norm(state["answers"][pid][key]), []).append(pid)
        for group in seen.values():
            if len(group) > 1:
                for pid in group:
                    out[pid][key] = "dup"
    return out


def _score(state: dict) -> None:
    verdicts = _verdicts(state)
    gains = {}
    for p in state["players"]:
        pid = str(p["id"])
        gain = sum(UNIQUE if v == "ok" else SHARED if v == "dup" else 0 for v in verdicts[pid].values())
        if state["stopper"] == p["id"]:
            gain += STOP_BONUS
        gains[pid] = gain
        p["score"] += gain
    state["result"] = {"verdicts": verdicts, "gains": gains}
    state.update(phase="result", phase_at=now(), deadline=now() + RESULT_SECONDS, ready=[])
    state["rev"] += 1


def _after_result(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0)
        state["rev"] += 1
    else:
        _begin_round(state)


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    pid = str(me["id"])
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        _begin_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        for player in state["players"]:
            player["score"] = 0
        state.update(round=0, used=[], phase="setup", phase_at=now(), deadline=0.0, result=None, answers={})
        drop_bots(state)
        state["rev"] += 1
        return

    if action in ("save", "stop"):
        if phase != "write":
            raise Illegal("tooLate")
        given = body.get("answers") if isinstance(body.get("answers"), dict) else {}
        row = state["answers"].setdefault(pid, {})
        for key in KEYS:
            if key in given:
                row[key] = " ".join(str(given[key] or "").split())[:MAX_WORD]
        if action == "stop":
            if not all(row.get(k) for k in KEYS):
                raise Illegal("fillAll")
            if me["id"] not in state["done"]:
                state["done"].append(me["id"])
            if state["stopper"] is None:
                state["stopper"] = me["id"]
                state["deadline"] = min(state["deadline"], now() + STOP_SECONDS)
        state["rev"] += 1
        return

    if action == "reject":
        if phase != "review":
            raise Illegal("tooLate")
        target = str(body.get("player"))
        key = str(body.get("key"))
        if key not in KEYS or target == pid or not any(str(p["id"]) == target for p in state["players"]):
            raise Illegal("badTarget")
        marks = state["rejects"].setdefault(f"{target}:{key}", [])
        if me["id"] in marks:
            marks.remove(me["id"])
        else:
            marks.append(me["id"])
        state["rev"] += 1
        return

    if action == "ready":
        if phase in ("review", "result") and me["id"] not in state["ready"]:
            state["ready"].append(me["id"])
            state["rev"] += 1
        return

    raise Illegal("badAction")


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    human_ids = [p["id"] for p in state["players"] if not p.get("bot")]
    if phase == "write":
        humans_done = all(h in state["done"] for h in human_ids)
        if humans_done or t >= state["deadline"]:
            _open_review(state)
        return True
    if phase in ("review", "result"):
        ready = human_ids and all(h in state["ready"] for h in human_ids) and t - state["phase_at"] > 2
        if ready or t >= state["deadline"]:
            if phase == "review":
                _score(state)
            else:
                _after_result(state)
        return True
    return False


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    if phase == "write":
        done = set(state["done"])
    elif phase in ("review", "result"):
        done = set(state["ready"])
    else:
        done = set()
    view = base_view(state, seat)
    view["players"] = player_view(state, done)
    view["categories"] = [{"key": k, "label": l} for k, l in CATEGORIES]
    view["letter"] = state["letter"]
    view["stopper"] = state["stopper"]
    if phase == "setup":
        view["roundChoices"] = list(ROUND_CHOICES)
    me = str(state["players"][seat]["id"]) if seat is not None else None
    if phase == "write" and me is not None:
        view["mine"] = state["answers"].get(me, {})
    if phase in ("review", "result"):
        view["answers"] = state["answers"]
        view["known"] = {pid: {k: _known(k, v) for k, v in row.items() if v}
                         for pid, row in state["answers"].items()}
        view["rejects"] = {k: v for k, v in state["rejects"].items() if v}
    if phase == "result":
        view["result"] = state["result"]
    return view

