"""
Ludo (Sheesh) - two to four players, four pieces each, bots fill the empty seats.

The track is 52 squares shared by everyone; each colour enters it at its own
start square and, after 50 steps, turns into its own six-square home column.
A piece is described by its progress along its own route:

    -1        in the yard
    0 .. 50   on the shared track (start square = 0)
    51 .. 55  in the home column
    56        home (finished)

Rules as they are usually played in the Gulf:
  - a six brings a piece out of the yard, and a six rolls again; three sixes
    in a row lose the turn;
  - landing on a lone enemy piece sends it back to the yard and rolls again,
    except on the eight safe squares (the four starts and four stars);
  - two or more pieces of one colour on a square are a wall: they cannot be
    captured;
  - reaching home rolls again, and home needs the exact number;
  - the first to bring all four home wins; the rest are ranked by progress.
"""
from __future__ import annotations

import json
import pathlib
import random
import time

HERE = pathlib.Path(__file__).resolve().parent
_LOCALE = json.loads((HERE / "locales" / "ar.json").read_text(encoding="utf-8"))

TRACK = 52
LAST_TRACK = 50
HOME = 56
COLORS = ("red", "green", "yellow", "blue")
START = {"red": 0, "green": 13, "yellow": 26, "blue": 39}
SAFE = {0, 8, 13, 21, 26, 34, 39, 47}
SEAT_COLORS = {2: ("red", "yellow"), 3: ("red", "green", "yellow"), 4: COLORS}
COUNTS = (2, 3, 4)
TURN_SECONDS = 15
BOT_ROLL_DELAY = 0.9
BOT_MOVE_DELAY = 0.8
MOVE_MS_PER_STEP = 170
MAX_SEATS = 4


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


def _seat(person: dict, bot: bool = False) -> dict:
    return {"id": person["id"], "name": person["name"], "photo": person.get("photo", ""),
            "bot": bot, "color": "", "pieces": [-1, -1, -1, -1], "home": 0, "caps": 0}


def new_match(people: list[dict], host: int) -> dict:
    humans = [_seat(p) for p in people[:MAX_SEATS]]
    return {
        "game": "ludo", "host": host, "players": humans,
        "count": max(2, min(4, len(humans) if len(humans) > 1 else 4)),
        "phase": "setup", "turn": 0, "dice": 0, "rolled": False, "sixes": 0,
        "movable": [], "deadline": 0.0, "bot_at": 0.0, "busy_until": 0.0,
        "last": None, "winner": None, "rank": [], "wins": {}, "rolls": 0,
        "rev": 0,
    }


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if seat["id"] == user_id and not seat["bot"]:
            return index
    return None


def host_seat(state: dict) -> int | None:
    seat = seat_of(state, state.get("host", 0))
    if seat is not None:
        return seat
    return next((i for i, p in enumerate(state["players"]) if not p["bot"]), None)


def sit(state: dict, person: dict) -> None:
    if seat_of(state, person["id"]) is not None:
        return
    if state["phase"] == "setup":
        if len(state["players"]) >= MAX_SEATS:
            raise Illegal("full")
        state["players"].append(_seat(person))
        state["count"] = max(state["count"], len(state["players"]))
    else:
        # Mid-game a newcomer takes over a bot's seat, pieces and all.
        bot = next((p for p in state["players"] if p["bot"]), None)
        if bot is None:
            raise Illegal("full")
        bot.update(id=person["id"], name=person["name"], photo=person.get("photo", ""), bot=False)
    state["rev"] += 1


# ============================== geometry ==============================

def square(color: str, progress: int) -> int | None:
    """The shared-track square a piece stands on, or None off the track."""
    if 0 <= progress <= LAST_TRACK:
        return (START[color] + progress) % TRACK
    return None


def _occupants(state: dict, sq: int) -> list[tuple[int, int]]:
    out = []
    for seat, player in enumerate(state["players"]):
        for token, progress in enumerate(player["pieces"]):
            if square(player["color"], progress) == sq:
                out.append((seat, token))
    return out


def target(state: dict, seat: int, token: int, dice: int) -> int | None:
    progress = state["players"][seat]["pieces"][token]
    if progress == HOME:
        return None
    if progress == -1:
        return 0 if dice == 6 else None
    to = progress + dice
    return to if to <= HOME else None


def legal_moves(state: dict, seat: int, dice: int) -> list[int]:
    return [t for t in range(4) if target(state, seat, t, dice) is not None]


# ============================== flow ==============================

def _begin(state: dict) -> None:
    count = state["count"]
    humans = [p for p in state["players"] if not p["bot"]][:count]
    names = [n for n in _LOCALE["bots"] if n not in {p["name"] for p in humans}]
    seats = humans[:]
    n = 1
    while len(seats) < count:
        seats.append(_seat({"id": -n, "name": names.pop(0) if names else f"{_LOCALE['bot']} {n}"}, bot=True))
        n += 1
    colors = SEAT_COLORS[count]
    for index, seat in enumerate(seats):
        seat.update(color=colors[index], pieces=[-1, -1, -1, -1], home=0, caps=0)
    state["players"] = seats
    state.update(phase="play", turn=random.randrange(count), dice=0, rolled=False, sixes=0,
                 movable=[], last=None, winner=None, rank=[], rolls=0)
    _clock(state)
    state["rev"] += 1


def _clock(state: dict) -> None:
    state["deadline"] = now() + TURN_SECONDS
    state["bot_at"] = 0.0


def _next_turn(state: dict) -> None:
    state["turn"] = (state["turn"] + 1) % len(state["players"])
    state.update(dice=0, rolled=False, sixes=0, movable=[])
    _clock(state)
    state["rev"] += 1


def _again(state: dict) -> None:
    """Same player rolls once more."""
    state.update(dice=0, rolled=False, movable=[])
    _clock(state)
    state["rev"] += 1


def _roll(state: dict, seat: int) -> None:
    dice = random.randint(1, 6)
    state["rolls"] += 1
    state["dice"] = dice
    state["rolled"] = True
    state["sixes"] = state["sixes"] + 1 if dice == 6 else 0
    state["last"] = {"kind": "roll", "seat": seat, "dice": dice, "at": now(), "n": state["rolls"]}
    state["rev"] += 1
    if state["sixes"] >= 3:
        state["last"]["burnt"] = True
        _pause(state, 0.9)
        _next_turn(state)
        return
    state["movable"] = legal_moves(state, seat, dice)
    if not state["movable"]:
        _pause(state, 0.9)
        if dice == 6:
            _again(state)
        else:
            _next_turn(state)
        return
    _clock(state)


def _pause(state: dict, seconds: float) -> None:
    state["busy_until"] = max(state["busy_until"], now() + seconds)


def _move(state: dict, seat: int, token: int) -> None:
    player = state["players"][seat]
    dice = state["dice"]
    start = player["pieces"][token]
    to = target(state, seat, token, dice)
    if to is None:
        raise Illegal("cannotMove")
    player["pieces"][token] = to
    captured = []
    sq = square(player["color"], to)
    if sq is not None and sq not in SAFE:
        enemies: dict[int, list[int]] = {}
        for other, piece in _occupants(state, sq):
            if other != seat:
                enemies.setdefault(other, []).append(piece)
        for other, pieces in enemies.items():
            if len(pieces) >= 2:
                continue  # a wall stands
            for piece in pieces:
                state["players"][other]["pieces"][piece] = -1
                captured.append({"seat": other, "token": piece})
        if captured:
            player["caps"] += len(captured)
    reached = to == HOME
    if reached:
        player["home"] += 1
    steps = 1 if start == -1 else to - start
    state["last"] = {"kind": "move", "seat": seat, "token": token, "from": start, "to": to,
                     "captured": captured, "home": reached, "dice": dice, "at": now(), "n": state["rolls"]}
    _pause(state, steps * MOVE_MS_PER_STEP / 1000 + (0.5 if captured else 0.15))
    state["rev"] += 1
    if player["home"] == 4:
        _finish(state, seat)
        return
    if dice == 6 or captured or reached:
        _again(state)
    else:
        _next_turn(state)


def _finish(state: dict, winner: int) -> None:
    def progress(i: int) -> tuple:
        p = state["players"][i]
        return (p["home"], sum(max(0, x) for x in p["pieces"]))
    order = sorted(range(len(state["players"])), key=progress, reverse=True)
    order.remove(winner)
    state["winner"] = winner
    state["rank"] = [winner] + order
    key = str(state["players"][winner]["id"])
    state["wins"][key] = state["wins"].get(key, 0) + 1
    state.update(phase="over", movable=[], deadline=0.0)
    state["rev"] += 1


# ============================== bot ==============================

def _danger(state: dict, seat: int, sq: int) -> int:
    """How many enemy pieces could land on this square with one roll."""
    if sq in SAFE:
        return 0
    threat = 0
    for other, player in enumerate(state["players"]):
        if other == seat:
            continue
        for progress in player["pieces"]:
            if 0 <= progress <= LAST_TRACK:
                behind = (sq - square(player["color"], progress)) % TRACK
                if 1 <= behind <= 6 and progress + behind <= LAST_TRACK:
                    threat += 1
            elif progress == -1 and sq == START[player["color"]]:
                threat += 1
    return threat


def best_move(state: dict, seat: int) -> int:
    player = state["players"][seat]
    dice = state["dice"]
    best, best_score = state["movable"][0], -1e9
    for token in state["movable"]:
        start = player["pieces"][token]
        to = target(state, seat, token, dice)
        score = 0.0
        sq = square(player["color"], to)
        if to == HOME:
            score += 60
        if start == -1:
            score += 45
        if sq is not None and sq not in SAFE:
            victims = [o for o, _ in _occupants(state, sq) if o != seat]
            if victims and len(victims) == 1:
                score += 80 + to * 0.3
        if sq is not None:
            score -= _danger(state, seat, sq) * 18
            if sq in SAFE:
                score += 12
        before = square(player["color"], start) if start >= 0 else None
        if before is not None:
            score += _danger(state, seat, before) * 14  # escaping a threat
        if 51 <= to <= 55:
            score += 20
        score += to * 0.35 + random.random() * 2
        if score > best_score:
            best, best_score = token, score
    return best


# ============================== actions ==============================

def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    if seat is None:
        raise Illegal("watchingOnly")
    is_host = seat == host_seat(state)
    if action == "setup":
        if state["phase"] != "setup":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        count = int(body.get("count", 4))
        if count not in COUNTS or count < len([p for p in state["players"] if not p["bot"]]):
            raise Illegal("badCount")
        state["count"] = count
        state["rev"] += 1
        return
    if action == "go":
        if state["phase"] != "setup":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        _begin(state)
        return
    if action == "again":
        if state["phase"] != "over":
            raise Illegal("notNow")
        if not is_host:
            raise Illegal("notHost")
        state["players"] = [p for p in state["players"] if not p["bot"]]
        _begin(state)
        return
    if state["phase"] != "play":
        raise Illegal("notNow")
    if seat != state["turn"]:
        raise Illegal("notYourTurn")
    if now() < state["busy_until"]:
        raise Illegal("slowDown")
    if action == "roll":
        if state["rolled"]:
            raise Illegal("alreadyRolled")
        _roll(state, seat)
        return
    if action == "move":
        if not state["rolled"]:
            raise Illegal("rollFirst")
        token = int(body.get("token", -1))
        if token not in state["movable"]:
            raise Illegal("cannotMove")
        _move(state, seat, token)
        return
    raise Illegal("badAction")


def step(state: dict) -> bool:
    if state["phase"] != "play":
        return False
    t = now()
    if t < state["busy_until"]:
        return True
    seat = state["turn"]
    player = state["players"][seat]
    late = t >= state["deadline"]
    if player["bot"] or late:
        if not state["bot_at"]:
            state["bot_at"] = t + (0 if late else (BOT_MOVE_DELAY if state["rolled"] else BOT_ROLL_DELAY))
            return True
        if t < state["bot_at"]:
            return True
        state["bot_at"] = 0.0
        if not state["rolled"]:
            _roll(state, seat)
        elif state["movable"]:
            _move(state, seat, best_move(state, seat))
    return True


# ============================== view ==============================

def view_for(state: dict, seat: int | None) -> dict:
    t = now()
    return {
        "game": "ludo", "phase": state["phase"], "seat": seat,
        "isHost": seat is not None and seat == host_seat(state),
        "count": state["count"], "counts": list(COUNTS),
        "players": [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": p["bot"],
                     "color": p["color"], "pieces": p["pieces"], "home": p["home"], "caps": p["caps"],
                     "wins": state["wins"].get(str(p["id"]), 0)}
                    for p in state["players"]],
        "turn": state["turn"], "dice": state["dice"], "rolled": state["rolled"],
        "movable": state["movable"] if seat == state["turn"] else [],
        "targets": {str(tk): target(state, state["turn"], tk, state["dice"]) for tk in state["movable"]} if seat == state["turn"] else {},
        "last": state["last"], "winner": state["winner"], "rank": state["rank"],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state["phase"] == "play" else 0,
        "busyFor": max(0, int((state["busy_until"] - t) * 1000)),
        "safe": sorted(SAFE), "start": START,
        "rev": state["rev"],
    }

