"""
Who Said It (meen) -- a party game about the people in the room.

Two kinds of round:
  * write: everyone answers the same prompt in secret; the answers are shown
    unsigned and everyone guesses who wrote each one.
  * chat:  real lines the players typed in the room chat are shown; guess who
    said them. Played every third round when the chat has enough lines.

Scoring: a right guess is +2 for the guesser ("read"); every wrong guess on
your own line is +1 for you ("fooled"). Your own line is never yours to guess.

All player text lives in content/prompts.json; this file holds no player text.
Per-player data is keyed by id, never by seat, so bots leaving or late players
taking a bot's seat renumber nothing.
"""
from __future__ import annotations

import json
import pathlib
import random

from games import party
from games.party import Illegal, base_view, drop_bots, host_seat, now, player_view, seat_of

HERE = pathlib.Path(__file__).resolve().parent
CONTENT = json.loads((HERE / "content" / "prompts.json").read_text(encoding="utf-8"))
PROMPTS: list[dict] = CONTENT["prompts"]
BOT_FALLBACK: list[str] = CONTENT["botFallback"]

MIN_SEATS = 3
BOT_FILL = 3
MAX_SEATS = 10
ROUND_CHOICES = (4, 6, 8)
DEFAULT_ROUNDS = 6
WRITE_SECONDS = 75
GUESS_BASE = 30
GUESS_PER_CARD = 6
REVEAL_SECONDS = 18
MAX_LEN = 120
CHAT_EVERY = 3
CHAT_CARDS = 4
QUOTE_MIN, QUOTE_MAX = 6, 140
QUIET = ("setup", "reveal", "final")

__all__ = ["Illegal", "new_match", "act", "step", "view_for", "seat_of", "sit", "set_bots", "feed", "MAX_SEATS"]


def new_match(people: list[dict], host: int) -> dict:
    state = {
        "game": "meen", "host": host, "players": party.seats(people, MAX_SEATS), "rounds": DEFAULT_ROUNDS,
        "round": 0, "phase": "setup", "phase_at": now(), "deadline": 0.0, "kind": "write",
        "prompt": "", "subject": None, "answers": {}, "cards": [], "guesses": {}, "ready": [],
        "tally": {}, "used": [], "used_quotes": [], "quotes": [], "result": None,
        "bot_plan": {}, "rev": 0,
    }
    party.fill_bots(state, BOT_FILL)
    return state


def feed(state: dict, room: dict) -> None:
    """Called by the table before every action: keep the room's real chat lines at hand."""
    out = []
    for line in room.get("chat") or []:
        if line.get("sys") or not isinstance(line.get("id"), int):
            continue
        text = str(line.get("text") or "").strip()
        if QUOTE_MIN <= len(text) <= QUOTE_MAX and not text.startswith(("/", "http")):
            out.append({"id": line["id"], "text": text})
    state["quotes"] = out[-80:]


def sit(state: dict, person: dict) -> None:
    party.sit(state, person, QUIET, MAX_SEATS)


def set_bots(state: dict, on: bool) -> None:
    party.set_bots(state, on, BOT_FILL, QUIET)


def _ids(state: dict) -> set:
    return {p["id"] for p in state["players"]}


def _humans(state: dict) -> list[dict]:
    return [p for p in state["players"] if not p.get("bot")]


def _tally(state: dict, pid, key: str) -> None:
    row = state["tally"].setdefault(str(pid), {"fooled": 0, "read": 0})
    row[key] += 1


def _chat_round_ready(state: dict) -> list[dict]:
    """Unused chat lines whose authors still sit at the table, from at least two people."""
    seated = {p["id"] for p in _humans(state)}
    used = set(state["used_quotes"])
    pool = [q for q in state["quotes"] if q["id"] in seated and q["text"] not in used]
    return pool if len({q["id"] for q in pool}) >= 2 and len(pool) >= 3 else []


def _start_round(state: dict) -> None:
    drop_bots(state)
    state["round"] += 1
    state.update(answers={}, cards=[], guesses={}, ready=[], result=None, bot_plan={}, subject=None)
    pool = _chat_round_ready(state) if state["round"] % CHAT_EVERY == 0 else []
    if pool:
        random.shuffle(pool)
        picked, per_author = [], {}
        for q in pool:
            if per_author.get(q["id"], 0) >= 2:
                continue
            per_author[q["id"]] = per_author.get(q["id"], 0) + 1
            picked.append(q)
            if len(picked) >= CHAT_CARDS:
                break
        state["used_quotes"] += [q["text"] for q in picked]
        state["kind"] = "chat"
        state["prompt"] = ""
        state["cards"] = [{"id": f"c{i}", "text": q["text"], "author": q["id"]} for i, q in enumerate(picked)]
        _open_guessing(state)
        return
    state["kind"] = "write"
    fresh = [i for i in range(len(PROMPTS)) if i not in state["used"]] or list(range(len(PROMPTS)))
    index = random.choice(fresh)
    state["used"].append(index)
    prompt = PROMPTS[index]
    text = prompt["q"]
    # {p} and {p2} are two different seated players, so prompts can be about the room itself.
    humans = [p for p in state["players"] if not p.get("bot")]
    pool = humans if len(humans) >= 2 else state["players"]
    people = random.sample(pool, min(2, len(pool)))
    names = {"{p}": people[0]["name"] if people else "", "{p2}": people[-1]["name"] if people else ""}
    if "{p}" in text and people:
        state["subject"] = people[0]["id"]

    def fill(line: str) -> str:
        for key, name in names.items():
            line = line.replace(key, name)
        return line

    state["prompt"] = fill(text)
    lines = [fill(line) for line in (prompt.get("bots") or [])] + BOT_FALLBACK
    for p in state["players"]:
        if p.get("bot"):
            state["bot_plan"][str(p["id"])] = {"at": now() + random.uniform(8, 40), "text": random.choice(lines)}
    state.update(phase="write", phase_at=now(), deadline=now() + WRITE_SECONDS)
    state["rev"] += 1


def _open_guessing(state: dict) -> None:
    if state["kind"] == "write":
        rows = [(pid, text) for pid, text in state["answers"].items()]
        random.shuffle(rows)
        state["cards"] = [{"id": f"c{i}", "text": text, "author": int(pid)} for i, (pid, text) in enumerate(rows)]
    if len(state["cards"]) < 2:
        _reveal(state)
        return
    state["bot_plan"] = {}
    for p in state["players"]:
        if p.get("bot"):
            state["bot_plan"][str(p["id"])] = {"at": now() + random.uniform(5, 20)}
    seconds = GUESS_BASE + GUESS_PER_CARD * len(state["cards"])
    state.update(phase="guess", phase_at=now(), deadline=now() + seconds)
    state["rev"] += 1


def _bot_guess(state: dict, pid: int) -> dict:
    ids = [p["id"] for p in state["players"] if p["id"] != pid]
    out = {}
    for card in state["cards"]:
        if card["author"] == pid:
            continue
        out[card["id"]] = card["author"] if random.random() < 0.35 else random.choice(ids)
    return out


def _reveal(state: dict) -> None:
    scores = {p["id"]: 0 for p in state["players"]}
    outcome = []
    for card in state["cards"]:
        right, wrong = [], []
        for pid_s, picks in state["guesses"].items():
            pid = int(pid_s)
            if pid == card["author"] or card["id"] not in picks:
                continue
            if picks[card["id"]] == card["author"]:
                right.append(pid)
                scores[pid] = scores.get(pid, 0) + 2
                _tally(state, pid, "read")
            else:
                wrong.append(pid)
                scores[card["author"]] = scores.get(card["author"], 0) + 1
                _tally(state, card["author"], "fooled")
        outcome.append({"id": card["id"], "text": card["text"], "author": card["author"],
                        "right": right, "wrong": wrong,
                        "picks": {pid_s: picks.get(card["id"]) for pid_s, picks in state["guesses"].items()
                                  if card["id"] in picks}})
    for p in state["players"]:
        p["score"] += scores.get(p["id"], 0)
    state["result"] = {"cards": outcome, "gained": {str(k): v for k, v in scores.items()}}
    state.update(phase="reveal", phase_at=now(), deadline=now() + REVEAL_SECONDS, ready=[])
    state["rev"] += 1


def _after_reveal(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        state.update(phase="final", phase_at=now(), deadline=0.0)
        state["rev"] += 1
    else:
        _start_round(state)


def _all_humans(state: dict, done) -> bool:
    people = _humans(state)
    return bool(people) and all(str(p["id"]) in done for p in people)


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    me = state["players"][seat]
    pid = me["id"]
    is_host = seat == host_seat(state)

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        state["rev"] += 1
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        if len(state["players"]) < MIN_SEATS:
            raise Illegal("needPlayers")
        _start_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase != "final":
            raise Illegal("tooLate")
        state.update(round=0, used=[], tally={}, phase="setup", phase_at=now(), deadline=0.0, cards=[],
                     answers={}, guesses={}, result=None, prompt="", ready=[])
        drop_bots(state)
        for p in state["players"]:
            p["score"] = 0
        state["rev"] += 1
        return

    if action == "write":
        if phase != "write":
            raise Illegal("tooLate")
        text = " ".join(str(body.get("text") or "").split())[:MAX_LEN]
        if len(text) < 2:
            raise Illegal("tooShort")
        state["answers"][str(pid)] = text
        state["rev"] += 1
        if _all_humans(state, state["answers"]):
            # Nobody waits on bots: the ones still "typing" hand in their line now.
            for p in state["players"]:
                plan = state["bot_plan"].get(str(p["id"]))
                if p.get("bot") and plan and str(p["id"]) not in state["answers"]:
                    state["answers"][str(p["id"])] = plan["text"]
            _open_guessing(state)
        return

    if action == "guess":
        if phase != "guess":
            raise Illegal("tooLate")
        picks = body.get("picks")
        if not isinstance(picks, dict):
            raise Illegal("badGuess")
        ids = _ids(state)
        clean = {}
        for card in state["cards"]:
            if card["author"] == pid:
                continue
            try:
                choice = int(picks.get(card["id"]))
            except (TypeError, ValueError):
                continue
            if choice in ids and choice != pid:
                clean[card["id"]] = choice
        state["guesses"][str(pid)] = clean
        state["rev"] += 1
        if _all_humans(state, state["guesses"]):
            for p in state["players"]:
                if p.get("bot") and str(p["id"]) not in state["guesses"]:
                    state["guesses"][str(p["id"])] = _bot_guess(state, p["id"])
            _reveal(state)
        return

    if action == "ready":
        if phase != "reveal":
            return
        if str(pid) not in state["ready"]:
            state["ready"].append(str(pid))
            state["rev"] += 1
        if _all_humans(state, set(state["ready"])):
            _after_reveal(state)
        return

    raise Illegal("badAction")


def step(state: dict) -> bool:
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    if phase == "write":
        for p in state["players"]:
            plan = state["bot_plan"].get(str(p["id"]))
            if p.get("bot") and plan and t >= plan["at"] and str(p["id"]) not in state["answers"]:
                state["answers"][str(p["id"])] = plan["text"]
                state["rev"] += 1
        everyone = all(str(p["id"]) in state["answers"] for p in state["players"])
        if t >= state["deadline"] or everyone:
            _open_guessing(state)
        return True
    if phase == "guess":
        for p in state["players"]:
            plan = state["bot_plan"].get(str(p["id"]))
            if p.get("bot") and plan and t >= plan["at"] and str(p["id"]) not in state["guesses"]:
                state["guesses"][str(p["id"])] = _bot_guess(state, p["id"])
                state["rev"] += 1
        everyone = all(str(p["id"]) in state["guesses"] for p in state["players"])
        if t >= state["deadline"] or everyone:
            _reveal(state)
        return True
    if phase == "reveal":
        if t >= state["deadline"]:
            _after_reveal(state)
        return True
    return False


def _titles(state: dict) -> dict:
    out = {}
    for key in ("fooled", "read"):
        best = max(((int(pid), row[key]) for pid, row in state["tally"].items()), key=lambda r: r[1], default=None)
        if best and best[1] > 0:
            out[key] = {"id": best[0], "count": best[1]}
    return out


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    view = base_view(state, seat)
    done = set()
    if phase == "write":
        done = {int(k) for k in state["answers"]}
    elif phase == "guess":
        done = {int(k) for k in state["guesses"]}
    elif phase == "reveal":
        done = {int(k) for k in state["ready"]}
    view["players"] = player_view(state, done)
    view["minSeats"] = MIN_SEATS
    view["kind"] = state["kind"]
    view["maxLen"] = MAX_LEN
    me = state["players"][seat]["id"] if seat is not None else None
    if phase == "setup":
        view["roundChoices"] = list(ROUND_CHOICES)
        view["chatLines"] = len(state.get("quotes") or [])
    if phase == "write":
        view["prompt"] = state["prompt"]
        view["subject"] = state["subject"]
        view["mine"] = state["answers"].get(str(me), "") if me is not None else ""
    if phase == "guess":
        view["prompt"] = state["prompt"]
        view["cards"] = [{"id": c["id"], "text": c["text"], "mine": c["author"] == me} for c in state["cards"]]
        view["picked"] = state["guesses"].get(str(me), {}) if me is not None else {}
    if phase == "reveal":
        view["prompt"] = state["prompt"]
        view["result"] = state["result"]
    if phase == "final":
        view["titles"] = _titles(state)
    return view

