"""
Habda - a bluffing trivia party game (in the spirit of Psych!).

Every round shows a strange-but-true fact with a blank. Each player writes a
fake answer that sounds true. All fakes are shuffled together with the truth,
and everyone picks the one they believe. Finding the truth earns points; every
friend who falls for your fake earns you points. The last round pays double.

The "friends" pack has no truth at all: the prompt is about one of the players
and the funniest answer (most votes) wins.

Security rules that ARE the game, enforced here and never in the client:
  - the truth never leaves the server before the reveal;
  - option authors are hidden until the reveal;
  - a player cannot pick their own fake.

All player-facing text lives in content/questions.json and locales/ar.json.
This file carries keys only.
"""
from __future__ import annotations

import json
import pathlib
import random
import re
import time
import unicodedata

try:
    from games import party
except ModuleNotFoundError:  # the bank tools load this file on its own
    party = None

HERE = pathlib.Path(__file__).resolve().parent
_CONTENT = json.loads((HERE / "content" / "questions.json").read_text(encoding="utf-8"))
_LOCALE = json.loads((HERE / "locales" / "ar.json").read_text(encoding="utf-8"))

PACKS: dict[str, dict] = {pack["key"]: pack for pack in _CONTENT["packs"]}
MIX = "mix"
FRIENDS = "friends"
ROUND_CHOICES = (5, 7, 10, 15, 20, 30)
DEFAULT_ROUNDS = 7
MIN_SEATS = 3
MAX_SEATS = 16
HINTS = 3
MAX_LIE = 40

WRITE_SECONDS = 75
PICK_SECONDS = 35
REVEAL_BASE = 22.0   # the round summary stays up long enough to read who wrote what
REVEAL_STEP = 3.4

TRUTH_POINTS = 1000
FOOL_POINTS = 500
LAST_MULT = 3          # the last round pays triple, so whoever is behind still has a chance
ERASE_COST = 200       # pay to strike one fake off your own list of options
STREAK_BONUS = 300     # fooling someone two rounds running


class Illegal(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def now() -> float:
    return time.time()


# ============================== text ==============================

_MARKS = re.compile(r"[\u064B-\u065F\u0670\u0640]")
_PUNCT = re.compile(r"[\s\.\,\!\?\u061F\u060C\u061B\-_'\"()\[\]{}:;/\\%\u066A]+")


def normalize(text: str) -> str:
    """Loose form for comparing answers: no diacritics, unified letters."""
    value = unicodedata.normalize("NFKC", str(text or "")).lower()
    value = _MARKS.sub("", value)
    value = (value.replace("\u0623", "\u0627").replace("\u0625", "\u0627")
             .replace("\u0622", "\u0627").replace("\u0671", "\u0627")
             .replace("\u0629", "\u0647").replace("\u0649", "\u064A")
             .replace("\u0624", "\u0648").replace("\u0626", "\u064A"))
    # Arabic-Indic digits to ASCII so 38 and its Arabic form match.
    value = value.translate(str.maketrans("\u0660\u0661\u0662\u0663\u0664\u0665\u0666\u0667\u0668\u0669",
                                          "0123456789"))
    value = _PUNCT.sub("", value)
    return value


def _stem(value: str) -> str:
    """Also match with or without the definite article."""
    return value[2:] if value.startswith("\u0627\u0644") and len(value) > 3 else value


def _same(a: str, b: str) -> bool:
    x, y = normalize(a), normalize(b)
    return bool(x) and (x == y or _stem(x) == _stem(y))


def clean_lie(text: str) -> str:
    value = " ".join(str(text or "").split())[:MAX_LIE].strip()
    return value


# ============================== setup ==============================

def _bot_names() -> list[str]:
    return list(_LOCALE.get("bots") or ["Bot"])


def new_match(people: list[dict], host: int) -> dict:
    """`people`: [{id, name, photo}] humans in the room, in join order."""
    seats = [{"id": p["id"], "name": p["name"], "photo": p.get("photo", ""), "bot": False, "score": 0}
             for p in people[:MAX_SEATS]]
    _fill_bots(seats)
    return {
        "game": "habda",
        "host": host,
        "players": seats,
        "pack": MIX,
        "rounds": DEFAULT_ROUNDS,
        "round": 0,
        "phase": "setup",
        "phase_at": now(),
        "deadline": 0.0,
        "question": None,
        "lies": {},
        "picks": {},
        "ready": [],
        "options": [],
        "result": None,
        "history": [],
        "used": [],
        "bot_due": {},
        "teams": {},
        "team_mode": False,
        "team_picks": {},
        "erased": {},
        "subjects": [],
        "rev": 0,
    }


def _fill_bots(seats: list[dict]) -> None:
    names = [n for n in _bot_names() if n not in {s["name"] for s in seats}]
    random.shuffle(names)
    while len(seats) < MIN_SEATS:
        index = len(seats)
        seats.append({"id": -(200 + index), "name": names.pop() if names else f"Bot {index}",
                      "photo": "", "bot": True, "score": 0})


def seat_of(state: dict, user_id: int) -> int | None:
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot") and seat.get("id") == user_id:
            return index
    return None


def host_seat(state: dict) -> int | None:
    host = seat_of(state, state.get("host", 0))
    if host is not None:
        return host
    for index, seat in enumerate(state["players"]):
        if not seat.get("bot"):
            return index
    return None


def sit(state: dict, person: dict) -> None:
    """A late arrival takes a seat (replacing a bot when there is one)."""
    if seat_of(state, person["id"]) is not None:
        return
    if state["phase"] not in ("setup", "reveal", "final"):
        raise Illegal("waitForRound")
    seat = {"id": person["id"], "name": person["name"], "photo": person.get("photo", ""),
            "bot": False, "score": 0}
    for index, old in enumerate(state["players"]):
        if old.get("bot"):
            seat["score"] = old["score"] if state["phase"] != "setup" else 0
            state["players"][index] = seat
            state["rev"] += 1
            return
    if len(state["players"]) >= MAX_SEATS:
        raise Illegal("full")
    state["players"].append(seat)
    state["rev"] += 1


# ============================== rounds ==============================

def _pool(pack: str) -> list[tuple[str, int]]:
    keys = [k for k, p in PACKS.items() if not p.get("friends")] if pack == MIX else [pack]
    return [(k, i) for k in keys for i in range(len(PACKS[k]["questions"]))]


def _level(state: dict) -> int:
    """The difficulty this round asks for: medium to start, very hard by the last round."""
    share = state["round"] / max(1, state["rounds"])
    return 2 if share <= 0.34 else 3 if share < 1 else 4


def _draw(state: dict) -> dict:
    pool = _pool(state["pack"])
    fresh = [q for q in pool if f"{q[0]}:{q[1]}" not in state["used"]]
    if not fresh:
        state["used"] = []
        fresh = pool
    # Questions carry a difficulty "d" (2 medium, 3 hard, 4 very hard; unmarked ones are medium):
    # the round draws from the closest level still left.
    want = _level(state)
    gap = lambda q: abs(int(PACKS[q[0]]["questions"][q[1]].get("d", 2)) - want)
    best = min(gap(q) for q in fresh)
    key, index = random.choice([q for q in fresh if gap(q) == best])
    state["used"].append(f"{key}:{index}")
    raw = PACKS[key]["questions"][index]
    pack = PACKS[key]
    question = {"pack": key, "text": raw["q"], "truth": raw.get("a", ""),
                "alt": list(raw.get("alt") or []), "lies": list(raw.get("lies") or []),
                "friends": bool(pack.get("friends")), "pic": ""}
    if pack.get("pics"):
        head, _, rest = question["text"].partition(" ")
        question["pic"], question["text"] = head, rest
    if question["friends"]:
        # Everyone at the table gets a turn in the spotlight before anyone gets a second one.
        humans = [s for s in state["players"] if not s.get("bot")] or state["players"]
        used = state.setdefault("subjects", [])
        fresh_people = [s for s in humans if s["id"] not in used]
        if not fresh_people:
            used.clear()
            fresh_people = humans
        last = used[-1] if used else None
        subject = random.choice([s for s in fresh_people if s["id"] != last] or fresh_people)
        used.append(subject["id"])
        question["subject"] = subject["id"]
        question["text"] = question["text"].replace("{p}", subject["name"])
        lines = pack.get("botLines") or ["-"]
        question["lies"] = random.sample(lines, k=min(12, len(lines)))
    return question


def _is_truth(question: dict, text: str) -> bool:
    if question["friends"]:
        return False
    return any(_same(text, candidate) for candidate in [question["truth"], *question["alt"]])


def _begin_round(state: dict) -> None:
    state["round"] += 1
    state["phase"] = "write"
    state["phase_at"] = now()
    state["deadline"] = now() + WRITE_SECONDS
    state["question"] = _draw(state)
    state["lies"] = {}
    state["picks"] = {}
    state["ready"] = []
    state["options"] = []
    state["result"] = None
    state["erased"] = {}
    state["bot_due"] = {str(i): now() + random.uniform(6, 22)
                        for i, s in enumerate(state["players"]) if s.get("bot")}
    state["rev"] += 1


def _open_picks(state: dict) -> None:
    question = state["question"]
    options: list[dict] = []

    def add(text: str, author: int | None, house: bool = False) -> None:
        for option in options:
            if _same(option["text"], text):
                if author is not None and author not in option["authors"]:
                    option["authors"].append(author)
                return
        options.append({"text": text, "truth": False, "house": house,
                        "authors": [] if author is None else [author]})

    for seat_key, text in state["lies"].items():
        add(text, int(seat_key))
    if not question["friends"]:
        options.append({"text": question["truth"], "truth": True, "house": False, "authors": []})
        spare = [lie for lie in question["lies"] if not any(_same(lie, o["text"]) for o in options)]
        random.shuffle(spare)
        while len(options) < 4 and spare:
            add(spare.pop(), None, house=True)
    random.shuffle(options)
    for index, option in enumerate(options):
        option["id"] = index
    state["options"] = options
    state["phase"] = "pick"
    state["phase_at"] = now()
    state["deadline"] = now() + PICK_SECONDS
    state["bot_due"] = {str(i): now() + random.uniform(3, 12)
                        for i, s in enumerate(state["players"]) if s.get("bot")}
    state["rev"] += 1
    # Nothing to choose between (friends round nobody wrote in): skip ahead.
    if len(options) < 2:
        _score(state)


def _score(state: dict) -> None:
    question = state["question"]
    double = state["round"] >= state["rounds"]
    mult = LAST_MULT if double else 1
    gains = {str(i): 0 for i in range(len(state["players"]))}
    fooled = {str(i): 0 for i in range(len(state["players"]))}
    found = []
    items = []
    for option in state["options"]:
        pickers = [int(seat) for seat, choice in state["picks"].items() if choice == option["id"]]
        if option["truth"]:
            for seat in pickers:
                gains[str(seat)] += TRUTH_POINTS * mult
                found.append(seat)
        else:
            for author in option["authors"]:
                victims = [p for p in pickers if p != author]
                gains[str(author)] += FOOL_POINTS * mult * len(victims)
                fooled[str(author)] += len(victims)
        items.append({"id": option["id"], "text": option["text"], "truth": option["truth"], "house": option["house"],
                      "authors": option["authors"], "pickers": pickers, "laughs": []})
    # Fooling someone two rounds running pays a bonus.
    last = state["history"][-1]["fooled"] if state["history"] else {}
    streak = [int(seat) for seat, n in fooled.items() if n > 0 and int(last.get(seat, 0)) > 0]
    for seat in streak:
        gains[str(seat)] += STREAK_BONUS
    for seat, gain in gains.items():
        state["players"][int(seat)]["score"] += gain
    # Reveal order: fakes nobody fell for are skipped, then fooled ones from
    # least to most victims, and the truth last.
    shown = sorted((i for i in items if not i["truth"] and i["pickers"]), key=lambda i: len(i["pickers"]))
    truth = [i for i in items if i["truth"]]
    state["result"] = {"items": shown + truth, "quiet": [i for i in items if not i["truth"] and not i["pickers"]],
                       "gains": gains, "double": double, "mult": mult, "friends": question["friends"],
                       "truth": question["truth"], "streak": streak}
    names = lambda seats: [state["players"][s]["name"] for s in seats if 0 <= s < len(state["players"])]
    lies = [{"text": i["text"], "names": names(i["authors"]), "authors": list(i["authors"]),
             "victims": len([p for p in i["pickers"] if p not in i["authors"]]), "laughs": 0}
            for i in items if not i["truth"] and i["authors"]]
    duped = {str(seat): choice for seat, choice in state["picks"].items()
             if any(o["id"] == choice and not o["truth"] for o in state["options"])}
    state["history"].append({"round": state["round"], "fooled": fooled, "found": found, "lies": lies,
                             "question": question["text"], "duped": sorted(int(s) for s in duped),
                             "picked": sorted(int(s) for s in state["picks"]),
                             "wrote": sorted({a for o in state["options"] for a in o["authors"]}),
                             "friends": question["friends"]})
    steps = len(shown) + len(truth)
    state["phase"] = "reveal"
    state["phase_at"] = now()
    state["deadline"] = now() + REVEAL_BASE + REVEAL_STEP * steps
    state["ready"] = []
    state["rev"] += 1


def _finish(state: dict) -> None:
    state["phase"] = "final"
    state["phase_at"] = now()
    state["deadline"] = 0.0
    state["rev"] += 1


def _after_reveal(state: dict) -> None:
    if state["round"] >= state["rounds"]:
        _finish(state)
    else:
        _begin_round(state)


def _team_view(state: dict) -> dict[str, int]:
    """Who is on which team, by seat. Choices are kept by player id, because seats shift when
    bots come and go; anyone not placed yet joins the smaller team, people before bots."""
    picks = state.get("team_picks") or {}
    out: dict[str, int] = {}
    counts = [0, 0]
    players = list(enumerate(state["players"]))
    for seat, player in players:
        team = picks.get(str(player["id"]))
        if team in (0, 1):
            out[str(seat)] = team
            counts[team] += 1
    for seat, player in sorted(players, key=lambda item: bool(item[1].get("bot"))):
        if str(seat) in out:
            continue
        team = 0 if counts[0] <= counts[1] else 1
        out[str(seat)] = team
        counts[team] += 1
    return out


def _keep_team_view(state: dict) -> None:
    """Writes the teams as they stand, so moving one player never reshuffles another."""
    view = _team_view(state)
    state["team_picks"] = {str(p["id"]): view[str(i)] for i, p in enumerate(state["players"])}


def _shuffle_teams(state: dict) -> None:
    """Two balanced random teams, people spread across both before the bots."""
    people = [p for p in state["players"] if not p.get("bot")]
    bots = [p for p in state["players"] if p.get("bot")]
    random.shuffle(people)
    random.shuffle(bots)
    state["team_picks"] = {str(p["id"]): n % 2 for n, p in enumerate(people + bots)}


def _split_teams(state: dict) -> None:
    """Fixes the teams chosen in setup for the match."""
    state["teams"] = _team_view(state) if state.get("team_mode") else {}
    if state["teams"] and len(state["players"]) > 1 and len(set(state["teams"].values())) < 2:
        state["teams"] = {}
        raise Illegal("teamEmpty")


def _mates(state: dict, seat: int) -> list[int]:
    """من يكتب هبدةً واحدة معك: فريقك كله في وضع الفرق، وأنت وحدك في غيره."""
    teams = state.get("teams") or {}
    if not state.get("team_mode") or str(seat) not in teams:
        return [seat]
    return [int(s) for s, team in teams.items() if team == teams[str(seat)]]


def _humans(state: dict) -> list[int]:
    return [i for i, s in enumerate(state["players"]) if not s.get("bot")]


# ============================== bots on / off ==============================
#
# The host decides whether bots play. Off: they leave at once, even mid-turn, and every
# record keyed by seat number is renumbered so nothing points at a seat that is gone.

def _renumber(keep: list[int]) -> dict[int, int]:
    return {old: new for new, old in enumerate(keep)}


def _keys(table: dict, new: dict[int, int]) -> dict:
    out = {}
    for key, value in (table or {}).items():
        try:
            seat = int(key)
        except (TypeError, ValueError):
            continue
        if seat in new:
            out[str(new[seat])] = value
    return out


def _seats(items, new: dict[int, int]) -> list:
    return [new[i] for i in (items or []) if isinstance(i, int) and i in new]


def set_bots(state: dict, on: bool) -> None:
    """On: bots fill the table up to three seats and play from the next round. Off: every bot leaves now."""
    state["no_bots"] = not on
    if on:
        _fill_bots(state["players"])
        state["rev"] += 1
        return
    keep = [i for i, p in enumerate(state["players"]) if not p.get("bot")]
    if len(keep) == len(state["players"]):
        return
    new = _renumber(keep)
    state["players"] = [state["players"][i] for i in keep]
    for key in ("lies", "picks", "bot_due", "teams", "erased"):
        state[key] = _keys(state.get(key), new)
    state["ready"] = _seats(state.get("ready"), new)
    # A lie only a bot wrote leaves with it; a lie a person also wrote stays theirs.
    options = []
    for option in state.get("options", []):
        authors = _seats(option.get("authors"), new)
        if authors or option.get("truth") or option.get("house"):
            options.append({**option, "authors": authors})
    state["options"] = options
    result = state.get("result")
    if result:
        result["gains"] = _keys(result.get("gains"), new)
        for group in ("items", "quiet"):
            for item in result.get(group, []):
                item["authors"] = _seats(item.get("authors"), new)
                item["pickers"] = _seats(item.get("pickers"), new)
                item["laughs"] = _seats(item.get("laughs"), new)
    for entry in state.get("history", []):
        entry["fooled"] = _keys(entry.get("fooled"), new)
        entry["found"] = _seats(entry.get("found"), new)
        for key in ("duped", "picked", "wrote"):
            entry[key] = _seats(entry.get(key), new)
    state["rev"] += 1


# ============================== actions ==============================

def _back_to_setup(state: dict) -> None:
    """A clean table on the setup page; the pack, the rounds and the chosen teams stay."""
    for player in state["players"]:
        player["score"] = 0
    state.update(round=0, history=[], phase="setup", phase_at=now(), deadline=0.0, question=None, options=[],
                 result=None, lies={}, picks={}, ready=[], teams={}, erased={}, bot_due={})
    state["rev"] += 1


def act(state: dict, seat: int | None, action: str, body: dict) -> None:
    phase = state["phase"]
    if seat is None:
        raise Illegal("notSeated")
    is_host = seat == host_seat(state)

    if action == "setup":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        pack = str(body.get("pack") or state["pack"])
        if pack != MIX and pack not in PACKS:
            raise Illegal("badPack")
        try:
            rounds = int(body.get("rounds") or state["rounds"])
        except (TypeError, ValueError):
            rounds = state["rounds"]
        state["pack"] = pack
        state["rounds"] = rounds if rounds in ROUND_CHOICES else DEFAULT_ROUNDS
        if "teams" in body:
            state["team_mode"] = bool(body.get("teams"))
        state["rev"] += 1
        return

    if action == "botset":
        if not is_host:
            raise Illegal("notHost")
        party.set_roster(state, body.get("names") or [], MAX_SEATS)
        return

    if action in ("teamset", "teamshuffle"):
        if phase != "setup":
            raise Illegal("tooLate")
        if not state.get("team_mode"):
            raise Illegal("tooLate")
        if action == "teamshuffle":
            if not is_host:
                raise Illegal("notHost")
            _shuffle_teams(state)
            state["rev"] += 1
            return
        try:
            target, team = int(body.get("player")), int(body.get("team"))
        except (TypeError, ValueError):
            raise Illegal("badMove")
        if team not in (0, 1) or not any(p["id"] == target for p in state["players"]):
            raise Illegal("badMove")
        # The host places anyone, bots included; a player can only move themselves.
        if not is_host and target != state["players"][seat]["id"]:
            raise Illegal("notHost")
        _keep_team_view(state)
        state["team_picks"][str(target)] = team
        state["rev"] += 1
        return

    if action == "cancel":
        if not is_host:
            raise Illegal("notHost")
        if phase not in ("write", "pick", "reveal"):
            raise Illegal("tooLate")
        _back_to_setup(state)
        return

    if action == "go":
        if not is_host:
            raise Illegal("notHost")
        if phase != "setup":
            raise Illegal("tooLate")
        _split_teams(state)
        _begin_round(state)
        return

    if action == "again":
        if not is_host:
            raise Illegal("notHost")
        if phase == "setup":
            raise Illegal("tooLate")
        _back_to_setup(state)
        return

    if action == "lie":
        if phase != "write":
            raise Illegal("tooLate")
        text = clean_lie(body.get("text", ""))
        if not text:
            raise Illegal("emptyLie")
        if _is_truth(state["question"], text):
            raise Illegal("thatsTrue")
        for mate in _mates(state, seat):
            state["lies"][str(mate)] = text
        state["rev"] += 1
        return

    if action == "erase":
        if phase != "pick":
            raise Illegal("tooLate")
        mine = state["erased"].setdefault(str(seat), [])
        if mine:
            raise Illegal("onceOnly")
        if state["players"][seat]["score"] < ERASE_COST:
            raise Illegal("tooPoor")
        left = [o for o in state["options"] if o["id"] not in mine]
        fakes = [o for o in left if not o["truth"] and seat not in o["authors"]]
        if len(left) <= 2 or not fakes or state["question"]["friends"]:
            raise Illegal("notNow")
        gone = random.choice(fakes)
        mine.append(gone["id"])
        state["players"][seat]["score"] -= ERASE_COST
        if state["picks"].get(str(seat)) == gone["id"]:
            state["picks"].pop(str(seat), None)
        state["rev"] += 1
        return

    if action == "laugh":
        if phase != "reveal" or not state["result"]:
            raise Illegal("tooLate")
        try:
            choice = int(body.get("option"))
        except (TypeError, ValueError):
            raise Illegal("badOption") from None
        result = state["result"]
        item = next((i for i in result["items"] + result["quiet"] if i.get("id") == choice and not i["truth"]), None)
        if item is None:
            raise Illegal("badOption")
        if seat in item["authors"]:
            raise Illegal("ownLie")
        laughs = item.setdefault("laughs", [])
        if seat in laughs:
            laughs.remove(seat)
        else:
            laughs.append(seat)
        for lie in state["history"][-1].get("lies", []) if state["history"] else []:
            if lie["text"] == item["text"]:
                lie["laughs"] = len(laughs)
        state["rev"] += 1
        return

    if action == "pick":
        if phase != "pick":
            raise Illegal("tooLate")
        try:
            choice = int(body.get("option"))
        except (TypeError, ValueError):
            raise Illegal("badOption") from None
        option = next((o for o in state["options"] if o["id"] == choice), None)
        if option is None:
            raise Illegal("badOption")
        if seat in option["authors"]:
            raise Illegal("ownLie")
        if choice in state["erased"].get(str(seat), []):
            raise Illegal("badOption")
        state["picks"][str(seat)] = choice
        state["rev"] += 1
        return

    if action == "ready":
        if phase != "reveal":
            return
        if seat not in state["ready"]:
            state["ready"].append(seat)
            state["rev"] += 1
        return

    raise Illegal("badAction")


# ============================== the clock and the bots ==============================

def _bot_lie(state: dict, seat: int) -> str | None:
    """البوت يتعلّم: كلما تقدّمت المباراة اختار من الهبدات أقربها شبهًا بالحقيقة."""
    taken = list(state["lies"].values())
    question = state["question"]
    pool = [lie for lie in question["lies"]
            if not any(_same(lie, t) for t in taken) and not _is_truth(question, lie)]
    if not pool:
        return None
    if state["round"] > state["rounds"] / 2 and question["truth"]:
        truth = question["truth"]
        digit = any(ch.isdigit() for ch in truth)
        pool.sort(key=lambda lie: (any(ch.isdigit() for ch in lie) != digit, abs(len(lie) - len(truth))))
        return pool[0] if random.random() < 0.7 else random.choice(pool)
    return pool[0]


def _bot_pick(state: dict, seat: int) -> int | None:
    choices = [o for o in state["options"] if seat not in o["authors"]]
    if not choices:
        return None
    choices = [o for o in choices if o["id"] not in state["erased"].get(str(seat), [])] or choices
    truth = [o for o in choices if o["truth"]]
    sharp = min(0.72, 0.32 + 0.05 * state["round"])
    if truth and random.random() < sharp:
        return truth[0]["id"]
    others = [o for o in choices if not o["truth"]] or choices
    return random.choice(others)["id"]


def step(state: dict) -> bool:
    """Advance the clock. Returns True while there is something to wait for."""
    phase = state["phase"]
    if phase in ("setup", "final"):
        return False
    t = now()
    humans = _humans(state)

    if phase == "write":
        humans_done = all(str(i) in state["lies"] for i in humans)
        # A bot whose team already has its lie has nothing left to write.
        state["bot_due"] = {k: v for k, v in state["bot_due"].items() if k not in state["lies"]}
        for key, due in list(state["bot_due"].items()):
            if key not in state["lies"] and (t >= due or humans_done or t >= state["deadline"]):
                lie = _bot_lie(state, int(key))
                if lie:
                    for mate in _mates(state, int(key)):
                        state["lies"].setdefault(str(mate), lie)
                    state["rev"] += 1
                state["bot_due"].pop(key, None)
                return True           # one bot at a time, so answers trickle in
        if (humans_done and not state["bot_due"]) or t >= state["deadline"]:
            _open_picks(state)
        return True

    if phase == "pick":
        humans_done = all(str(i) in state["picks"] for i in humans)
        for key, due in list(state["bot_due"].items()):
            if key not in state["picks"] and (t >= due or humans_done or t >= state["deadline"]):
                choice = _bot_pick(state, int(key))
                if choice is not None:
                    state["picks"][key] = choice
                    state["rev"] += 1
                state["bot_due"].pop(key, None)
                return True
        if (humans_done and not state["bot_due"]) or t >= state["deadline"]:
            _score(state)
        return True

    if phase == "reveal":
        # Everyone pressed "ready" once the reveal played at least a little.
        all_ready = humans and all(i in state["ready"] for i in humans) and t - state["phase_at"] > 3
        if all_ready or t >= state["deadline"]:
            _after_reveal(state)
        return True

    return False


# ============================== view ==============================

def _awards(state: dict) -> dict:
    fooled = {i: 0 for i in range(len(state["players"]))}
    found = {i: 0 for i in range(len(state["players"]))}
    for entry in state["history"]:
        for seat, count in entry["fooled"].items():
            fooled[int(seat)] += count
        for seat in entry["found"]:
            found[seat] += 1
    liar = max(fooled, key=lambda s: fooled[s]) if fooled else None
    sharp = max(found, key=lambda s: found[s]) if found else None
    laughs: dict[str, int] = {}
    best = []
    for entry in state["history"]:
        for lie in entry.get("lies", []):
            for name in lie["names"]:
                laughs[name] = laughs.get(name, 0) + int(lie["laughs"])
            best.append(lie)
    best.sort(key=lambda lie: (lie["victims"], lie["laughs"]), reverse=True)
    funny = max(laughs, key=laughs.get) if laughs else None
    return {
        "funny": funny if funny and laughs[funny] > 0 else None,
        "funnyCount": laughs.get(funny, 0) if funny else 0,
        "best": [{"text": l["text"], "names": l["names"], "victims": l["victims"], "laughs": l["laughs"]}
                 for l in best if l["victims"] > 0 or l["laughs"] > 0][:3],
        "liar": liar if liar is not None and fooled[liar] > 0 else None,
        "liarCount": fooled.get(liar, 0) if liar is not None else 0,
        "sharp": sharp if sharp is not None and found[sharp] > 0 else None,
        "sharpCount": found.get(sharp, 0) if sharp is not None else 0,
        "titles": _titles(state, fooled, found, laughs),
    }


def _titles(state: dict, fooled: dict, found: dict, laughs: dict) -> list[dict]:
    """One title for every player at the end, so nobody leaves the table without a name."""
    seats = list(range(len(state["players"])))
    duped = {s: 0 for s in seats}
    picked = {s: 0 for s in seats}
    wrote = {s: 0 for s in seats}
    for entry in state["history"]:
        if entry.get("friends"):
            continue
        for s in entry.get("duped", []):
            duped[s] = duped.get(s, 0) + 1
        for s in entry.get("picked", []):
            picked[s] = picked.get(s, 0) + 1
        for s in entry.get("wrote", []):
            wrote[s] = wrote.get(s, 0) + 1
    out: dict[int, tuple[str, int]] = {}
    ranked = sorted(seats, key=lambda s: state["players"][s]["score"], reverse=True)

    def give(seat, key: str, count: int = 0) -> None:
        if seat is not None and seat not in out:
            out[seat] = (key, count)

    if ranked and state["players"][ranked[0]]["score"] > 0:
        give(ranked[0], "champion", state["players"][ranked[0]]["score"])
    best_liar = max(seats, key=lambda s: fooled.get(s, 0), default=None)
    if best_liar is not None and fooled.get(best_liar, 0) > 0:
        give(best_liar, "liar", fooled[best_liar])
    names = {p["name"]: i for i, p in enumerate(state["players"])}
    funny = max(laughs, key=laughs.get) if laughs else None
    if funny and laughs[funny] > 0:
        give(names.get(funny), "funny", laughs[funny])
    solid = [s for s in seats if picked.get(s, 0) >= 2 and duped.get(s, 0) == 0]
    for s in solid:
        give(s, "solid", picked[s])
    sharp = max(seats, key=lambda s: found.get(s, 0), default=None)
    if sharp is not None and found.get(sharp, 0) > 0:
        give(sharp, "sharp", found[sharp])
    gullible = max(seats, key=lambda s: duped.get(s, 0), default=None)
    if gullible is not None and duped.get(gullible, 0) >= 2:
        give(gullible, "gullible", duped[gullible])
    for s in seats:
        if wrote.get(s, 0) >= 2 and fooled.get(s, 0) == 0:
            give(s, "honest", wrote[s])
    for s in seats:
        give(s, "player")
    return [{"seat": s, "key": out[s][0], "count": out[s][1]} for s in seats]


def _hints(state: dict, seat: int) -> list[str]:
    """Three ideas for a player with no idea: never the truth, never a lie already written,
    and the same three on every refresh of the same round."""
    question = state["question"]
    taken = list(state["lies"].values())
    pool = [lie for lie in question.get("lies", [])
            if not _is_truth(question, lie) and not any(_same(lie, t) for t in taken)]
    pick = random.Random(f"{state['round']}:{seat}:{question['text']}")
    pick.shuffle(pool)
    return pool[:HINTS]


def view_for(state: dict, seat: int | None) -> dict:
    phase = state["phase"]
    t = now()
    question = state["question"]
    players = []
    for index, player in enumerate(state["players"]):
        if phase == "write":
            done = str(index) in state["lies"]
        elif phase == "pick":
            done = str(index) in state["picks"]
        elif phase == "reveal":
            done = index in state["ready"]
        else:
            done = False
        players.append({"id": player["id"], "name": player["name"], "photo": player.get("photo", ""),
                        "bot": bool(player.get("bot")), "score": player["score"], "done": done})

    view = {
        "game": "habda",
        "phase": phase,
        "seat": seat,
        "isHost": seat is not None and seat == host_seat(state),
        "hostName": state["players"][host_seat(state)]["name"] if host_seat(state) is not None else "",
        "players": players,
        "pack": state["pack"],
        "rounds": state["rounds"],
        "round": state["round"],
        "endsIn": max(0, int((state["deadline"] - t) * 1000)) if state["deadline"] else 0,
        "elapsed": int((t - state["phase_at"]) * 1000),
        "rev": state["rev"],
        "double": state["round"] >= state["rounds"] and phase in ("write", "pick", "reveal"),
        "mult": LAST_MULT,
        "teamMode": bool(state.get("team_mode")),
        "teams": _team_view(state) if phase == "setup" and state.get("team_mode")
                 else {str(k): v for k, v in (state.get("teams") or {}).items()},
        "roster": list(party.BOT_NAMES),
        "eraseCost": ERASE_COST,
    }
    if phase == "setup":
        view["packs"] = [{"key": MIX, "label": _LOCALE["mix"]["label"], "blurb": _LOCALE["mix"]["blurb"],
                          "art": "mix", "count": len(_pool(MIX))}] + [
            {"key": p["key"], "label": p["label"], "blurb": p.get("blurb", ""), "art": p.get("art", p["key"]),
             "count": len(p["questions"]), "friends": bool(p.get("friends"))}
            for p in _CONTENT["packs"]]
        view["roundChoices"] = list(ROUND_CHOICES)
    if question and phase in ("write", "pick", "reveal"):
        pack = PACKS.get(question["pack"], {})
        view["question"] = {"text": question["text"], "pack": question["pack"], "pic": question.get("pic", ""),
                            "packLabel": pack.get("label", ""), "friends": question["friends"]}
        if seat is not None and str(seat) in state["lies"]:
            view["myLie"] = state["lies"][str(seat)]
        if phase == "write" and seat is not None:
            view["hints"] = _hints(state, seat)
    if phase == "pick":
        # Texts only: which is true and who wrote what stays here.
        erased = state["erased"].get(str(seat), []) if seat is not None else []
        view["options"] = [{"id": o["id"], "text": o["text"], "mine": seat is not None and seat in o["authors"]}
                           for o in state["options"] if o["id"] not in erased]
        view["erasedOne"] = bool(erased)
        if seat is not None and str(seat) in state["picks"]:
            view["myPick"] = state["picks"][str(seat)]
    if phase == "reveal" and state["result"]:
        view["result"] = state["result"]
        view["myPick"] = state["picks"].get(str(seat)) if seat is not None else None
    if phase == "final":
        view["awards"] = _awards(state)
    return view

